INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41878506337', 'Cabo Carregador USB para Lightning Carga Rápida 4.8A Reforçado Kapbom', 'Cabo Carregador USB para Lightning Carga Rápida 4.8A Reforçado Kapbom KA-0332-5G Cabo desenvolvido para quem precisa de carregamento rápido, segurança e alta durabilidade no uso diário. Compatível com iPhones com entrada Lightning, oferece encaixe firme, conexão estável e desempenho confiável para carregar seu aparelho em casa, no trabalho ou em viagens. Sua estrutura reforçada ajuda a resistir a dobras e torções, tornando o cabo ideal para uso intenso sem comprometer a eficiência do carregamento. ⭐ BENEFÍCIOS NO USO DIÁRIO • Carregamento rápido com corrente de até 4.8A • Conector Lightning com encaixe firme e seguro • Cabo reforçado, mais resistente ao uso contínuo • Conexão estável, sem quedas de energia • Comprimento ideal para uso no dia a dia • Compatível com diversos modelos de iPhone • Excelente custo-benefício dentro da categoria ⚙️ INFORMAÇÕES DO PRODUTO • Marca: Kapbom • Modelo: KA-0332-5G • Tipo: Cabo USB para Lightning • Corrente máxima: Até 4.8A • Função: Carregamento rápido • Comprimento: 1 metro • Estrutura: Cabo reforçado de alta resistência • Cor: Preto • Compatibilidade: iPhone 7, 8, X, XR, XS, 11, 12, 13, 14 (Mini, Pro e Pro Max) ❓ DÚVIDAS FREQUENTES • Funciona em todos os iPhones com entrada Lightning? Sim. Compatível do iPhone 7 ao iPhone 14, incluindo versões Mini, Pro e Pro Max. • Suporta carga rápida? Sim. Suporta corrente de até 4.8A para carregamento mais eficiente. • O cabo é resistente? Sim. Possui estrutura reforçada, ideal para uso diário intenso. Garanta já o seu com envio rápido e compra segura pela Shopee. Qualquer dúvida, estamos à disposição no chat.', 49.9, 12.9, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/br-11134207-820lb-mqbzqk06rdog8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F410522123%2F41878506337', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094481263', 'Base Liquida 32ml Sérum Wet N Wild Bare Focus Niacinamida Skin Tint Cobertura Leve A Média', 'Base Sérum Bare Focus Niacinamide Skin Tint Wet n Wild A Bare Focus Niacinamide Skin Tint combina maquiagem e cuidados com a pele em uma única fórmula. Desenvolvida para oferecer cobertura leve a média, construível, ela uniformiza o tom da pele enquanto proporciona hidratação e um acabamento acetinado com aparência natural. Sua textura leve oferece conforto durante o uso diário, sem deixar sensação pesada. Sua fórmula reúne ativos conhecidos por seus benefícios para a pele, tornando esta skin tint uma excelente opção para quem busca um visual natural sem abrir mão do cuidado facial. Principais benefícios: Cobertura leve a média com possibilidade de construção de camadas Uniformiza o tom da pele de forma natural Disfarça vermelhidão e pequenas imperfeições Acabamento acetinado com aspecto saudável Textura leve e confortável Não deixa sensação pesada Ideal para uso diário Produto Cruelty-Free Ativos da fórmula: 5% de Niacinamida: Auxilia na uniformização da aparência da pele Ajuda a suavizar pequenas imperfeições Contribui para uma pele com aspecto mais equilibrado Ácido Hialurônico: Promove hidratação Ajuda a manter a pele confortável durante o uso Extrato de Peônia: Contribui para uma aparência mais suave e iluminada Vitamina E: Ingrediente com ação antioxidante que auxilia na proteção da pele contra os efeitos dos radicais livres. Diferenciais: Base sérum com tratamento e maquiagem Cobertura construível sem perder o aspecto natural Acabamento acetinado Fórmula leve Excelente espalhabilidade Fácil aplicação com dedos, pincel ou esponja Desenvolvida para proporcionar aparência de "segunda pele" Como usar: Aplique sobre a pele limpa e hidratada. Distribua pequenas quantidades do centro do rosto para as extremidades. Espalhe utilizando os dedos, pincel ou esponja. Caso deseje maior cobertura, aplique novas camadas nas áreas necessárias. Para um acabamento mais sequinho, sele levemente a zona T com pó facial. Indicado para: Uso diário Maquiagem natural Quem prefere cobertura leve ou média Quem procura acabamento confortável Todos os tipos de pele, especialmente para quem deseja um efeito de pele saudável Resultado: Pele mais uniforme Aspecto naturalmente radiante Acabamento acetinado Cobertura confortável Aparência de pele saudável Características: Marca: Wet n Wild Linha: Bare Focus Tipo: Skin Tint / Base Sérum Cobertura: Leve a média Cobertura construível Acabamento: Acetinado Contém 5% de Niacinamida Contém Ácido Hialurônico Contém Extrato de Peônia Contém Vitamina E Cruelty-Free', 186.54, 138.04, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-824h7-mfcq9c3yrpji22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F572166540%2F22094481263', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46401026809', 'Boneco Funko Pop! Disney Princesas de Natal - Anna', 'Entre no clima natalino com o Boneco Funko Pop! Anna! Inspirada no especial Olaf em Uma Nova Aventura Congelante de Frozen, Anna aparece com seu elegante traje de inverno, pronta para celebrar as festas com charme e alegria. Com aproximadamente 11 centímetros de altura, esta figura de vinil é perfeita para fãs da princesa e colecionadores que querem adicionar um toque festivo e encantador à coleção Disney. Uma peça indispensável para iluminar sua estante nesta temporada!', 149.99, 149.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-824h4-me0j0h02ypl251', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289869635%2F46401026809', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
