INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206326659', 'Coxim Torque Superior Direito Honda New Civic 2006 2007 2008', 'Obs: Os valores do anuncio são apenas para pessoa física, consumo próprio. Pessoa jurídica fora do estado de SP é preciso pagar antecipado a SUBSTITUIÇÃO TRIBUTARIA, não faça compras com CNPJ sem antes se informar sobre os valores desses impostos!!! TODOS OS NOSSOS PRODUTOS ACOMPANHAM NOTA FISCAL SÓ TRABALHAMOS COM PRODUTO NOVO. Descrição do Produto Coxim Traseiro do Motor Superior Direito Cambio MecanicoHonda New Civic Valor: Unitário Aplicação NEW CIVIC - ANO 2006 ATÉ 2011 Especificação Técnica Código: ACX07010 Tipo:CoximTraseiro do Motor Superior Direito Cambio Mecanico Garantia: 3 meses Referencia 50880SNAA02 O Coxim do motor é uma peça feita de borracha e metal, tendo à utilidade de tirar à vibração do chassi do carro. Eles ficam em pontos estratégicos e especificos para conseguir realizar essa função. Temos ele presente no motor, escapamento e câmbio. Ficar com o carro se tremendo inteiro não é legal e pode também prejudicar outros componentes.', 184.08, 176.72, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-8262x-mlgp25q565tv01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1599461548%2F58206326659', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
