INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492441810', 'Broca 6mm Bosch para Porcelanato HEX-9 Hard Ceramic Expert em Widea', 'Broca Para Porcelanato HardCeramic 6x90mm Bosch Expert Descrição do produto: - Como azulejos de porcelanato se tornaram maiores e mais resistentes, fazer furos neles tornou-se muito exigente para as brocas. Foi por isso que a Bosch desenvolveu a broca EXPERT HardCeramic, que é capaz de perfurar cerâmica dura com muito mais durabilidade e sem lubrificante ou refrigeração. Possui Carbide Technology: o metal duro integrado à ponta da broca que permite até 10x mais durabilidade em relação à Bosch CYL-9 Ceramic. Vantagens: - Haste hexagonal para uma conexão segura e máxima transmissão de torque em mandris de castanha e porta-ferramentas hexagonais internos de ¼"; - Permite a perfuração de materiais duros sem danificá-lo graças à sua ponta centralizadora ativa; - O design da ponta permite uma menor geração de calor e possibilita a realização de furos sem umidade; - Sua afiação precisa garante um corte agressivo sem perder a estabilidade; - Para medidas acima de 10mm de diâmetro, é recomendado iniciar o furo com uma broca de 6mm; - Uso com 6 meses de garantia Bosch. Características: - Cor: Cinza e azul; - Acabamento do acessório: Aço, Carbeto de Tungstênio (widea); - Tipo de embalagem: Blister com furo auto-serviço; - Uso indicado: Porcelanato, vidros, telhas, pedras naturais; - Para quais ferramentas se aplica: Furadeiras e Parafusadeiras sem impacto; - Público Alvo: Azulejistas, Encanadores, Vidraceiros, Telhadistas, Pedreiros, Instaladores em geral. Dados Técnicos: - Código de Referência: 2 608 900 590; - Diâmetro: 6 mm; - Comprimento total: 90 mm; - Encaixe: Hexagonal; - Dimensões da embalagem (CxLxA): 18x 4,1 x 0,8 cm; - Peso: 0,030 Kg. Componentes incluídos na embalagem: - 01 Broca para porcelanato EXPERT HEX-9 Hard Ceramic 6x90mm.', 68.0, 47.6, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbcrqzmwwgs982', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397583038%2F22492441810', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893062548', 'Capa Case Capinha Carteira Dual para iPhone 14 Pro Porta-Cartão, Proteção Reforçada - Gshield', 'A Capa Carteira Dual para iPhone 14 Pro é a fusão de proteção e praticidade! Além de proteger o seu iPhone 14 Pro, a Capa Carteira Dual da Gshield oferece espaço para seus cartões essenciais e dinheiro, combinando a conveniência de uma carteira com a funcionalidade de uma capa de proteção. Fabricada com materiais de alta qualidade, a Capa Carteira Dual não só protege contra arranhões e quedas, mas também mantém uma aparência elegante ao longo do tempo. A estrutura durável envolve completamente o seu celular, garantindo proteção contra impactos, arranhões e sujeira. Bordas elevadas também protegem a tela e a câmera contra danos acidentais. Além disso, os recortes precisos proporcionam acesso fácil a todas as portas, botões e funções do seu iPhone 14 Pro sem a necessidade de remover a capa. Eleve a praticidade e a proteção do seu iPhone 14 Pro com a Capa Carteira Dual da Gshield, a escolha ideal para quem busca funcionalidade sem abdicar do estilo. ESPECIFICAÇÕES - Material: Polipropileno de alta densidade - Não Amarela - Marca: Gshield - Dimensões: Dimensões exatas do aparelho - Proteção: Contra impactos e riscos à tela - Certificações: Us Military COMPATIBILIDADE - iPhone 14 Pro ITENS INCLUSOS - 1x Capa protetora', 142.97, 142.97, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7rdvz-m1fj42p4fxr259', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23893062548', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
