INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23891806909', 'Papel De Parede Adesivo Azulejo Mármore Cozinha Lavável Banheiro 1,00m', 'IMPORTANTE!! INFORME A MEDIDA DE SUA PAREDE EM ALTURA E LARGURA PARA QUE POSSAMOS AUXILIAR EM SUA COMPRA. Pedidos em datas diferentes ou separados, possuem cores diferentes, compre tudo em uma única vez em caso de dúvidas fale com nossos atendentes. Papel de parede é um adesivo vinílico, autocolante e lavável. Produzido em impressão digital, sem relevo. Ideal para decoração de sala, quarto, cozinha, banheiro ou outros ambientes. Cada unidade contem a medida de 1,00 metro de altura x 40 centímetros de largura. Papel de parede, autocolante, lavável e fosco. Impresso em material 0.10 Material: PVC vinílico, polimérico fosco e não tem cheiro. Antibactericida, Antimofo e não propaga chamas Dica para aplicação: Limpe o local com um pano úmido, certifique-se de retirar todo o pó da parede para melhor fixação do produto. Abra o papel em uma superfície plana, verifique a emenda do produto e alinhamento do mesmo. Vitalidade da aplicação, média esperada: Interna 5 anos. Externa 2 anos.', 16.9, 13.9, NULL, 'Home & Living > Decoration > Wallpapers & Wall Stickers', 'https://cf.shopee.com.br/file/br-11134207-7qukw-ljoi38961pr790', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322399178%2F23891806909', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
