INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19097739975', 'Carrinho Infantil Quadriciclo Elétrico Pimp Maral Até 23kg com Luz e Som para Crianças 3+', 'O Quadriciclo Elétrico Pimpi Flash Wheels é a opção perfeita para crianças a partir de 2 anos que buscam diversão e novas aventuras. Com um design sofisticado e vibrante, este quadriciclo chama a atenção em qualquer lugar. Com uma velocidade máxima de 5 km/h e a capacidade de suportar até 23 kg, o Pimpi Flash Wheels é ideal para proporcionar momentos de pura alegria em ambientes internos e externos. Além disso, é fácil de montar, assegurando que a diversão comece rapidamente. A sua construção robusta e as dimensões de embalagem compactas facilitam o transporte e armazenamento. O quadriciclo é leve, pesando 7.190 g, tornando-o prático para levar em passeios em família. Experimente a liberdade que o Quadriciclo Elétrico Pimpi Flash Wheels oferece e transforme o tempo de brincadeira em uma experiência memorável para seus filhos. Características do Produto: - Alcança uma velocidade máxima de 5km/h - Com luzes e sons - Idade mínima recomendada: 2 anos - Momentos de diversão garantidos - A duração da bateria depende do uso que se dê ao produto Especificações do Produto: - Marca: Maral - Modelo: Pimpi Flash Wheels - Cor: Rosa - Peso máximo suportado: 23 kg - Velocidade máxima: 5 km/h - Idade mínima recomendada: 2 anos Itens inclusos: - Quadriciclo Elétrico Pimpi Flash Wheels - Carregador - Manual de Instruções', 599.99, 569.9, NULL, 'Mom & Baby > Baby Travel Essentials > Strollers & Travel Systems', 'https://cf.shopee.com.br/file/br-11134207-820l7-mqer08l8nx8i2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F751907905%2F19097739975', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
