INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794939040', 'Cream Cheese Tradicional Danubio', 'O Cream Cheese Tradicional Danubio é cremoso, equilibrado e com o verdadeiro sabor do cream cheese, ideal para receitas doces e salgadas. Elaborado com leite pasteurizado, passa por processo de ultrafiltração, resultando em um produto leve e saudável. Perfeito para preparar tortas, cheesecakes, recheios e molhos. Experimente também com torradas e canapés. * Não contém glúten * Contém leite e derivados * Sem aromatizantes artificiais * Manter refrigerado entre 1°C e 10°C', 14.79, 13.3, NULL, 'Food & Beverages > Dairy & Eggs > Others', 'https://cf.shopee.com.br/file/sg-11134201-825b5-mqnelgl3ka9uea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555024%2F23794939040', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259449910', 'Lacta Intense 70% Cacau Chocolate', 'O novo chocolate Lacta Intense 70% original possui alto teor de cacau sem perder a cremosidade do chocolate Lacta que você já conhece. É uma experiência única no segmento de chocolates amargos. Possui o sabor intenso do cacau combinando com uma maciez irresistível, derretendo lentamente na boca e fazendo cada momento delicioso durar ainda mais. Além de toda a deliciosidade, este chocolate é feito de cacau sustentável, ajudando o meio ambiente. Impossível não se apaixonar! Aproveite e conheça toda a linha de produtos Lacta Intense.', 19.49, 17.53, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-8259a-mqnelcm1mwpabc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555024%2F58259449910', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498451902', 'Cilindro Roda Traseiro Pampa 1982 a 1996 Ate 6448', 'Descrição: O Cilindro de roda ATE 6448 é uma peça que serve na posição Traseiro, lados Direito / Esquerdo do veículo FORD PAMPA. Confira abaixo as especificações e aplicações detalhadas. Atenção: EMBALAGEM COM 1 UNIDADE Especificações Técnicas: - Diâmetro externo: 19,05 mm - Lado: DIREITO / ESQUERDO - Posição: TRASEIRO Aplicação: - FORD PAMPA L 1.6 L 8V SOHC L4 1983 a 1996; - FORD PAMPA STD 1.6 L 8V SOHC L4 1982 a 1996; Sobre o Peça Aí: Com o Peça Aí, você acha a peça certa para cada carro e compra num só lugar. É o maior estoque digital de peças do país! São mais de 100 mil itens originais e de reposição à sua disposição. Importante: • Dúvidas: Caso tenha qualquer dúvida sobre as aplicações do produto, entre em contato conosco. • Instalação Profissional: Recomendamos que a instalação do produto seja realizada por profissionais especializados. • Responsabilidade: Não nos responsabilizamos por montagens mal realizadas e equívocos de instalação." • Produto novo, original e com nota fiscal.', 65.91, 65.91, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Wheels', 'https://cf.shopee.com.br/file/sg-11134201-7rfgd-m96ha3qbhwr924', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1343288194%2F22498451902', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28729347835', 'Ração Magnus Todo Dia Pequeno Porte Carne e Frango 10,1kg', '– Indicado para cães;– Para cães adultos de porte pequeno;– Com proteínas de alta qualidade;– Auxilia na saúde intestinal. A Ração Magnus Todo Dia Cães de Pequeno Porte Carne e Frango é ideal para cães de pequeno porte. Formulada com o exclusivo complexo bio complex, cuidadosamente projetado para atender às necessidades específicas desses cães, promovendo uma flora intestinal saudável e reduzindo o odor das fezes. A ração contém todos os nutrientes essenciais, como proteínas, fibras, vitaminas e minerais, necessários para a saúde e o bem-estar do seu cão. Contém ingredientes que contribuem para uma pelagem saudável e brilhante, além de ajudar na manutenção da saúde da pele. O sabor carne e frango é atrativo para os cães e oferece uma proteína de alta digestibilidade. IngredientesMilho moído, farinha de carne e ossos de bovino, farelo de soja, farelo de trigo, cloreto de sódio, óleo de aves, hidrolisado de fígado de aves e suíno, parede celular de levedura, grão de linhaça, polpa de beterraba, extrato de yucca (0,03%), vitaminas (A, D3, E, K3, B1, B2, B5, B6, B12, niacina, ácido fólico, biotina, cloreto de colina), minerais (sulfato de ferro, sulfato de cobre, sulfato de manganês, sulfato de zinco, iodato de cálcio, selenito de sódio, organozinco, organosselênio, organomanganês), hexametafosfato de sódio, (0,01%), bentonita, ácido propiônico, BHA (Butilhidroxianisol) e BHT (Butilhidroxitolueno).', 110.9, 94.27, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/sg-11134201-7rd6e-m79pwydoeqp80d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F28729347835', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19199070558', 'Blusa Básica Feminina Plus Size Decote V Em Meia Malha AntiOdor', 'Blusa Básica Malwee confeccionada em meia malha anti odor. Modelo possui mangas curtas e decote em "V". As blusas básicas Malwee são atemporais e indispensáveis no guarda-roupa feminino por serem versáteis, confortáveis e feitas para durar, já que possuem a melhor durabilidade do mercado. O tecido meia malha anti odor possui beneficiamento que inibe mal cheiro, trazendo muito mais conforto e segurança para o seu dia a dia. Combine com calça jeans Malwee e tênis slip on!Modelagem: TradicionalDecote: V', 79.9, 71.91, NULL, 'Women Clothes > Tops > Shirts & Blouses', 'https://cf.shopee.com.br/file/sg-11134201-7rbmq-lo5uzx1d3c1cc9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939838662%2F19199070558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
