INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18970348045', 'Mochila Cavalera Reforçada Notebook Moda Executiva Casual Masculina Espaçosa', '📌CARACTERISTICAS: • Bolso frontal • Bolsos laterais telados • Bolso principal amplo e espaçoso • Divisórias internas espaçosas • Compartimento para notebook • Alças ergonômicas e reguláveis • Alças acolchoadas • Fechamento em zíper • Logo e puxadores personalizados 📝 FICHA TÉCNICA: • SKU: CV7239Z • Marca: Cavalera • Material: Poliéster 600D • Medidas (A*P*L): 44x14x30 cm • Peso: 0,400 kg • Capacidade: 18,5 litros ⚠️ CUIDADOS DE CONSERVAÇÃO: • Evite carregar excesso de peso • Embalar objetos com cantos vivos cortantes • Para limpeza, utilize apenas pano úmido ou esponja macia e sabão neutro. • Não expor a luz do sol para secar • Não utilizar nenhum produto químico para limpeza • Conservar em local seco e arejado ❓ QUEM SOMOS? A Oh My Bag, varejo constituído para a revenda de Mochilas, Bolsas e Malas de Viagem, vem se especializando no varejo online e se tornando referência em qualidade e confiança. Com abrangência em todo território nacional, a OMB com centro de abastecimento próprio e estoque permanente. Isso tem tornado a loja um sinônimo de tranquilidade na compra e agilidade na entrega. Emitimos Nota Fiscal para Pessoa Física e Jurídica (CNPJ). Produtos a pronta entrega. Produtos no interior do produto são apenas ilustrativos. Todos os nossos produtos são originais.', 209.9, 178.42, NULL, 'Men Bags > Laptop Bags > Laptop Backpacks', 'https://cf.shopee.com.br/file/br-11134207-7qukw-ljfrxvv0uun795', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F441234830%2F18970348045', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
