INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399308987', 'Buzina Automotiva Caracol Fiat Punto 2013-2017 12v Original Gauss', '🚚 𝗘𝗡𝗩𝗜𝗢 𝗜𝗠𝗘𝗗𝗜𝗔𝗧𝗢 𝗘𝗠 𝗔𝗧𝗘́ 𝟭𝟮𝗛 𝗨́𝗧𝗘𝗜𝗦 Buzina Automotiva Caracol Fiat Punto 2013-2017 12v Gauss A principal função da buzina é alertar no trânsito sobre alguma condição adversa sendo utilizada para evitar uma colisão no trânsito, em ocasiões de desatenção de outro motorista.Trata-se de um item obrigatório no veículo, que pode render multa para o motorista, caso não esteja funcionando regularmente. A Buzina Gauss Fiat Punto Buzina Caracol combina eficiência com durabilidade, para que você possa ter o melhor desempenho do seu veículo As buzinas da Gauss são rigorosamente testados para que apresentem sempre o melhor resultado. Usando tecnologia de ponta, a Gauss hoje é uma multinacional, com mais de 20 anos do mercado e certificado pelo ISO 9001, que garante excelência de qualidade e atendimento. Compatibilidade com os seguintes veículos: Fiat Punto 2013 Fiat Punto 2014 Fiat Punto 2015 Fiat Punto 2016 Fiat Punto 2017 Especificações Técnicas do Veículo: Veículo: Punto Montadora: Fiat Ano: 2013 a 2017 Especificação Técnica - Buzina: Cod Produto: Gb1052 Modelo: Buzina Caracol Voltagem: 12.0 Nivel Sonoro: 110.0 Quantidade De Conectores: 2.0 Quantidade Buzinas: 1.0 Quandidade De Cornetas: 1.0 Origem: Brasil 🚚 Enviamos para todo o Brasil com segurança e rapidez! ✅ Qualquer dúvida estamos à disposição no chat.', 37.99, 37.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5ku78j2ej76d6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F18399308987', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42175357206', 'Ventilador de Mesa Ventisol Oscilante Turbo Grade De Plástico 10 Pás 50CM 150W 127V Preto - 17598', 'Ventilador de Mesa Ventisol Oscilante Turbo Grade De Plástico 10P 50CM 150W 127V Preto - 17598 O Ventilador de Mesa Ventisol Turbo 10 une potência, design moderno e eficiência para deixar seu ambiente sempre arejado e confortável. Com motor de alta performance de 150W e hélice de 10 pás com design aerodinâmico, ele oferece muito mais vento e melhor circulação de ar. Seu novo design alia robustez e estilo, com acabamento moderno e arrojado que combina com qualquer ambiente. Além disso, conta com oscilação horizontal automática, que distribui o ar de forma uniforme, e regulagem manual de inclinação, permitindo ajustar o fluxo conforme sua necessidade. ESPECIFICAÇÕES Marca: Ventisol Modelo: 17598 Cor: Preto Tensão (Voltagem): 127v Dimensões(CxLxA): 520x320x684mm Quantidade de Pás: 10 Potência: 150w Tamanho da Hélice: 450mm Tamanho da Grade: 520mm Vazão: 0,97 m3/s Consumo de Energia: 4,07 kWh/mês Imagens de caráter ilustrativo. Informações divulgadas de acordo com o manual do fabricante. Produto novo na caixa, lacrado com garantia do fabricante de 12 meses. Em caso de dúvidas sobre informações técnicas, utilização, limitações e manuseio do produto, verifique o manual do fabricante. NAC016927 EAN7898461977602', 279.8, 189.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-8258l-mg3wwr679yx968', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683223635%2F42175357206', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
