INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192476344', 'Pincel De Maquiagem Belliz Wood Duo Fiber 1780', 'O Pincel Duo Fiber Belliz Wood possui cerdas com duas alturas diferentes, sendo indicado para aplicar e esfumar bases líquidas, oferecendo um acabamento mais leve e natural. Ele pode ainda ser utilizado para aplicação de pós faciais soltos e compactos ou blushs. Cerdas sintéticas de alta qualidade e extra macias. Desempenho profissional. Design sofisticado. Cabo 100% em madeira. Modo de uso: Use para aplicação de bases líquidas e cremosas. A dica para uma aplicação impecável é depositar uma pequena quantidade do produto no rosto e em seguida usar o pincel para espalhar. Limpeza e conservação: Lave o pincel em solução de água morna e pouco sabão neutro, sem esfregar para não danificar os fios. Deixe secar naturalmente. #html-body [data-pb-style="646BA649A0A25"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA649A0A3A"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 18.95, 18.95, NULL, 'Beauty > Beauty Tools > Makeup Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rbmz-lm64ly5iv22zd5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22192476344', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
