INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693230286', 'Estator do Magneto Xr 250 Tornado 2001 A 2008 Magnetron', 'Potência e confiabilidade para sua moto: com o Estator C/Bobina de Pulso do Magneto, você garante carga estável e funcionamento perfeito em qualquer trajeto! O estator do magneto é responsavel pela geração e regularidade da energia elétrica da moto. Quando estão desgastados, podem causar falhas na partida, descarga da bateria e até apagões inesperados. A substituição preventiva dessa peça garante um sistema elétrico eficiente, evitando imprevistos e mantendo a moto sempre pronta para rodar com segurança e desempenho. Compatível com HONDA: XR 250 TORNADO 2001 XR 250 TORNADO 2002 XR 250 TORNADO 2003 XR 250 TORNADO 2004 XR 250 TORNADO 2005 XR 250 TORNADO 2006 XR 250 TORNADO 2007 XR 250 TORNADO 2008 Conteúdo da Embalagem: 01 Estator com Bobina de Pulso do Magneto Magnetron Código Original (OEM) do Estator: 31120-KPE-901 31120-KPE-931 Especificações Técnicas: - Equivalente a Peça Original - Ideal para Reposição - Alta Resistência e Durabilidade - Tratamentos contra a oxidação - Confeccionado com a melhor matéria-prima - Melhor condutibilidade e maior vida útil da peça - Material leve e resistente - Excelente qualidade e acabamento Características: - Produto desenvolvido com os mesmos parâmetros e encaixes do original, substituindo o mesmo sem nenhum problema ou adaptação. - Testado e aprovado dentro das normas de segurança. Importante !! - Para a instalação do produto corretamente, leve ao mecânico de sua confiança! - Não nos responsabilizamos pelo uso indevido do produto.', 389.9, 311.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-8258y-mfxxg43o81zh8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%