INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257918127', 'Sapato Mississipi de Salto Bloco Feminino J1523', 'Produto marca Mississipi. O Sapato Mississipi de Salto Bloco é a união perfeita entre o charme retrô e a modernidade indispensável para a mulher contemporânea. Com o icônico design estilo Mary Jane, este modelo apresenta um acabamento monocolor em material sintético de alta qualidade, garantindo um visual polido e sofisticado. a delicada tira sobre o pé, finalizada com uma fivela metalizada, não apenas adiciona um toque de feminilidade, mas também oferece um ajuste seguro e personalizado para o seu caminhar. Projetado para quem não abre mão do bem-estar, o salto bloco de 5,5 cm proporciona a estabilidade ideal, permitindo que você transite do ambiente de trabalho para um evento de lazer com total confiança. Sua estrutura leve de 0,585 kg reduz o cansaço ao longo do dia, tornando-o o aliado perfeito para uma rotina dinâmica. É o calçado "coringa" que eleva qualquer look, desde o jeans casual até alfaiatarias mais estruturadas, entregando conforto premium sem sacrificar a elegância. Invista em um acessório que reflete sua personalidade e praticidade. Este sapato é a escolha estratégica para quem busca durabilidade e estilo em uma única peça, garantindo um guarda-roupa inteligente e atemporal. Seja para o dia a dia ou momentos de descontração, sinta-se pronta para conquistar qualquer espaço com a segurança e o brilho que só a Mississipi oferece. Peso: 0,585 kg', 206.9, 179.9, NULL, 'Women Shoes > Flats > Ballet Flats', 'https://cf.shopee.com.br/file/sg-11134201-8261b-mmgh45506arncc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F58257918127', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207921836', 'Sapato Mississipi de Salto Bloco Feminino J1471', 'Produto marca Mississipi. O Sapato Mississipi de Salto Bloco é a união perfeita entre a elegância clássica e o design contemporâneo. Com acabamento em material sintético de alta qualidade, ele apresenta um visual minimalista que nunca sai de moda. o destaque fica para a tira sobre o pé, adornada por uma fivela metalizada com textura orgânica, garantindo um toque de sofisticação e ajuste seguro para o seu caminhar. Desenvolvido para oferecer o máximo conforto e estabilidade, este modelo conta com um salto bloco de 4,5 cm, a altura ideal para quem busca elevar o visual sem abrir mão do bem-estar. Sendo leve e resistente, ele é o aliado indispensável para enfrentar a rotina com confiança. É a escolha inteligente para mulheres que valorizam a praticidade, proporcionando uma transição suave entre as demandas do trabalho e os momentos de descontração. Versátil, o sapato Mary Jane adapta-se facilmente a diferentes estilos de vida, do romântico ao urbano. Combine com vestidos fluidos, saias midi ou alfaiataria para criar looks que transparecem personalidade e bom gosto. Invista em um calçado que entrega durabilidade e tendência, garantindo que você esteja pronta para qualquer ocasião, seja no lazer ou no dia a dia, sempre com um toque de exclusividade Mississipi. Peso: 0,757 kg', 206.9, 206.9, NULL, 'Women Shoes > Flats > Ballet Flats', 'https://cf.shopee.com.br/file/sg-11134201-82617-mmgh4hu6jmrs67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F58207921836', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
