INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394344197', 'Jogo Com 6 Taças Diamond 340ml Vidro Transparente Suco Vinho', 'Elegância e Brilho na Sua Mesa: Jogo de Taças Diamond Para momentos especiais ou para o dia a dia, a escolha dos utensílios certos faz toda a diferença. O Jogo de Taças Diamond é a peça que faltava para levar sofisticação e requinte à sua casa. Com um design que remete ao brilho dos diamantes, estas taças em vidro com relevo texturizado capturam a luz de uma forma única, transformando qualquer bebida em uma experiência visual. Ideal para servir água, sucos ou até mesmo coquetéis, este conjunto de 6 unidades é versátil e perfeito para receber convidados. Feitas com vidro de alta qualidade, as taças são resistentes e fáceis de limpar, garantindo durabilidade e praticidade. Na Openbox2, nossa missão é oferecer os melhores produtos do mercado para que você tenha uma mesa completa e impecável. Adquira já o seu Jogo de Taças Diamond e eleve o nível das suas refeições. Sua mesa de jantar merece esse toque de brilho. Altura: 16cm Largura: 8cm Profundidade: 7,5cm', 79.99, 79.99, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mduf8c1mgkopd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F775496126%2F23394344197', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
