INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40551841011', 'Viseira P/ Capacete Norisk FF302 Soul 2.2mm Polivisor', 'Viseira Polivisor Antirrisco 2.2mm: Proteção e Visibilidade para Seu Capacete! Compatível com: - Capacetes NORISK - FF302/SOUL TEXX - WING - Tamanhos: 56, 58, 60 e 62 Características: - Tratamento Antirrisco: Resistente a riscos e arranhões - Material: Policarbonato de alta qualidade com 2.2mm de espessura - Proteção UV: Proteção contra raios UV para uma visão segura - Durabilidade: Alta durabilidade e resistência para um uso prolongado - Transparência: Alta transparência para uma visão clara e precisa - Fácil Instalação: Fácil de instalar e remover Benefícios: - Proteção: Proteção contra riscos e arranhões para uma visão segura - Visibilidade: Alta transparência para uma visão clara e precisa - Durabilidade:Alta durabilidade e resistência para um uso prolongado Instruções de Uso: - Limpe com sabão neutro e água corrente - Evite solventes químicos, gasolina ou produtos abrasivos - Não aplique vernizes ou adesivos - Troque sua viseira regularmente para garantir a segurança e visibilidade Marca Confiável: A Polivisor é a maior fabricante de viseiras para capacetes no Brasil, com mais de 20 anos de experiência e investimentos constantes em tecnologia para desenvolver produtos de alta qualidade. Importante !! - Não nos responsabilizamos pelo mau uso do produto', 59.9, 50.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmet Visor Shields', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk8gqoqxaolcd5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F40551841011', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4093973601', 'Kit Reparo Fixação de Viseira P/ Capacete LS2 FF350', 'Kit Fixação Polivisor: Proteção e Visibilidade para Seu Capacete! Os Kit Fixação da Polivisor oferecem benefícios como instalação rápida e fácil, durabilidade, ajuste preciso e manutenção da segurança, permitindo a substituição de peças danificadas e prolongando a vida útil do seu capacete. Compatível com - LS2: FF350 - Tamanhos: 56, 58, 60 e 62 Conteúdo da Embalagem: 01 Par de Reparo Fixador da Viseira 04 Parafusos Instalação Rápida e Fácil: As Fixações da Polivisor são projetados para facilitar a substituição de peças, muitas vezes sem a necessidade de ferramentas complexas, tornando o processo simples e rápido. Durabilidade: Os materiais utilizados nos reparos são resistentes ao desgaste e a impactos, garantindo que a peça substituída tenha uma longa vida útil e suporte o uso diário do capacete. Especificações: - Padrão Original - Peça extremamente precisa que oferece total segurança durante o uso - Os produtos possuem encaixes perfeitos e não necessitam de adaptações para serem instalados. - Acessório de reposição de fácil instalação - Acompanha lado direito e esquerdo - Produto fabricado pela marca Polivisor. - Oferecendo o melhor custo beneficio, unindo qualidade e eficiência na sua utilidade. Importante !! - Antes da compra verifique se este modelo é realmente compatível com seu capacete - Não nos responsabilizamos pelo mau uso do produto.', 49.9, 39.92, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmet Visor Shields', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcrt5yeodgxtf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F4093973601', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16920311809', 'Viseira Cristal Polivisor P/ Capacete Ls2 FF350 / Norisk FF311 Antirrisco 2.2mm', 'Viseira Polivisor injetada 2.2mm Com tratamento resistente a risco. Aplicação: NORISK FF311 LS2 FF350 NITRO CN400 / N510 / N1420 E N1430 TEXX SILVER EAGLE SHAD AD204 MHR BLADE SYKO BIG MUTH / YUASA / HAWAI TEXX 360 CONCEPTS Especificações: - Viseira em policarbonato com espessura de 2.2mm; - Viseira compatível com capacetes do tamanho 56, 58 e 60 - Super resistente - Alta transparência - Alta durabilidade - Boa vedação e funcionalidade no capacete - Proteção contra raios UV - Fácil Instalação Com mais de 20 anos de experiência no mercado a Polivisor é a maior fabricante de viseiras para capacetes no Brasil. Produzindo viseiras de alta qualidade, com investimentos constantes em tecnologia para o desenvolvimento de novo produtos. Instruções de uso: - Limpe somente com sabão neutro e água corrente - Não aplicar solvente químico, gasolina ou produtos abrasivos - Não aplicar vernizes ou adesivos - Troque sua viseira regularmente Importante: - Não nos responsabilizamos pelo mau uso do produto', 79.9, 79.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmet Visor Shields', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcw1kwdj82rl73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F16920311809', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
