INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23999032681', 'Cloro Piscina Genclor Estabilizador 10Kg', 'O Cloro Piscina Genclor Genco 10Kg Estabilizado foi desenvolvido para proporcionar água limpa, cristalina e segura por mais tempo. Sua fórmula com 56% de cloro ativo oferece alta eficiência na eliminação de bactérias, fungos e outros microrganismos, garantindo um tratamento completo para piscinas residenciais e institucionais. Por ser um cloro estabilizado, possui proteção contra os raios UV, reduzindo a perda de cloro causada pela exposição solar e aumentando o rendimento do produto. Isso proporciona economia, praticidade e menor frequência de aplicações. Ideal para manutenção contínua da piscina, o Genclor Genco ajuda a manter a água transparente, saudável e pronta para uso durante toda a temporada. CARACTERÍSTICAS PRINCIPAISCloro estabilizado para piscinas Teor de cloro ativo de 56% Proteção contra raios UV Alta eficiência na desinfecção Dissolução rápida Excelente rendimento Indicado para uso residencial e institucional Embalagem econômica de 10kg APLICAÇÕESPiscinas residenciais Piscinas de condomínios Clubes Chácaras Hotéis Áreas de lazer FICHA TÉCNICAMarca: Genco Modelo: Genclor Estabilizado Tipo: Cloro Granulado Estabilizado Teor de Cloro Ativo: 56% Peso Líquido: 10kg Validade: 2 anos Embalagem: Balde Origem: Nacional DIMENSÕES E PESOAltura: 29 cm Largura: 27 cm Profundidade: 27 cm Peso: 10 kg', 702.9, 234.9, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-8257s-mg6n9dfbaeq45f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965617276%2F23999032681', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
