INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3788956282', 'Lona Polietileno 5x3m Laranja 200 Micras Reforçada Vonder', 'Conteúdo da embalagem 1 Lona de polietileno Aplicações e dicas de uso Indicada para indústria, agricultura, construção civil, náutica, camping, pesca, recreação, utilidades domésticas, entre outros. Não utilizar a lona diretamente sobre superfícies aquecidas ou expostas ao sol (exemplos: veículos, peças metálicas, máquinas e equipamentos), pois a ação do calor poderá provocar manchas e danos às superfícies. Não utilizar para cobertura de cargas transportadas em caminhões, caminhonetes e automóveis. Não utilizar em contato com produtos químicos e resinas e para cobertura de peças perfurantes/cortantes. O esforço excessivo e a ação de ventos fortes podem provocar o rompimento dos ilhoses, bem como da lona. Conservação: armazenar longe de fontes de calor. Caso necessário, lavar com água e sabão neutro. Destaques e diferenciais Possui cantos reforçados e fio sintético ao redor da bainha para maior resistência. Fabricada em polietileno de alta e baixa densidade com aditivo que protege contra os raios ultravioleta. Impermeável. Possui amostra do produto fora da embalagem. DETALHES TÉCNICOS Medida da lona: 5 m x 3 m Cor da lona: Laranja Espessura aproximada da lona de polietileno: 200 micra Distância entre ilhoses da lona: A cada 1 metro', 120.9, 120.9, NULL, 'Home & Living > Tools & Home Improvement > Shades, Awnings & Tarpaulins', 'https://cf.shopee.com.br/file/sg-11134201-7rdwk-lzyy1dgj3ujmde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442555366%2F3788956282', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
