INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993084529', 'Kit 3 und Lavitan Primula Femme 60 Caps', 'Lavitan Prímula é um suplemento alimentar recomendado para o alívio dos sintomas da TPM e fotalecimento do sistema imunológico. Além disso, é recomendado para a prevenção de transtornos cardiovasculares. Modo De Usar: É recomendada a administração de 2 cápsulas de Lavitan Prímula ao dia. Esta embalagem contém 60 unidades gelatinosas de 750mg cada uma. Para facilitar, ingira com auxílio de líquidos e tome todos os dias no mesmo horário. Composição: Este suplemento é composto por óleo de linhaça, óleo de prímula, óleo de borragem e antioxidante DL-alfa tocoferol. A cápsula é formula por gelatina, água purificada e umectante glicerina. Advertência: Não substitua alimentação para administrar Lavitan; Caso esteja grávida ou em período de amamentação, Não consuma este produto sem orientação médica ou de um nutricionista; Mantenha o frasco longe do alcance de crianças; Não exceda a recomendação diária.', 66.99, 66.99, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rd6x-lw5vk6i4lwchc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F22993084529', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
