INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23639585051', 'Bico Espalhador Tipo Leque Para Pistola De Pintura Arprex Modelo 90 Furo Retangular', 'Comercial Vipasa Distribuidora FURO DO BICO : 1,2mm Descrição: O Bico Espalhador Tipo Leque para Pistola de Pintura Arprex Modelo 90 é uma peça de reposição essencial para manter o desempenho e a precisão da sua pistola de pintura. Projetado especificamente para o modelo 90 da Arprex, este bico espalhador oferece um padrão de pulverização uniforme em forma de leque, ideal para uma variedade de aplicações de pintura. Fabricado com materiais de alta qualidade, este bico garante uma pulverização suave e consistente, permitindo resultados profissionais em qualquer projeto de pintura. Ficha Técnica: Marca: Arprex Modelo Compatível: Modelo 90 Tipo: Bico Espalhador Tipo Leque Material: Metal resistente à corrosão Padrão de Pulverização: Leque Aplicação: Pintura em superfícies diversas Uso: Profissional e industrial Fácil Instalação: Substituição simples e rápida Garantia: Garantia do fabricante contra defeitos de fabricação Este Bico Espalhador Tipo Leque para Pistola de Pintura Arprex Modelo 90 é a escolha ideal para garantir resultados de pintura precisos e de alta qualidade. Seja para aplicações profissionais ou industriais, este bico espalhador oferece desempenho confiável e durabilidade excepcional, garantindo uma pulverização uniforme e eficiente em cada trabalho de pintura. Comercial Vipasa Distribuidora', 13.99, 13.99, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-7qveg-lfrdl9ryiz9m70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F23639585051', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
