INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14246640574', 'Vinho Latitud 33 Syrah 750ml', 'Este vinho amável e muito aromático distingue-se pela fiel caracterização da uva Syrah. De cor vermelho-rubi, corpo amplo, aromas de frutas vermelhas e toques de especiarias, é exótico, mas de grande equilíbrio na boca, com paladar longo e profundo... um convite para desfrutar desta surpreendente variedade em um vinho jovem e frutado. O amadurecimento em barricas de carvalho realça características como as especiarias, presentes naturalmente na uva Syrah. O nome desse rótulo faz referência ao local onde estão localizados os vinhedos que dão origem a esse exemplar.', 49.9, 49.9, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/ef7f884c434c9192002010b888b534cb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F14246640574', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
