INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20598001559', 'Roda - R-412 BP - 75KG 4 X 1.1/2 Polegadas - COLSON', 'Resina Termoplástica - Ref: BP - TP - C Material: Resina Termoplástica injetada na cor cinza. Material do Núcleo: Polipropileno injetado na cor cinza claro. Dureza: 80 (+/- 5) Shore D. Temperatura: de -5 a + 50 C. Aplicação: equipamento para supermercados, lojas, hospitais e indústrias. Tipo de Piso: concreto, cerâmica, aço, plásticos, borrachas e epóxi. Condições do Piso: liso, não mancha. Resistência Química: boa. Resistência a Umidade: excelente Resistência a Abrasão: muito boa.', 21.23, 20.6, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Truck Wheels', 'https://cf.shopee.com.br/file/sg-11134201-7ra27-m51la5qfzavec3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F272868574%2F20598001559', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20797612219', 'Óculos de Sol Chicago Rose Preto Degradê Premium Steampunk Piloto Vintage uv400 Masculino Feminino', '*ATENÇÃO! TODAS AS PROMOÇÕES E OFERTAS DA CACIFE BRAND NA SHOPEE SÃO POR TEMPO LIMITADO, APROVEITE!* Estamos felizes em recebê-lo em nossa loja, que já está no mercado há mais de 3 anos, proporcionando aos nossos clientes a melhor experiência em óculos de sol. Já vendemos mais de 300 mil óculos, o que demonstra a confiança que nossos clientes depositam em nossos produtos e serviços. Estamos comprometidos em oferecer óculos de qualidade a preços acessíveis, para que todos possam desfrutar de um estilo único e proteção para os olhos. * MEDIDAS * Armação: Acetato/metal Largura da lente 5,2 cm Altura da lente 5,0 cm Largura total 13,5 cm Agradecemos sua preferencia! Caso tenha alguma duvida, estamos 24 horas por dia, disponível. Garantia do vendedor: 90 dias CUPOM: CACIVINTE', 99.99, 69.99, NULL, 'Fashion Accessories > Eyewear > Sunglasses', 'https://cf.shopee.com.br/file/br-11134211-81z1k-mgfhu5fish6t46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1009389128%2F20797612219', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18376627119', 'HIDRATAÇÃO INTENSIVA 1KG TRIVITT', 'A Hidratação Intensiva Trivitt 1KG é um tratamento capilar desenvolvido para todos os tipos de cabelo, especialmente indicado para quem busca reparar danos e promover hidratação profunda. Este produto é ideal para quem deseja recuperar o brilho, a resistência e o condicionamento dos fios. Entre os principais ingredientes, destacam-se a queratina hidrolisada, que penetra facilmente nas cutículas capilares devido ao seu baixo peso molecular, restaurando áreas danificadas e selando as cutículas para manter a hidratação. O óleo de Camelina Dourada, de origem 100% vegetal, é rico em ômegas 3 e 6, restaurando a oleosidade natural dos fios e combatendo o ressecamento, além de melhorar a elasticidade e flexibilidade capilar. O PCA Sódico e a Arginina também estão presentes na fórmula, contribuindo para a nutrição e fortalecimento dos cabelos. Para aplicar, basta distribuir o produto sobre os cabelos limpos e úmidos, do comprimento às pontas, massageando suavemente mecha por mecha. Deixe agir por 5 minutos e enxágue. Para quem deseja finalizar com escova, recomenda-se aplicar o Fluido para Escova Trivitt antes de usar o secador. Os benefícios do uso regular incluem cabelos mais hidratados, com brilho intenso e resistência aumentada contra a quebra. O produto também ajuda a proteger os fios contra agentes externos, mantendo-os saudáveis por mais tempo. Lembre-se de que este produto é para uso externo e não deve ser utilizado em crianças. Mantenha-o fora do alcance de crianças e observe o prazo de validade de 36 meses para garantir a eficácia do tratamento.', 141.45, 123.07, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lkguinprl6cn6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F969993035%2F18376627119', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21299600092', 'Compressor Tecumseh 1/5 HP R134 LBP TH231DS - 127V', 'Compressor Tecumseh 1/5 HP R134 LBP TH231DS - 127V Apresentamos o Compressor Tecumseh 1/5 HP R134 LBP TH231DS - 127V, a solução ideal para quem busca eficiência e confiabilidade na refrigeração. Com capacidade de 785 Btu/h, este compressor utiliza o gás R-134A, garantindo um desempenho otimizado e sustentável. Projetado para operar em baixas temperaturas, é perfeito para equipamentos de refrigeração que necessitam de uma performance robusta e constante. Sua construção de alta qualidade assegura durabilidade e resistência, tornando-o uma escolha confiável para diversas aplicações. O Compressor Tecumseh 1/5 HP R134 LBP TH231DS é compatível com uma ampla variedade de equipamentos, oferecendo versatilidade e adaptabilidade ao seu sistema de refrigeração. Além disso, seu design compacto facilita a instalação, economizando espaço sem comprometer a eficiência.', 339.9, 339.9, NULL, 'Home Appliances > Kitchen Appliances > Others', 'https://cf.shopee.com.br/file/br-11134201-820m3-mqxe1neh9ced90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F21299600092', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258122060', 'Tomada Adaptador Reboque alta resistencia Para Chevrolet Silverado Após 2023 7 Vias, Padrão USA para Padrão Brasileiro', 'Atenção: este não é um produto original de montadora. Trata-se de peça paralela destinada ao mercado de reposição. Tomada Adaptador Chicote Reboque Para Chevrolet Silverado após 2023 – Padrão USA para Padrão Brasileiro 7 Vias Você tem uma Chevrolet Silverado, um ícone de força e capacidade, pronta para rebocar o que for preciso. Mas, na hora de engatar sua carretinha, trailer, reboque de barco ou jet ski com plugue no padrão brasileiro, surge o problema: a tomada elétrica é incompatível. Cortar fios e fazer adaptações no chicote de uma picape desse nível? Nem pensar. Isso pode comprometer a garantia, a segurança elétrica e a originalidade do veículo. A solução profissional é usar um adaptador específico, feito sob medida para essa conversão. Vantagens do Adaptador Instalação Plug and Play – sem cortes, sem gambiarra Basta conectar um lado na tomada original da sua Silverado e o outro na tomada do seu reboque. Em segundos tudo está funcionando, sem alterar a fiação original. Sua picape permanece 100% original. Sinalização correta, segura e em conformidade com a lei Garante o funcionamento adequado de todas as luzes do reboque (seta, freio, lanterna, ré) em sincronia com o veículo, conforme exigido pela legislação. Mais segurança para você, seus passageiros e os demais motoristas, evitando riscos e possíveis multas. Construção robusta, feita para uso pesado Fabricado em termoplástico de alta resistência, desenvolvido para suportar as condições de estrada: sol, chuva, poeira e vibrações constantes. Produto com excelente acabamento e durabilidade para o dia a dia. Características técnicas Marca: FLX Código: ASSTC112 Função: Adaptador / Conversor de Tomada de Reboque Conexão de entrada: 7 vias (padrão americano – macho) Conexão de saída: padrão brasileiro (fêmea) Voltagem: 12 V Material: termoplástico de alta resistência Instalação: Plug and Play Mapeamento de sinais: EUA: Terra, Posição, Pisca e Freio Esquerdo, Pisca e Freio Direito, Ré BR: Terra, Posição Esquerda, Posição Direita, Pisca Esquerdo, Pisca Direito, Luz de Freio, Ré Aplicação Chevrolet Silverado após 2023 Ford F-150 após 2023 Dodge Ram Ram 1500 após 2012 Ram 2500 após 2012 Ram 3500 após 2012 Observação: não serve no modelo Ram 2018. Garantia Tempo de garantia: 6 meses contra defeitos de fabricação. Itens inclusos 1 Tomada Adaptador para Reboque', 293.55, 235.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > CNG', 'https://cf.shopee.com.br/file/sg-11134201-81zvi-mmkgt6pn8bnl44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1365281712%2F58258122060', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23299117648', 'Kit Encorpa Cabelo 500gr Haskell | Shampoo + Máscara + Fluido finalizador encorpa', 'Transforme seus fios com o Kit Encorpa Haskell! Esta linha foi especialmente desenvolvida para cabelos finos e ralos, este kit completo promove o aumento da espessura dos fios e proporciona até 2x mais encorpamento, deixando os cabelos visivelmente mais densos, saudáveis e com volume natural. Benefícios: Cabelos 2x mais encorpados e densos Fortalecimento da fibra capilar Redensificação e revitalização dos fios Brilho, hidratação e maciez Volume leve e natural sem pesar Ideal para cabelos finos e com pouco volume O kit contém: 1 Shampoo Encorpa Haskell 500ml 1 Máscara Encorpa Haskell 500g 1 Fluido Encorpa Haskell 120ml Modo de uso: Shampoo: Aplique nos cabelos molhados, massageie o couro cabeludo e enxágue bem. Máscara: Com os fios limpos e úmidos, aplique mecha por mecha, deixe agir por 3 a 5 minutos e enxágue. Fluido: Após o uso da máscara, aplique nos cabelos limpos e úmidos, do comprimento às pontas. Finalize como desejar (com ou sem secador).', 223.7, 223.7, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8259d-mgdzb3h63evfa4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1562135680%2F23299117648', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
