INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54914651667', 'Cabo divisor estéreo TRRS de 3,5 mm para compartilhamento de áudio com dois fones de ouvido em PC/caixa de som', 'Conexão perfeita: Este cabo divisor e extensão para fone de ouvido com conector padrão 3,5 mm garante transferência de áudio perfeita do seu iPhone, iPod, iPad, Samsung, MP3 players, CD players, laptops, tablets e PlayStation. Seu design compacto e leve o torna ideal para viagens, viagens de carro e voos de avião.Desfrute de áudio nítido e confiável em qualquer lugar—este versátil divisor de fone de ouvido de 3,5 mm é compatível com iPhones, iPads, Samsung, MP3 players, CD players, laptops, tablets e PlayStation.', 21.0, 14.45, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/sg-11134253-8258y-mqy13utwx91e6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F54914651667', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18198180526', 'Pipoqueira Elétrica Sem Óleo 127V com 1200W Multi - GO057', 'Pipoqueira Elétrica Sem Óleo 127V com 1200W Multi - GO057 Transforme Seus Momentos com Pipoca de Cinema em Casa com a Pipoqueira Elétrica Sem Óleo Multi! Prepare-se para uma experiência cinematográfica de primeira com a Pipoqueira Elétrica Sem Óleo Multi! Em apenas 2 minutos, você terá pipoca fresquinha e crocante, pronta para compartilhar com amigos e família. Por que você vai adorar a Pipoqueira Elétrica Sem Óleo Multi? Praticidade em 2 Minutos: Basta ligar, adicionar o milho e aguardar. Sem panelas, fogão ou bagunça ? só pipoca deliciosa e saudável! Saudável e Crocante: Sem uma gota de óleo, você desfruta de pipoca com menos calorias e mais sabor. A saída de vapor mantém a crocância perfeita, sem umidade. Versatilidade na Cozinha: Inclui um copo dosador para você derreter manteiga, chocolate ou preparar coberturas deliciosas para personalizar suas pipocas. Facilidade e Segurança: O bocal direcionador garante que suas pipocas caiam diretamente na tigela, e os pés antiderrapantes proporcionam maior estabilidade durante o preparo. Capacidade Ideal: Com capacidade para até 80g de milho, é perfeito para uma sessão de cinema em casa ou uma tarde descontraída. Transforme seus momentos de lazer com a Pipoqueira Elétrica Sem Óleo Multi e descubra o prazer de uma pipoca saudável e perfeita, sempre pronta para qualquer ocasião! Ficha Técnica Marca: Multilaser Modelo: Pipoqueira Elétrica Sem Óleo 127V com 1200W Multi - GO057 Cor: Vermelho Voltagem: 127v Composição do Material: Polímero, metal e componentes eletrônicos Largura do produto: 14.5cm Altura do produto: 22cm Comprimento do produto: 30cm Peso do produto: 1,05kg Potência Total (W): 1200W PLUG: Tipo N Conteúdo da embalagem: 1 Pipoqueira elétrica, 1 Tampa dosadora, 1 Manual de instruções Garantia: 12 meses Imagens meramente ilustrativas.', 219.89, 169.9, NULL, 'Home Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7reps-m8z4c3p31amt58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389315825%2F18198180526', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14501087623', 'Creative Fun Multikids Super Feira 12 Legumes - BR1110', 'Creative Fun Super Feira Legumes Multikids, sua brincadeira de casinha muito mais divertida! Com 2 ovos, 1 cenoura, 1 batata, 1 milho, 2 tomates, 1 cebola, 1 pimenta, 1 brócolis, 1 berinjela, 1 cogumelo, 1 faca, 1 tabua de cortar legumes, saia para fazer suas compras na super feira e encha sua geladeira com coisas gostosas e saudáveis. Chame suas amigas para fazer compras com você na feirinha e se divirta muito! Deixe sua imaginação fluir e crie diversas situações divertidas para brincar. São mil possibilidades de brincar com esse incrível brinquedo da Multikids. Sua brincadeira de casinha muito mais completa, confira o restante dos produtos Creative Fun e tenha todas as frutas e legumes para suas brincadeiras! Imagens meramente ilustrativas', 175.89, 159.9, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/c1d85dfaa53c13b2ccbf1bd80b8f7745', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389315825%2F14501087623', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19750049651', 'Adesivo De Contato Lata (225 Ml) Brascola', 'Adesivo de contato Universal Brascola (230 ml). Apresenta aplicabilidade adequada para a colagem em materiais porosos. Como adesivo universal, sua linha de adesão permanece flexível durante longo tempo, resistindo a dilatações decorrentes de substratos diferentes. De uso geral, para colagem de tapeçaria de autos, guarnições de borracha, revestimentos, pisos de vinil, amianto, couro, diversos plásticos, tecidos, fibras, lã de vidro, pisos de borracha, madeira, papelão e carpetes. Resiste a até 60°C. Características do Produto:- Cor: Amarelo- Tempo de Manuseio: Tempo aberto de aproximadamente 25 minutos- Secagem: Cura total em 24 horas *** MANTER FORA DO ALCANCE DE CRIANÇAS E ANIMAIS DE ESTIMAÇÃO ***', 25.35, 25.35, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-22090-5fdiu7x2xzhvc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F19750049651', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
