INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21898323957', 'Bujao Plastico Caixa Radiador Mb Atego M22', '🛡️ Bujão Plástico para Caixa de Radiador com Rosca M22 – Vedação Confiável e Durabilidade O Bujão Plástico para Caixa de Radiador com Rosca M22 é um componente essencial para garantir a vedação perfeita e a segurança do sistema de refrigeração do seu veículo. Fabricado com material resistente e durável, suporta altas temperaturas e pressões típicas de radiadores automotivos, prevenindo vazamentos que podem comprometer o desempenho do motor. Com rosca padrão M22, o bujão oferece encaixe seguro e confiável, facilitando a instalação e a remoção durante a manutenção do sistema de arrefecimento. É ideal para veículos que exigem robustez, segurança e eficiência na proteção do motor. ⚙️ Aplicação Compatível com sistemas de radiador que utilizam rosca M22, indicado para: Caminhões, ônibus e veículos pesados Máquinas agrícolas e equipamentos industriais com sistemas de refrigeração M22 Substituição em radiadores com caixa plástica 💡 Benefícios Material resistente e durável, garantindo longa vida útil Vedação eficiente contra vazamentos de fluido de arrefecimento Suporta altas temperaturas e pressões típicas do radiador Rosca M22 padrão para encaixe seguro e fácil instalação Facilita manutenção preventiva e corretiva do sistema de refrigeração ⚠️ Atenção Verifique a compatibilidade da rosca M22 com o radiador do veículo antes da instalação. Recomenda-se instalação por profissional qualificado para garantir vedação e funcionamento corretos. 🔄 Troca e Garantia Produto novo, com garantia contra defeitos de fabricação. Aceitamos trocas conforme política vigente, desde que o item não apresente sinais de uso ou danos. 🚛 Entrega Envio rápido e seguro para todo o Brasil, com embalagem reforçada que protege o bujão durante o transporte. 🌟 Dunga Peças – Qualidade que move o seu caminho. Peças técnicas com confiança e aplicação precisa para o seu veículo.', 62.82, 57.8, NULL, 'Spare Parts and Accessories for Vehicles > Heavy Duty and Boats > Spare Parts for Heavy Duty Vehicles', 'https://cf.shopee.com.br/file/br-11134207-820l8-mqo58937fmrn16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1310994553%2F21898323957', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
