INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46803204289', 'Eu Posso ser um Médico Fantástico | Anna Claybourne', 'Você tem o que é preciso para ser um médico? Sim, claro que tem, e este livro repleto de ação vai provar isso!Enquanto completa as atividades e desafios divertidos, você aprenderá inúmeros fatos interessantes sobre o corpo humano e o mundo da medicina. Incentive assim seu pequeno no desenvolvimento.Não perca mais títulos dessa coleção incrível. 24x17 cm 64 Páginas', 14.9, 11.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-822zz-micgzi2occ1s53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F46803204289', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993518823', 'Puff Frapê Linho Cinza 47 cm', 'Que tal o Puff Frapê? O Puff Frapê é perfeito para compor sua casa como assento extra e levar mais comodidade ao dia a dia. Estruturado em madeira reflorestada e MDP, ele proporciona estabilidade e segurança ao o uso - já o enchimento em espuma D26 e o revestimento em Linho garantem o bem-estar adequado. Sofisticado e contemporâneo, o móvel tem formato redondo, pés alongados e um lindo detalhe em sua circunferência, tudo isso para deixar a sala, o quarto ou até o closet mais elegantes. Incrível, não é mesmo? Cor: Cinza Garantia em Meses: 3 Cores do Produto: Cinza Instruções/Cuidados: Limpar com pano seco Conteúdo da Embalagem: 1 Puff - Entregue em: 1 Volume Modelo: Frapê Número de Volumes: 1 Material: O Puff Frapê possui estrutura em madeira de reflorestamento e MDP 25 e 12mm, enchimento em espuma D26 e revestimento em linho Material para Filtro: Madeira Descrição do Tamanho: Altura: 41 cm | Largura: 47 cm | Profundidade: 47 cm Altura do Produto (cm): 41 Largura do Produto (cm): 47 Comprimento do Produto (cm): 47 Peso do Produto (Kg): 6 Produto precisa de Montagem?: Sim, sugerimos a contratação do nosso serviço de montagem (para os CEPs em que o serviço está disponível) ou de algum profissional experiente de sua preferência Quantidade de Peças: 1 Tipo de pé: Fixo Altura do assento até o chão (cm): 43 Linha de produtos: Frapê Tendências: Retro Chique Material da estrutura: Madeira Material do enchimento do assento: Espuma D26 Material do Revestimento: Linho Possui Baú?: Não Tipo de Puff: Banco Material dos pés: Madeira PROFUNDIDADE x LARGURA x ALTURA: 47 x 47 x 41 Fornecedor: Lidiane M. T. A. Batista - ME Baterias são necessárias?: Não Certificação de teste externa: Não Componentes incluídos: Não Is Fragile: Não Número da peça: Não Produto: Puff', 554.96, 554.96, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7rcdb-m6e8aqa02463ed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1226120317%2F22993518823', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23696665307', 'Bíblia King James 1611 | Letra Normal | Brochura | Coroa', 'A King James 1611 (BKJ1611), é descrita como uma das publicações mais importantes da história, e também a mais fiel ao Textus Receptus e o Texto Massorético. O rei James I da Inglaterra reuniu 54 estudiosos religiosos e linguistas para uma nova tradução da Bíblia, a fim de estabelecer a tradução mais precisa e mais digna. As Profecias Messiânicas são passagens nas escrituras sagradas, destacadas no texto Bíblico com o simbolo da Estrela de Davi, que falam sobre a vinda de um Messias, um Salvador prometido por Deus. Essas profecias descrevem características, eventos e propósitos relacionados ao Messias, incluindo sua linhagem, nascimento virginal, ministério, sacrifício e reino futuro, e são consideradas previsões que se cumpriram em Jesus Cristo. Os Recursos Adicionais auxiliam no entendimento do texto bíblico e seus estudos aos novos convertidos. Nós da BV Books Editora estamos felizes em poder apresentar, finalmente, a Versão Autorizada em português. Essa é a única versão em português da Bíblia King James 1611. Fiel e autêntica. BKJ1611 Ultrafina, é uma versão integral da King James 1611. 704 Páginas 14x21cm', 26.9, 26.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkmur9jlipaw7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23696665307', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794207250', 'Adoração: Quando a Fé se Torna Amor | Asaph Borba', 'Adoração é um estilo de vida, mais que um estilo de música Muitos pensam que adorar a Deus é sinônimo de espetáculos, festas e celebrações com muita música que mais se assemelham a shows de famosos cantores do mundo. Mas será que é isso que o Senhor realmente espera daqueles que dizem adorá-lo? Lábios que pronunciam declarações de amor valem mais que corações próximos de Deus? Em Adoração, o músico Asaph Borba defende que a adoração que Deus procura envolve deixar o "eu" de lado para que o Senhor possa atuar sem barreiras. O que Deus quer de seus seguidores é mais do que palavras de louvor: ele deseja vidas e caracteres retos e santos. Com esse livro, Borba mostra aos leitores que o mais importante e essencial é o ser antes do realizar, e que a verdadeira adoração é quando a fé se torna amor. 21X13 CM 184 Páginas', 32.9, 30.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdxr-mbxkzlo5emw5c2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22794207250', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
