INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18299884595', 'Mamadeira Super Evolution Divertida 6m+ 300ml Azul - Lillo', 'Mamadeira Super Evolution Divertida 6m+ 300ml Azul - Lillo A Mamadeira Super Evolution Divertida 300ml Lillo foi projetada com o formato de frasco mais acinturado. Sua abertura mais larga facilita a limpeza e o preparo dos alimentos. O bico redondo em silicone flexível contém uma área maior de apoio. Sua tampa antivazamento fecha de forma eficaz e mantém o bico protegido durante o transporte. Livre de BPA. O MINISTÉRIO DA SAÚDE ADVERTE: A CRIANÇA QUE MAMA NO PEITO NÃO NECESSITA DE MAMADEIRA, BICO OU CHUPETA. O USO DE MAMADEIRA, BICO OU CHUPETA PREJUDICA O ALEITAMENTO MATERNO. Principais Características: - Bico Tamanho 2: (6+ Meses) - Fácil higienização - Copo transparente com desenhos. - Formato inovador com elementos e traços suaves - Livre de BPA - Capacidade de 300 ml Especificações Técnicas: - Conteúdo da Embalagem: 1 Mamadeira Super Evolution 300ml - Composição/Material: Polipropileno e Silicone - Certificação INMETRO: CE-PUR /IQB-000632 - Garantia: 30 Dias (Contra Defeito de Fabricação Pelo Fabricante) - Cód Fabricante:628321 - Código EAN: 7896033211253 - Marca: Lillo Imagens meramente ilustrativas, cores e estampas podem variar de acordo com o lote do fabricante.', 34.9, 34.9, NULL, 'Mom & Baby > Feeding Essentials > Bottle-feeding', 'https://cf.shopee.com.br/file/sg-11134201-7rdx1-md0u9earn68e91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F624228750%2F18299884595', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693844067', 'Martelete Bosch GBH 220 720W 220V + Maleta', 'Ficou alguma dúvida? Faça sua pergunta, ficaremos satisfeitos em lhe atender bem. Emitimos Nota Fiscal. Qualidade, preço Justo e atendimento Perfeito. =====PRODUTO NA TENSÃO DE 220V===== O Martelo Perfurador Bosch GBH 220 720W é o mais compacto e leve da categoria, com excelente custo-benefício! Possui embreagem de segurança que evita acidentes com o usuário em caso de travamento da ferramenta e 4,0 metros de cabo de energia. O Martelo Perfurador Bosch GBH 220 é o martelo com o melhor índice de precisão para perfuração da categoria, oferecendo três operações: perfuração, perfuração com impacto e cinzelamento. Seu botão trava permite trabalhos contínuos e confortáveis ao operador, além de possuir controle de velocidade variável, para uma perfuração mais controlada. O Martelo Perfurador Bosch GBH 220 é leve, pesando apenas 2,3kg e possui 7202W de potência com 2,0J de impacto. Além de tudo, é uma ferramenta de fácil manutenção com um sistema de troca rápida de escova de carvão, tão fácil que pode ser feito com uma moeda. O Martelo Bosch GBH 220 acompanha maleta, punho auxiliar e limitador de profundidade. Ferramenta possui 1 ano (12 meses) de garantia Bosch. Potente motor de 720W, com 2,0J de impacto para melhor desempenho e maior eficiência. Versátil: Oferece três operações, perfuração, perfuração com impacto e cinzelamento. Possui cabo de energia de 4,0 metros de comprimento. O martelo mais compacto e leve da categoria; Embreagem de segurança: evita acidentes com o usuário em caso de travamento da ferramenta; 4.0 metros de cabo de energia; Martelo com o melhor índice de precisão para perfuração da categoria, Fácil manutenção: sistema de troca rápida de escova de carvão. ESPECIFICAÇÕES: - Potência: 720W - Número Máx de Impacto: 0 – 4.800 i.p.m. - Energia de percussão: 2 J - Diâmetro de perfuração em concreto, brocas para martelo: 4 – 22 mm - Diâmetro máx. de perfuração em metal: 13 mm - Diâmetro máx. de perfuração em madeira: 30 mm - Diâmetro máx. de perfuração concreto: 22 mm - Suporte da ferramenta: SDS plus - Valores totais de vibração (Cinzelar em concreto): Valor de emissão de vibrações ah: 11,9 m/s² Incerteza K: 1,5 m/s² - Cinzelar em concreto: Valor de emissão de vibrações ah: 11,9 m/s² Incerteza K: 1,5 m/s² - Dimensões (CxLxA): 34 x 9 x 21 cm - Peso: 2,300 Kg CONTEÚDO DA EMBALAGEM: 1 Martelete Perfurador GBH 220; 1 Manual de instruções; 1 Limitador de profundidade; 1 Empunhadura Auxiliar; 1 Maleta. Cód. Bosch: 110v 06112A60D0 / 220v 06112A60E0 Ficou alguma dúvida? Faça sua pergunta, ficaremos satisfeitos em lhe atender bem. Emitimos Nota Fiscal. Qualidade, preço Justo e atendimento Perfeito.', 999.9, 889.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9kgt0b3cf9538', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F350962329%2F22693844067', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
