INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40771039650', 'Dino Monta e Desmonta Mega Dino Robô 10cm Sortido - Art Brink', 'O Dino Monta e Desmonta Mega Dino Robô Sortido da Art Brink é a escolha perfeita para estimular a criatividade e a coordenação motora das crianças. Com um design divertido e peças coloridas, esse brinquedo permite que os pequenos montem e desmontem diferentes versões de dinossauros, utilizando uma ferramenta de montagem feita de plástico, especialmente desenvolvida para mãos pequenas. O grande diferencial está na possibilidade de combinar peças de diferentes modelos para criar um impressionante Mega Dino Robô, proporcionando horas de diversão educativa e interativa. Ideal para crianças que adoram dinossauros e desafios de montagem, esse produto une imaginação e aprendizado em uma única experiência. CARACTERÍSTICAS: -Marca: Art Brink -Faixa Etária: +3 -Contém: 1 Dinossauro, 1 Ferramenta para montagem -Composição: Plástico PP -Cor: Sortidas -Dimensão do Produto: 10cm -Dimensão da Embalagem: 4x12x10cm (LxCxA) INMETRO: 009882/2023', 19.99, 19.99, NULL, 'Mom & Baby > Toys > Robot Toys', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf1a844rtt6sdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406894684%2F40771039650', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
