INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298257258', 'Roda Par Dianteira Traseira Raio 4MM Cromado Cg Fan 125 2009 em Diante Com Pneu + Relação', 'Roda Dianteira e Traseira (Montada, Alinhada e Balanceada) Especificações: Modelo Compatível: Honda Fan 125 Posição da Roda: Dianteira e Traseira Anos de Fabricação: 2009 em Diante Características Técnicas: Aro: Pro Tork Cubo: Fabreck/Unibreq ( Marca Instalada Conforme Disponibilidade no Estoque ) Raio: 4mm Cromado Sistema de Freio: Á Tambor Dimensões e Material: Medidas do Aro: 18inches Material do Aro: Aço Estrutura de roda: De Raios Sendo líder de mercado, os cubos de roda Fabreck são confeccionados em liga de alumínio especial e com pintura no padrão da original, além de serem produzidos em modernos equipamentos de usinagem, proporcionam grande durabilidade e resistência do produto. Conservação Os cuidados para conservação do cromo, tanto no seu aspecto quanto na prevenção contra a oxidação, devem considerar a limpeza frequente com água e sabão neutro aplicados com pano ou esponja macia. A montagem e desmontagem do pneu deve ser realizada por profissional experiente e com equipamento adequado. Nunca utilize materiais abrasivos ou produtos químicos para limpeza.', 1064.9, 1064.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Wheels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6tq2eamk8rr7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1421013142%2F22298257258', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
