INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52954662026', 'Carrinho Organizador com Rodinhas 3 Andares Multiuso para Casa Cozinha Lavanderia Escritório Salão', 'Carrinho multiuso com 3 níveis, ideal para otimizar a organização em diferentes ambientes da casa ou do trabalho. Sua funcionalidade prática o torna perfeito para uso em residências, escritórios, salões de beleza, cozinhas, lavanderias, áreas de estudo e muito mais. Com estrutura firme e durável, conta com rodízios que permitem movimentação fácil entre os cômodos. Suporta diversos tipos de itens como livros, cosméticos, materiais escolares, utensílios domésticos, entre outros. Seu formato vertical aproveita melhor os espaços reduzidos, mantendo tudo bem acessível. Indicado para: - Organização de cosméticos e produtos de beleza em salões ou uso pessoal - Armazenamento de livros, cadernos e itens de papelaria - Utensílios de cozinha, temperos e mantimentos - Produtos de limpeza e artigos de lavanderia Características: - 3 níveis amplos para armazenamento - Rodinhas com rotação suave para facilitar a locomoção - Estrutura leve, resistente e de fácil manutenção - Adaptável a diferentes ambientes - Ideal para espaços compactos Medidas: - Altura: aproximadamente 86 cm - Largura: aproximadamente 43 cm - Profundidade: aproximadamente 36 cm Imagens e vídeos são meramente ilustrativos. A tonalidade da cor pode variar conforme o monitor.', 159.9, 42.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjh01fd9t9tt7b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F52954662026', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58158435634', 'Livro de Jogos Unicornios - Capa Dura', 'Unicórnios - Livro de Jogos convida as crianças a entrarem em um mundo encantado cheio de diversão! Com jogos e desafios mágicos, o livro estimula o raciocínio, a criatividade e a imaginação de um jeito leve, lúdico e cheio de fantasia.', 69.9, 59.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-81zwp-mmt8nq99jy1118', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F58158435634', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20020816048', 'Sapateira Com 20 Divisórias Armazenamento Sapatos Porta Closet Perdurável Espaço Tecido Resistente', 'DESCRIÇÃO DO PRODUTO: Sapateira Organizador Portas Com 20 Bolsos TNT Perdurável O Organizador de Sapatos para Porta é ideal para armazenar sapatos e outros objetos que precisam estar sempre à mão, garantindo maior conservação e facilitando a escolha. Produzido com materiais respiráveis, possui 20 divisórias que contribuem para otimização do espaço. ESPECIFICAÇÕES: Material/Composição: TNT e Papelão. Fornecedor: VMP Tamanho: 40 x 90 (cm)', 23.9, 18.91, NULL, 'Home & Living > Home Organizers > Shoe Storage Boxes', 'https://cf.shopee.com.br/file/br-11134207-820ll-mo9vc9issj5x12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F20020816048', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50603477388', 'Farol Uno 91 92 93 94 95 96 97 98 99 2000 2001 2003', 'Código do Produto: 162956 VALOR ANUNCIADO REFERENTE A UNIDADE. ESCOLHER O LADO DESEJADO NAS OPÇÕES DISPONÍVEIS. Farol Uno 1991 1992 1993 1994 1995 1996 1997 1998 1999 2000 2001 2003 O farol é uma peça essencial para sinalização e visibilidade em vias noturnas e para maior segurança eles devem estar sempre em bom estado. E aqui temos o produto ideal para você. Este item possui material de alta qualidade e resistência, composto com sua lente em vidro lisa, encaixe da lâmpada H4 que suporta até 55W e um design que deixa seu carro com aspecto diferenciado de todos os outros. Compatível com: FIAT - Uno 1991 - Uno 1992 - Uno 1993 - Uno 1994 - Uno 1995 - Uno 1996 - Uno 1997 - Uno 1998 - Uno 1999 - Uno 2000 - Uno 2001 - Uno 2003 Especificações Técnicas: - Máscara Cromada - Foco Simples - Encaixe da Lâmpada H4 - Lente Lisa - Material da Lente em Vidro - Material da Carcaça em Plástico - Suporta Lâmpadas de até 55W ATENÇÃO Garantia - 3 Meses O valor anunciado é referente a unidade. A Empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 87.13, 87.13, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-81zva-mikp3idireh05c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F50603477388', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250683567', 'Coqueteleira Animal - 600ml Preta - Universal Nutrition', 'Coqueteleira Animal (600ml) é o utensílio ideal para a preparação de bebidas. A Coqueteleira Animal vem com marcações para dosagens, que vão dos 100 aos 600 ml, tornando-se um mixer perfeito para aqueles que precisam de dosagens exatas. Fácil de transportar e fácil de armazenar, é perfeita para levar à academia, faculdade ou trabalho, pois se acomoda tranquilamente em sua bolsa ou mochila. Além de ser prático e funcional, é muito fácil de higienizar. ...', 22.73, 22.73, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-821g1-mh6e82uv5udpd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F58250683567', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
