INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293498797', 'Seladora Automática Contínua Vertical com Datador 220v Industrial', 'As Seladoras Contínuas NAGANO são compactas e práticas. São fáceis de ser usadas na selagem de diversos tipos de embalagens, e têm manutenção simples. Possuem também datador para que o pacote já saia da esteira pronto para ser comercializado. As seladoras contam com um painel de ajuste, para que as configurações estejam de acordo com o trabalho requerido pelo usuário. VELOCIDADE DE VEDAÇÃO: 0 --- 12 M/MIN (Ajustável) LARGURA DE VEDAÇÃO: 6 --- 12MM (Ajustável) VARIAÇÃO DE TEMPERATURA: 0 --- 300C (Ajustável) COMPRIMENTO DE VEDAÇÃO: Ilimitado Nº DE PALAVRAS IMPRESSAS: 13 DIMENSÕES EXTERNAS (MM): 850 X 320 X 550 ATENÇÃO: Modelo com função para datar Codificação: por relevo.', 1782.8, 1782.8, NULL, 'Home & Living > Kitchenware > Sealers', 'https://cf.shopee.com.br/file/sg-11134201-7req7-m1wsvg0jr4qx54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F23293498797', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
