INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193685267', 'Bíblia Sagrada NVI Capa Dura - Perfeita para Presentear', '📖 BÍBLIA SAGRADA NVI CAPA DURA LETRA MÉDIA - FÁCIL LEITURA, TRADUÇÃO CLARA E DE QUALIDADE 📖 A Bíblia Sagrada Nova Versão Internacional (NVI) é uma das traduções mais queridas pelos cristãos, conhecida por sua linguagem moderna e acessível. Esta edição com capa dura e letra média oferece conforto na leitura e durabilidade para o dia a dia. Ideal para estudos, cultos e devocionais! ✨ Principais características: ✅ Bíblia NVI (Nova Versão Internacional) – Tradução clara e de fácil entendimento. ✅ Capa Dura Resistente – Perfeita para maior durabilidade e elegância. ✅ Letra Média Confortável – Ideal para leituras prolongadas sem cansaço visual. ✅ Tamanho Prático – Fácil de carregar para a igreja, grupos de estudo e viagens. ✅ Ótima para Presentear – Um presente especial para fortalecer a fé! 🔍 Palavras-chave para facilitar sua busca: Bíblia Sagrada, Bíblia NVI, Bíblia capa dura, Bíblia com letra média, Bíblia para leitura, Bíblia para estudos, Bíblia presente, Bíblia evangélica. 📦 Envio Rápido e Seguro! Garanta a sua agora mesmo! 🙏', 28.33, 28.33, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5vj18kb970274', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F23193685267', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4382464139', 'A Bíblia das Descobertas - Capa Ilustrada Azul', 'DESCRIÇÃO A Bíblia das Descobertas, edição capa dura da Sociedade Bíblica do Brasil, apresenta mais de 102 experiências interativas que ajudam crianças a explorar e aprender a Palavra de Deus de forma prática e divertida. A nova tradução NTLH facilita o entendimento, com elementos como introduções, tabelas, vocabulário e orientações visuais que incentivam o aprendizado bíblico. FICHA TÉCNICA Título: A Bíblia das Descobertas Autor / Organização: Sociedade Bíblica do Brasil Editora: Sociedade Bíblica do Brasil ISBN: 9788531110740 Formato: Capa dura ilustrada plastificada Dimensões: 13,5 x 21,5 x 2,9 cm Número de páginas: 1.376 Peso: 700 g Categoria: Bíblia Infantil / didática Idioma: Português (NTLH) Ano de edição: 2017 PALAVRAS‑CHAVE a bíblia das descobertas, sociedade bíblica do brasil, bíblia infantil, NTLH, bíblia ilustrada, Bíblia das Descobertas capa dura, bíblia para crianças, experiências bíblicas infantis, evangelização infantil, ensino bíblico, leitura infantil cristã, livro cristão infantil, bíblia com atividades, estudo bíblico infantil, bíblia didática, literatura lúdica bíblica, bíblia educativa, livro didático para crianças, devocional infantil, crianças aprendem bíblia, bíblia ilustrada educativa, presentes cristãos infantis, bíblia ensino visual', 127.98, 127.98, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7qukw-ljzjvatk0o832c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F4382464139', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
