INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893083508', 'Cômoda Primordial Max 4 Gavetas Marrom/Jacarandá Jacaranda', 'Conheça a Cômoda Primordial Max, a combinação perfeita de estilo e funcionalidade para seu espaço! Com 4 gavetas equipadas com corrediças metálicas, ela oferece um deslizar suave e durável. A primeira gaveta vem com divisórias e chave, garantindo organização e segurança para seus itens mais preciosos. Seus puxadores em MDF e o tampo em MDP de 25mm garantem robustez e elegância. O acabamento interno é igual ao externo, proporcionando um visual impecável em todos os ângulos. Transforme seu ambiente com a sofisticação e praticidade da Primordial Max! Estilo: Moderno Peso (kg): 35.5 Garantia: 03 Meses Altura (cm): 129.3 Acabamento: Pintura Texturizada UV Largura (cm): 61.3 Possui Pés: Sim Possui Nichos: Não Possui Portas: Não Pés Reguláveis: Não Possui Gavetas: Sim Possui Rodízio: Não Suporta Até (kg): 25 Tipo de Cômoda: Adulto Possui Espelhos: Não Profundidade (cm): 46.3 Escala de Brilho: Fosco Gaveta com Chave: Sim Material dos Pés: Plástico Material do Fundo: MDP Origem do Produto: Nacional Ambiente Principal: Quarto Material da Gaveta: MDP Material Principal: MDP Necessita Montagem: Sim Possui Prateleiras: Não Sapatas Niveladoras: Não Acabamento da Gaveta: Pintura Texturizada UV Peso Máximo por Gaveta: 3 Complexidade da Montagem: Alta: deve ser montado por um montador especializado Tipo de Puxador da Gaveta: Externo Escala de Brilho da Gaveta: Fosco Tipo de Corrediça da Gaveta: Metálica Simples Material do Puxador da Gaveta: MDF Marca: Zanzini Cor Interna: Jacaranda Cor: Jacaranda Cor do Produto: Jacarandá Itens Inclusos: 1-Cômoda Primordial MAX + Manual de Montagem Cor Predominante: Marrom Linha ou Coleção: Primordial Cor do Puxador: Marrom Quantidade de Gavetas: 04 Gavetas', 503.51, 503.51, NULL, '