INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50301907925', 'Carretilha Pesca Maruri Attack 7 Rolamentos 5kg Carretel Profissional Original', 'Carretilha Maruri Attack 7 Rolamentos 5kg Pesca Profissional A Carretilha Maruri Attack entrega desempenho, força e suavidade para pescarias com iscas artificiais. Com design moderno e construção reforçada, ela conta com pinhão apoiado por rolamentos, freio magnético e disco de carbono, garantindo mais resistência, precisão e controle até mesmo com peixes maiores. Pesando apenas 207gr, oferece leveza para longas horas de uso, além de excelente capacidade de linha no carretel de alumínio. Sua relação de recolhimento 7.3:1 proporciona recuperação rápida, ideal para quem busca agilidade e eficiência. Disponível nas cores preta e prata, é a carretilha perfeita para quem exige qualidade, força e suavidade. Especificações Técnicas: Rolamentos: 6+1 Freio: Magnético Disco de freio: Carbono Pinhão: Apoiado por rolamentos Corpo: Grafite Relação de recolhimento: 7.3:1 Drag (arrasto): 5 kg Manivela: Alumínio Coroa e pinhão: Bronze Yoke: Híbrido Peso: 207 g Capacidade de linha: 150 m / 0,23 mm Cores: Preto ou Prata Destaques da Carretilha Maruri Attack Leve, forte e resistente Suavidade incrível na recuperação Excelente para iscas artificiais Recuperação rápida (7.3:1) Ideal para pescadores iniciantes e profissionais Atenção: disponível nas cores Preto e Prata, selecione a cor na variação do anúncio!', 401.89, 279.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhc8u1ewfyf830', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F320275364%2F50301907925', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
