INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899260582', 'Pneu Dunlop SP Touring R1 Aro 14 - 185/65', 'O SP TOURING R1 traz para carros de passeio o melhor custo-benefício do mercado. Com estrutura reforçada, o SP TOURING R1 é uma excelente opção para você rodar sempre tranquilo. Sua banda de rodagem com desenho assimétrico, com desenho interno que auxilia na drenagem da água, e seus sulcos mais largos e profundos proporcionam excelente escoamento de água em situações de aquaplanagem. Possui desenho otimizado com quatro sulcos lineares Baixa resistência ao rolamento MODELO: 185/65R14 Dimensões Do Produto Altura: 59 cm Largura: 18 cm Profundidade: 59 cm Peso: 8,13 kg * Garantia do Fornecedor 12 Meses *', 409.9, 409.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/br-11134207-7r98o-majvnc85r1fddd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1243712796%2F21899260582', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206577421', 'Beliche em MDF com Pés em Madeira Escada até o Chão 0,88cm Arauna', 'O beliche Arauna é ideal para quem busca praticidade e melhor aproveitamento do espaço no quarto. Com design funcional e estrutura reforçada, ele oferece conforto e segurança para acomodar duas pessoas, sendo perfeito para quartos compartilhados ou ambientes compactos. Produzido em MDF com pés em madeira maciça, proporciona maior resistência e estabilidade no uso diário. A escada até o chão facilita o acesso à cama superior, enquanto a grade de proteção garante mais segurança durante o uso. O acabamento com pintura UV oferece maior durabilidade e melhor aparência ao móvel. Características do Produto: Marca: Arauna Estrutura em: MDF Pés em: Madeira maciça Escada até: O chão Grade de: Proteção na cama superior Estrado: Reforçado Acabamento com: Pintura UV Produto em: Madeira de Pinus Maciço e MDF Estrutura do Pé em: Madeira (100 x 55mm) Pintura com: Impressão UV e Verniz Bordas em: Esmalte PU e Fita de Borda Papel Soft Barra em: MDF de 22 mm 5 Travessa no: Estrado com Madeira Clean Reforçad Suporta até: 120kg com um colchão D-33 (cada cama) Informações do Colchão: - Indicado para colchão de 0,88 x 1,88 m (solteiro) - Colchões não inclusos Dimensões do produto: Altura: 160 cm Largura: 95,5 cm Profundidade: 200 cm Peso: 58 kg Garantia: 3 meses ⚠️ Observações Importantes: - As imagens são meramente ilustrativas e não acompanham objetos de decoração e eletros. - Pode haver alguma diferença de tonalidade entre a imagem e o produto, por conta do tratamento de imagens e a calibração de cores da sua tela. - Confira as dimensões do produto no momento da compra e certifique-se de que passará normalmente por elevadores, portas, escadas e/ou corredores, evitando assim futuros desagrados ou imprevistos com a entrega do produto. - A Lojas MM não se responsabiliza por montagens e instalações dos produtos.', 959.9, 959.9, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/br-11134207-820l8-mlmcdj4szoqv66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1243712796%2F58206577421', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
