INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099251694', 'Jogo 2 Pneus Goodyear Aro 13 Assurance Maxlife 165/70R13 83T XL', 'Marca: GOODYEAR Modelo: ASSURANCE MAXLIFE Medida: 165/70R13 Largura: 165 Perfil: 70 Tamanho de Aro: 13 Índice de peso: 83 - 487 kg Índice de velocidade: T - 190 km/h Tipo de Veiculo: CARRO Tipo de terreno: HT RunFlat: N/A Sidewall: BSW LETRAS PRETAS Extra Load: Sim Desenho: SIMÉTRICO UTGQ: N/A Adesão à àgua: E Eficiência energética: F Ruído externo: 70 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. O ASSURANCE MAXLIFE, novo pneu da família ASSURANCE fabricado pela GOODYEAR no Brasil, foi desenvolvido para atender consumidores que além de buscarem um preço acessível, buscam durabilidade para não terem que se preocupar com uma próxima troca tão cedo. Ele é produzido nos aros 13" e 14". Seu nome MAXLIFE (Máxima vida) foi escolhido com o intuito de mostrar seu principal benefício, a quilometragem. De acordo com a GOODYEAR, o novo pneu ASSURANCE MAXLIFE dura até 5.000 km a mais em relação a seu antecessor, graças ao novo composto de borracha utilizado na banda de rodagem, que faz com que o desgaste seja menor e aumente a vida útil do pneu. Sobre a marca Goodyear A marca Goodyear Considerada uma das maiores marcas de pneus no mundo, a Goodyear possui 2 centros de inovação, 48 fábricas e está presente em 22 países. Fundada por por Frank Seiberling em Akron, Ohio (EUA), já últrapassou os 100 anos de existência e hoje em dia conta com mais de 64 mil colaboradores no mundo todo. Investindo constantemente em inovação para fabricar pneus para automóveis, caminhões comerciais e leves, utilitários esportivos, carros de corrida, aviões e máquina agrícolas, é líder de vendas no mercado norte americano.', 990.81, 911.55, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdxj-lxlh9nt974w6b1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F20099251694', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497720976', 'Câmara de Ar Speedmax Aro 16 CM02-16 3.00/3.50-16', 'Sobre a SpeedMax A SpeedMax produz pneus para todos os tipos de veículo, com qualidade e custo que ao encontro com a sua busca por um pneu com ótima dirigibilidade, desempenho e economia para ter o máximo em qualquer situação - do campo ao asfalto. Pensados em Centros de Pesquisa e Desenvolvimento em países como China, Vietnã, Índia e Paquistão, a SpeedMax também tem produção feita no México e é homologada nos principais mercados, como Brasil e Estados Unidos.', 15.83, 14.57, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Inner Tubes for Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdxv-lywl09ujk1l394', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F22497720976', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
