INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15965447205', 'Capa Case Capinha Dual Shock X para Xiaomi Poco X3 / X3 Pro / X3 NFC - Gshield', 'Duas vezes mais forte = duas vezes mais protegido. Com a capa duplamente reforçada, o seu Xiaomi Poco X3 estará em segurança! A Capa Dual Shock para Xiaomi Poco X3 , da Gshield, foi projetada com uma dupla proteção. Além da proteção padrão de capas, a Dual Shock possui uma elevação na parte traseira que evita que a câmera entre em contato direto com os impactos. ESPECIFICAÇÕES Material: Polipropileno de alta densidade - Não Amarela. Marca: Gshield Dimensões: Dimensões exatas do aparelho Proteção: Contra impactos e riscos à traseira Certificações: Us Military Peso: 10G COMPATIBILIDADE Xiaomi Poco X3 ITENS INCLUSOS 1x Capa protetora', 87.97, 87.97, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/cd41dc516b28b4b7ec4a5fbc80fac629', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F15965447205', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398318079', 'Capa case capinha Clear View Para iPad – Proteção Completa e Design Funcional - Gshield', 'A fusão perfeita entre proteção avançada e funcionalidade prática para o seu iPad! A Capa Clear View para iPad, da Gshield, oferece uma defesa completa de 360° para a parte frontal e traseira do seu dispositivo. Sua estrutura leve e fina foi projetada para garantir a máxima proteção sem comprometer a elegância do seu iPad. Além disso, o mecanismo magnético inteligente assegura que o aparelho desperte ao abrir a capa e entre em repouso quando fechada, preservando a vida útil da bateria. Com sua funcionalidade prática, a parte frontal da capa Clear View pode ser dobrada em diferentes posições, transformando-se em uma base versátil para leitura, digitação, visualização de vídeos ou realização de chamadas FaceTime. Além de sua funcionalidade, a capa Clear View também possui um design sofisticado que inclui um discreto porta-lápis especialmente projetado para sua caneta touch, garantindo um armazenamento seguro e de fácil acesso para o acessório. Sua estrutura robusta e durável foi cuidadosamente projetada para resistir a impactos e arranhões, mantendo seu iPad seguro em todas as ocasiões. Seja em casa, no escritório ou em movimento, a Capa Clear View para iPad, da Gshield, oferece a proteção e a praticidade que você precisa, mantendo-se alinhada ao estilo de vida dinâmico! ESPECIFICAÇÕES Material: PU + TPU Marca: Gshield Dimensões: Dimensões exatas do aparelho Proteção: Contra impactos e riscos do dia a dia Certificações: Us Military COMPATIBILIDADE iPad ITENS INCLUSOS 1x Capa protetora', 119.97, 119.97, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7rd3k-m7bangofoip5c8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23398318079', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
