INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252186843', 'Kit 2 Protetor Solar Sundown Praia e Piscina FPS 70 200ml', 'PROTETOR SOLAR SUNDOWN PRAIA E PISCINA FPS 70 LOÇÃO Para corpo e rosto. Proteção imediata UVA + UVB. Resistente a água. Tripla proteção. Seguro para toda a família. O Protetor Solar Sundown Praia e Piscina foi especialmente desenvolvido para proteger o rosto e corpo em condições extremas, como o uso na praia e na piscina ou na prática de esportes ao ar livre. Protege a pele de queimaduras solares dentro e fora d’água. Ajuda a proteger a pele de elementos agressores como o cloro e agua salgada do mar. Resistente a água e suor. Proteção muito alta contra raios solares (UVA e UVB). Modo de usar: Aplicar abundantemente antes da exposição ao sol. É necessária a reaplicação para manter sua efetividade. Reaplicar sempre, após sudorese intensa, nadar ou banhar-se, secar-se com toalha e durante a exposição ao sol. Se a quantidade aplicada não for adequada, o nível de proteção será significativamente reduzido.', 177.98, 177.98, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/sg-11134201-823ri-mojpsdntleyo19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F58252186843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
