INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19371072317', 'Pandeiro Luen 10 Amarelo Pele Bandeira Aro Abs + Capa', 'Somos a Eletromusic Loja Especializada a mais de 10 anos no Mercado. Qual e o nosso diferencial? Buscamos sempre oferecer qualidade com excelencia por isso todos os nossos produtos sao de Fornecedores Nacionais com rigoroso controle de qualidade, possuem nota fiscal eletronica e garantia de fabrica. Voce e bem vindo para fazer parte da nossa historia PRODUTO PANDEIRO 10" PELE HOLOGRAFICA PERSONALIZADA BANDEIRA DO BRASIL LUEN + CAPA REFORCADA Profissional e resistente, o pandeiro de 10" da Luen com pele holografica e utilizado para execucao de diversos ritmos como samba, MPB, repente, Blues, Jazz e outros. Seu corpo e feito com ABS, um material plastico com a mesma resistencia dos materiais plasticos utilizados na industria automobilistica. Platinelas de Inox que evita o aparecimento de ferrugem com facilidade como as de latao. Por fim, a pele holografica da bandeira do Brasil de alta resistencia, possui um brilho espetacular. Oferecemos o corpo dos pandeiros nas cores: Verde, Amarelo e Azul. ESPECIFICACOES MARCA: Luen PELE: Holografica Bandeira do Brasil MATERIAL: Plastico ABS QUANTIDADE DE PLATINELAS: 5 MATERIAL DAS PLATINELAS: Inox PESO APROXIMADO: 515 g DIAMETRO APROXIMADO: 27 cm ALTURA APROXIMADA: 5 cm ITEM INCLUSO Chave de afinacao IMPORTANTE Imagens meramente ilustrativas.', 119.05, 119.05, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Percussion Instruments', 'https://cf.shopee.com.br/file/sg-11134201-23010-lkvpr2hk17lv01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F19371072317', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198854233', 'Restaurador Plástico Restaurax Revitalizador Proteção', 'Restaurax renova e restaura superfícies plásticas, como para-choques, painéis e laterais de portas. Sua fórmula contém polímeros especiais que também protegem as peças contra as ações do tempo, evitando degradação precoce do material. Tamanho: 500ML Diluição: Pronto uso Durabilidade: Até seis meses de proteção nos plásticos internos e sessenta dias nos plásticos externos Informações adicionais: Restaurax também pode ser usado em capota marítima Não recomendamos o uso do produto em couro -Renova e dá brilho -Protege contra a ação do tempo -Contém polímeros de última geração Modo de usar: Limpar bem a superfície e em seguida aplicar o produto com um aplicador de espuma até a completa restauração. Se necessário, repetir a operação. Para manter o plástico sempre novo, repetir a aplicação do produto a cada 60 dias na parte externa e a cada 6 meses na parte interna', 85.89, 65.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Wax', 'https://cf.shopee.com.br/file/sg-11134201-824gj-me1h9cqas7pcbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F712881035%2F23198854233', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
