INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19297383076', 'Kit 20 Discos De Lixa Flap 4.1/2 Grão 80 Esmerilhadeira', 'Distribuído Por Ismafer Ferramentas KIT 20 DISCO DE LIXA FLAP G80 – 4.1/2" X 7/8" – ACABAMENTO MÉDIO EM MADEIRA, PLÁSTICO, METAIS E PINTURA DESCRIÇÃO: O Disco de Lixa Flap G80 é a escolha ideal para quem busca um lixamento eficiente com acabamento médio em diversos tipos de materiais. Compatível com esmerilhadeiras padrão, é indicado para trabalhos em madeira, plástico, metais e superfícies pintadas. Proporciona rendimento elevado, durabilidade e desempenho profissional. VANTAGENS: - Granulação G80: ideal para acabamento médio, removendo imperfeições com eficiência; - Alta rotação de até 13.300 RPM, garantindo um trabalho rápido e uniforme; - Excelente resistência e longa vida útil mesmo em usos frequentes; - Aplicação versátil em diversos materiais e superfícies; - Ideal para uso profissional e doméstico. ESPECIFICAÇÕES TÉCNICAS: - Aplicações: Madeira, Plástico, Metais, Pintura - Diâmetro Externo: 4.1/2" (115 mm) - Diâmetro do Furo: 7/8" (22,23 mm) - Rotação Máxima: 13.300 RPM - Velocidade: 80 m/s - Grão: G80 (médio) APLICAÇÕES: - Indicado para acabamento e preparação de superfícies em marcenarias, funilarias, oficinas e serralherias; - Ideal para lixamento intermediário e remoção de resíduos, ferrugem e tinta. MARCA: Start SKU: KIT24819x20 Distribuído Por Ismafer Ferramentas', 129.9, 99.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8261c-mm66o18qyeiw49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F360012700%2F19297383076', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18797987004', 'Kit 2 Creme de Pentear Seda Cachos Definidos com 300ml', 'CREME DE PENTEAR SEDA CACHOS DEFINIDOS • O Creme para Pentear Seda Cachos Definidos conta com Infusão Ativa, que possui uma poderosa combinação de vitamina, óleo e proteína, desenvolvida para as necessidades do seu cabelo • Este creme para pentear contém pró-vitamina B5, conhecida por nutrir profundamente, óleo de coco, muito conhecido por suas propriedades nutritivas, e elastina, proteína com poder hidratante • Esse creme para pentear é indicado para cabelos cacheados. Pode ser usado diariamente • Este creme para pentear hidrata os cachos para o controle do frizz 24h, deixando-os prontos para uma super definição com o volume que você adora* • A fórmula do Creme para Pentear Seda Cachos Definidos conta com ingredientes poderosos • O Creme para Pentear Seda Cachos Definidos foi desenvolvido para deixar seu cabelo do jeito que você gosta. Juntas definindo nossos sonhos A vida é cheia de possibilidades - tenha um cabelo incrível para todas elas. Está pronta para conhecer o novo Seda? O Creme para Pentear Seda Cachos Definidos com Infusão Ativa tem uma poderosa combinação de vitamina, óleo e proteína, desenvolvido para as necessidades de seus cabelos cacheados. A fórmula deste creme contém pró-vitamina B5, conhecida por nutrir profundamente, óleo de coco, muito conhecido por suas propriedades nutritivas, e elastina, proteína com poder hidratante. Nossa fórmula, com ingredientes poderosos, hidrata os cachos para o controle do frizz 24h, deixando-os prontos para uma super definição com o volume que você adora*. O Creme de Pentear Seda Cachos Definidos é indicado para cabelos cacheados, podendo ser usado diariamente. Pronta? Aplique sobre o cabelo húmido. Não necessita enxágue. Pentear e dar forma como de costume. Para um cabelo ainda mais incrível, que tal combinar com o uso do Shampoo Seda Cachos Definidos e o Tratamento Condicionador Cachos Definidos? A garrafa do Creme para pentear Seda Cachos Definidos é feita com plástico 100% reciclável. Seda também possui a certificação PETA, o que garante que ele não é testado em animais. *com uso do Creme para Pentear Seda Cachos Definidos comparado com shampoo sem agentes condicionantes.', 28.98, 28.98, NULL, 'Beauty > Hair Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-8259p-mqm6qklbi39cdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F18797987004', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593013789', 'Pneu Moto Pirelli Aro 17 Sport Demon 150/70 -17 69H TL - Traseiro', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Pneu esportivo com estrutura convencional para motos Sport Touring de média cilindrada. Perfil do pneu traseiro desenvolvido com tecnologia de múltiplos raios, oferecendo condução precisa e controle em todas as condições de pilotagem. Composto de alta performance que assegura excelente rendimento quilométrico. Sobre a marca Pirelli A Pirelli nasceu na Itália há mais de 100 anos, em Milão. Com longa tradição na construção de pneus, a marca produz soluções para carros, motos, tratores, caminhões e ônibus e possui fábricas espalhadas pelo mundo. A Pirelli é a atual fornecedora de pneus da Fórmula 1, a principal categoria do automobilismo mundial, e possui longa tradição em pneus de alto desempenho.', 865.11, 795.91, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd5z-lvasu86gjtds69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F22593013789', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
