INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899195365', 'Macaco Hidráulico Tipo Garrafa Capacidade 4 Toneladas', 'Macaco Hidráulico Tipo Garrafa 3 Toneladas – NMHG3T Perfeito para o dia a dia de quem tem carros pequenos, médios e SUVs, o Macaco Hidráulico Tipo Garrafa 3 Toneladas – NMHG3T oferece elevação estável, rápida e segura para trocas de pneus e pequenas manutenções automotivas. Com capacidade de 3.000 kg (3 toneladas), ele atende com folga a maioria dos veículos de passeio, garantindo firmeza na elevação e praticidade no uso, seja em casa, na oficina ou na estrada. Leve e compacto, com peso bruto de 2,2 kg e peso líquido de 2,1 kg, é ideal para ficar no porta-malas, pronto para qualquer imprevisto. Recomendado para: Veículos pequenos Veículos médios SUVs Benefícios do produto Compatível com a maioria dos veículos de passeio: suporta até 3 toneladas, ideal para carros pequenos, médios e SUVs. Leve e fácil de transportar: com apenas 2,1 kg, é perfeito para ficar no porta-malas sem ocupar espaço. Elevação rápida e estável: garante mais segurança e praticidade na troca de pneus ou pequenos reparos. Uso simples: ideal tanto para motoristas comuns quanto para oficinas e autosserviço. Compacto: fácil', 81.0, 81.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-82259-mhd2rb6don4b99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F22899195365', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
