INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997594284', 'Colchão Viúva Ortobom ISO Dupla Face 128x188x20cm', 'ISO Dupla Face (20x128x188 SOBRE O PRODUTO O Colchão Ortobom ISO Dupla Face é a novidade da Ortobom entre os colchões mistos. Seu interior possui a leve e tecnológica placa EPS, que oferece perfeito suporte a camada de conforto em Espuma D28 Pró Aditivada de Alta Performance na parte superior, e uma espuma D33 na parte inferior, que pode ser ajustada para se adequar ao seu conforto Ideal. Esse colchão é para pessoas com até 80 quilos.. O tampo é bordado em Matelassê, que entrega uma camada extra de conforto. Seu revestimento é em 100% Poliester com tratamento antialérgico e antiácaro. CARACTERÍSTICAS Interior em placa EPS e camada de conforto em Espuma D28 em um dos lados, e camada de conforto em espuma D33 Pró Aditivada de Alta Performance no outro. Tecido em 100% Poliester, bordado em matelassê, tratamento antialérgico e antiácaro. Pillow: Não possui Peso (kg): 7.2837 Garantia: 03 Meses Altura (cm): 20 Antiácaro: Sim Antifungo: Sim Largura (cm): 128 Ortopédico: Não Antialérgico: Sim Tipo de Mola: Não Possui Possui Pillow: Não Precisa Virar: Sim Comprimento (cm): 188 Suporta Até (kg): 80 Tipo de Espuma: Espuma Poliuretano Tipo do Colchão: Espuma Misto Origem do Produto: Nacional Ambiente Principal: Quarto Densidade da Espuma: D-28 Revestimento do Colchão: Poliéster Serviço Impermeabilização: 102610509 Marca: Ortobom Tonalidade: Preto / Cinza Cor do Produto: Cinza/Preto Itens Inclusos: 1 Colchão e Manual Cor Predominante: Cinza', 1007.03, 1007.03, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rd74-lwmz9fw4ayze72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F23997594284', NULL, NULL, '2026-07-28T02:11:31.7