INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12498055575', 'Piscina Inflável Redonda 180 Litros Mor', 'Piscina Inflável Redonda 180 Litros Mor Com estampa de golfinhos e estrelas do mar, a Banheira Inflável da Mor é garantia de muita diversão para as crianças. Com capacidade para até 180 litros de água e medindo 1,20 metros de diâmetro, ela vai refrescar a garotada no verão e garantir muitas risadas! É excelente para uso em casa ou até em praias, o que evita maiores preocupações com o mar ou piscinas. Produzida em vinil resistente, contém duas câmaras de ar independentes, uma válvula deságue e adesivo reparo. É recomendada para crianças maiores de 2 anos. Atenção! Nunca deixe crianças sozinhas perto da água sem supervisão de um adulto. Descrição do produto Marca: Mor Materia: PVC Idade recomendada: Mais de 2 anos Cor: Azul Altura: 20 cm Largura: 1,20 m Comprimento: 1,20 m Peso: 546 g Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 148.87, 68.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Others', 'https://cf.shopee.com.br/file/sg-11134201-23010-9xj2bpgum3lvce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F12498055575', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499553964', 'Torneira Lorenzetti Em Abs Branco Bica Móvel C/ Filtro', 'A Torneira Lorenzetti Abs Bica Móvel Com Filtro Branco é uma solução inovadora para quem busca combinar funcionalidade e purificação de água em sua cozinha. Com o filtro Acqua Bella de 3 etapas de purificação, essa torneira oferece água limpa e segura para beber e cozinhar, além de ser prática para lavar louças e alimentos. Detalhes do produto: Filtro Acqua Bella 3 Etapas de Purificação: Garante água purificada para consumo diário, ideal para beber, cozinhar e preparar refeições saudáveis. Mecanismo Cerâmico de Acionamento Duplo 1/4 de Volta: Fácil de usar e durável, permite controlar o fluxo de água com precisão. Termostático com Tratamento Anti-UV: Protege o material contra danos causados pela exposição solar. Bica Móvel: Permite direcionar o fluxo de água conforme necessário, facilitando tarefas na cozinha.', 204.9, 121.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-7reph-m2jmm88w59w618', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965617276%2F19499553964', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
