INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42818067175', 'Sandália Feminina Lumiss Anabela De Dedo Confortável Enfeite Esfera Bico Redondo Off White', 'Com design sofisticado e detalhe em pedra no centro, essa anabela traz o toque de elegância ideal para produções casuais ou mais arrumadas. Perfeita para quem busca leveza sem abrir mão do estilo! ..:::.. ESPECIFICAÇÕES DO PRODUTO ..:::.. *Material - Napa Sintética *Solado - PVC Expandido, Emborrachado, Antiderrapante, Não faz Barulho, Não Escorrega. *Altura do salto - 7,5 cm. *Palmilha - Confortável com aplique da logo. Medida aproximada dos pés para cada numeração: Tamanho 34 --- 23,5 cm Tamanho 35 --- 24,0 cm Tamanho 36 --- 24,5 cm Tamanho 37 --- 25,0 cm Tamanho 38 --- 26,0 cm Tamanho 39 --- 26,5 cm Tamanho 40 --- 27,0 cm SOBRE A LUMISS: Desde 2018, brilha no coração da Lumiss a inovação para calçados femininos. Nascida como Amorelle, a marca é fruto do sonho de um visionário que sempre acreditou na possibilidade de fabricar calçados que surpreendessem o mercado, tanto pela variedade quanto por seus preços acessíveis. Com muito trabalho em família, essa ideia foi levada adiante, fortalecendo uma marca que hoje é referência nacional em calçados femininos, com presença marcante nos marketplaces e mais de dois milhões de pares já entregues em todo o Brasil. Comprometida com cada cliente, a Lumiss oferece as maiores tendências do mundo da moda a partir de materiais que garantem conforto, qualidade, sofisticação e estilo aos pés da mulher brasileira, encantando até mesmo os perfis mais exigentes. Além disso, a empresa se preocupa em oferecer a melhor experiência de compra, com total segurança e praticidade. Lumiss é mais que uma marca. É uma ideia que chegou para mostrar que todas as mulheres podem brilhar e ser ainda mais lindas e confiantes com calçados que as valorizam em todos os aspectos.', 189.9, 89.9, NULL, 'Women Shoes > Wedges', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meebaenmxt6p86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F323760756%2F42818067175', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51251679085', 'Uma Aventura Pop-up | Oceano em Movimento | Capa Dura', 'Pop Up incrível ! Pequenino para as crianças manusear com mais facilidades, cheio de engenharias, eles vão amar essa coleção !!! 16x16cm 10 Páginas', 21.9, 19.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821g9-mh8e6vadux3f8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F51251679085', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598053346', 'Como Você Pode Conhecer a Vontade de Deus | Kenneth E. Hagin', 'Deus nos ilumina e guia por meio do nosso espírito. Nós, contudo, buscamos orientação em muitos meios, exceto por intermédio do pai. Usamos os nossos sentidos, embora ele não tenha dito que nos guiaria por meio deles. Também procuramos usar a nossa perspectiva intelectual, mas a palavra de deus diz; deus é espírito, e importa que os que o adoram o adorem em espírito e em verdade. Somos seres espirituais - apesar de termos um alma e vivermos em um corpo, fomos feitos a semelhança do criador cujo próprio filho afirmou que deus é espírito. Existe um homem exterior, não representando de fato, mas sendo apenas uma "casa" (corpo) onde ele vive - e um interior onde reside o verdadeiro "eu". Nós não recebemos um corpo novo quando renascemos, porém o nosso "eu" verdadeiro foi renovado em cristo. As coisas espirituais são incompreensíveis aos olhos humanos, portanto, quanto mais conscientes do espírito nos tornamos, mais real a liderança do senhor será para nós. 11x15cm 72 Páginas', 17.9, 11.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rfgp-m38l64tveb87d0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23598053346', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
