INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23392653907', 'Caderno de Fé | Universitário Capa Dura Espiral | Jesus Loves Me', 'Memórias, estudos, sonhos ou mesmo simples anotações. Transforme sua vida tracejando suas palavras nos contornos da Palavra da Deus. Escreva uma nova história, esteja onde estiver, sempre com os olhos no alto e de mãos dadas com seu mais novo amigo, o seu “Caderno de fé”. Caderno com 80 folhas pautadas e um versículo ou frase de motivação em todas as paginas! Formato: 20cm x 27cm Número de folhas: 80 folhas (160 paginas) Capa e contracapa: Dura com papelão Miolo pautado padrão em papel offset 56g/m² Miolo com devocionais e frases motivacionais.', 31.9, 22.9, NULL, 'Stationery > Notebooks & Papers > Notebooks & Notepads', 'https://cf.shopee.com.br/file/sg-11134201-7rbkq-lodv167trm1s3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23392653907', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18598013153', 'Dez princípios antes do fim: Enunciado para uma vida possível | Emanuel Aragão', 'Este livro é a tentativa de colocar em palavras uma descoberta que mudou a minha vida. Ao contrário do que eu supunha até alguns anos atrás, as nossas emoções e os nossos sentimentos – nomes e organizações conceituais que damos a elas – não são consequência apenas de um desequilíbrio químico nem resultado de um excesso de planetas de água no seu mapa astral. As nossas emoções e afetos têm uma razão para existir assim como tudo mais o que existe. E essa razão de existir é o que trataremos aqui neste livro . Por que as emoções, os sentimentos e os afetos existem? E para que eles servem? 16x23cm 368 Páginas', 49.9, 47.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rfhm-m3mqsgf324i3b8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F18598013153', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57808015515', 'Tênis Masculino Rainha Haze II Casual Treino Academia Caminhada Corrida Leve', 'Tênis Haze II Rainha Modelo: RA0462 O Tênis Rainha Haze II é a escolha ideal para quem busca estilo urbano, conforto e excelente custo-benefício. Perfeito para treinos leves, caminhadas e uso casual, ele combina design moderno com praticidade para acompanhar sua rotina. Seu cabedal em tecido respirável mantém os pés frescos e confortáveis, mesmo durante longos períodos de uso. A entressola em EVA proporciona amortecimento leve a moderado, garantindo uma pisada mais suave. Com estrutura flexível e sem placa rígida, o modelo oferece liberdade de movimento e conforto natural. Características: - Marca: Rainha. - Modelo: Haze II. - Gênero: Masculino. - Categoria: Treino leve / casual. - Cabedal: Tecido respirável. - Forro: Têxtil confortável. - Palmilha: Macia. - Entressola: EVA com amortecimento leve. - Solado: Emborrachado com boa aderência. - Fechamento: Cadarço. - Indicação de uso: Caminhadas, academia leve e dia a dia. Benefícios: - Respirabilidade, mantendo os pés frescos. - Conforto no uso diário, com amortecimento em EVA. - Leveza e flexibilidade, ideal para movimentos naturais. - Versatilidade, combina com looks esportivos e casuais. - Ótimo custo-benefício, perfeito para rotina ativa. O Tênis Haze II Rainha pode ser encontrado aqui na Usee Brasil! Sobre a Usee Brasil: A Usee Brasil é uma empresa brasileira que oferece uma variedade de produtos de alta qualidade, desde roupas e acessórios até itens para casa. Tenha uma experiência conosco!', 359.99, 189.99, NULL, 'Sports & Outdoors > Sports Footwear > Training Shoes', 'https://cf.shopee.com.br/file/br-11134207-820m8-mqlwxzfkn0u827', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1559054473%2F57808015515', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
