INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5771641703', 'Oleo De Motor 5w40 Elaion FS540 Api Sn Sintético 1Lt', 'ELAION FS540 5W-40 100% sintético Descrição do produto Sua composição 100% sintética somada à tecnologia Flexlub de última geração e sua alta capacidade antiestresse garantem a proteção adicional ao motor, cumprindo com as mais exigentes especificações das grandes montadoras. Utilizado no enchimento inicial da produção dos veículos da Volkswagen da Argentina. Lubrificante 100% sintético, multiviscoso 5W-40, especialmente desenvolvido para veículos esportivos ou de alto nível de exigência que são equipados com qualquer tipo de motor e que utilizem qualquer tipo de combustível. Este produto cumpre com os segmentos mais severos da indústria automotiva. Apto para motores com sistema de pós tratamento que requeiram um nível ACEA C3 para proteção deste dispositivo. Utilizado no enchimento inicial da produção dos veículos Volkswagen da Argentina. Atende as especificações API SN, ACEA C3-A3/B4, VW 502 00, VW 505 01, VW 505.00, PORSCHE A40, BMW LL-04, MB 229.31 Atributos Incorporado com a tecnologia FLEXLUB Máxima proteção contra o desgaste Excelente capacidade de retardar a formação de borras e manter a fuligem em suspensão Máxima resistência a oxidação Apto para veículos que requeiram um nível ACEA C3 Análises Típicas ENSAIOS UNIDADE MÉTODO ASTM ELAION F50 Grau SAE ----- ----- 5W-40 Viscosidade a 100 °C cSt D-445 14,0 Ponto de Fulgor ºC D-92 225 Ponto de Fluidez °C D-97 -36 Os dados provenientes das análises típicas formam uma especificação, os mesmos são representativos de valores de produção. Níveis e Especificações API SN ACEA C3-A3/B4 VW 502.00/505.01/505.00 PORSCHE A40 BMW LL-04 RENAULT RN 0700/0710', 59.9, 59.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-23020-jh74wckyj0mv1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F295637446%2F5771641703', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
