INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18326698327', 'Top Up Nero Snd Fitness', 'O top Up, foi produzido em tecido de poliamida e elastano de alta compressão e possui o toque macio e geladinho, garantindo muito conforto. Sua modelagem possui encaixe perfeito ao busto, além de contar com 2 alças que oferecem mais segurança e liberdade nos movimentos. **Top sem bojo** A tecnologia do tecido conta com proteção solar permanente UV50+ e secagem rápida! Nesta foto, a modelo veste o Top tamanho P Qualidade Garantida Modelagem Fitness Exclusiva SND', 99.9, 77.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Sports Bras', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m01xs1wg3dk768', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F780631761%2F18326698327', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23199011118', 'Bermuda Feminina Modeladora Plie 50069', 'Diferencial PliéConforto e segurança total com efeito modelador contínuo até as pernas, deixando a silhueta perfeita sem restringir os movimentos. Como usar e combinar Fantástica peça para usar com vestidos e saias; modela e evita o atrito entre as pernas. Características do Produto Bermuda alta. Reduz medidas do abdômen e culotes. Modela bumbum. Melhora a postura e sustenta a região lombar. Cintura com dupla-faixa de silicone. Abertura higiênica traspassada. Sem costura laterais. Não marca sob a roupa. Fundinho 100% algodão. Lavagem à mão. Tratamento hidrófilo, para a pele respirar livremente. Equivalência de Tamanhos: P 40/42 M 44/46 G 48/50 Modo de Lavagem: Lavar a mão. Não usar cloro. Não secar a maquina. Não passar. Não lavar a seco. Composição: Corpo: 80% Poliamida, 15% Elastano e 05% Algodão Fundinho: 100% algodão.', 143.9, 143.9, NULL, 'Women Clothes > Lingerie & Underwear > Shapewear', 'https://cf.shopee.com.br/file/sg-11134201-824hm-mfnxvuapy22z88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401430924%2F23199011118', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
