INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20459323779', 'Capa Case Capinha MagSafe para iPhone 12 Pro Max - Preta - Gshield', 'A Capa MagSafe Preta para iPhone 12 Pro Max, da Gshield, foi projetada para dar mais segurança ao seu smartphone! Com design fino, leve e confortável, a capa além de proteger o seu celular irá manter o brilho e estilo original do aparelho! Desenvolvida com a combinação de policarbonato transparente, ela se encaixa perfeitamente ao smartphone e todos os materiais e coberturas são tratados para não amarelarem com o tempo. A tecnologia MagSafe na capa forma um anel de ímãs na traseira do celular para se conectar por magnetismo aos carregadores sem fios. Antes existia o risco de o usuário posicionar o aparelho de forma errada na base carregadora; agora, o MagSafe garante que o aparelho será sempre atraído para o ponto certo. Não compatível com uso de suporte magnético / Utilizar a placa para suporte magnetico poderá impossibilitar o carregamento Wireless OBS: O smartphone quando superaquecido durante o uso e/ou carregamento, transmite um calor que provoca uma reação química do material da capa que pode ocasionar uma aparência amarelada na mesma. ESPECIFICAÇÕES Material: policarbonato de alta densidade Marca: Gshield Dimensões: Dimensões exatas do aparelho Proteção: Contra impactos e riscos Cor: Preta COMPATIBILIDADE iPhone 12 Pro Max ITENS INCLUSOS 1x Capa protetora', 119.97, 119.97, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-22110-da385h919cjv67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F20459323779', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
