INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898693554', 'Sabonete Em Barra Protex Fresh 85g 6un', '*Produto Original* *Atenção:* Venda exclusiva para pessoa física. Pedidos com CNPJ serão cancelados. O Sabonete em Barra Protex Fresh cuida da pele do corpo, fragrância desenvolvida para um frescor duradouro. Oferece proteção antibacteriana natural com óleo de linhaça e elimina 99,9% das bactérias* naturalmente, mantendo você protegido por até 12h**. Contém 6 Sabonetes de 85g cada. Benefícios: - Mantém a boa saúde da sua pele: cria uma barreira de proteção que ajuda a prevenir a proliferação de bactérias. - Oferece proteção antibacteriana natural com óleo de linhaça, mantendo você protegido por até - 12h**. - Elimina 99,9%** das bactérias. - Fórmula enriquecida com óleo de linhaça. Modo de Uso: Aplique nas mãos, corpo ou região desejada até criar uma pequena espuma. Enxágue em seguida. Precauções: Manter fora do alcance de crianças. Evite contato com os olhos. Havendo irritação ou sensibilidade, suspenda o uso e consulte um dermatologista. * Após lavar as mãos com sabonete por 40 segundos. ** Bactéria testada E. coli, C. acnes, S. pyogenes, S. pneumoniae.', 19.08, 19.08, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7rdwt-mbqyw3k4944a6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1458515228%2F22898693554', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
