INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7783220230', 'Alarme + Modulo De Vidro Corolla 2003 A 2008.', 'Alarme Look Out Al 25 XR Com 2 Controles O alarme AL 25 XR possui diferentes modos de funcionamento integrados: - modo alarme, monitoramento do sensor das portas, sensor ultrassom (INCLUSO), e chave de ignição. E em caso de disparo informa em qual ponto de monitoramento o alarme foi acionado. - modo resgate, em caso de roubo após 15 segundos dispara a sirene e após 50 segundos realiza o bloqueio do veículo; - modo localizador, para localizar o veículo em grandes estacionamentos através da sinalização da setas; Especificações Técnicas: - Produto: Alarme Automotivo - Marca: Look Out - Modelo: AL25 XR - Liga e Desliga o Alarme com Sinal Visual ou Visual e Sonoro - Controle Remoto Auto Code com Alcance Médio de 30 Metros - Sistema de Bloqueio de Motor Temporizado (Anti-Assalto) - Travamento Automático das Portas com a Chave de Ignição Ligada - Rearme Automático - Sensor ultrasom - Saída para Travamento Universal das Portas (Não Acompanha Travas) - Saída para Fechamento de Vidros Elétricos (Não Acompanha Módulo) - Saída Temporizador para Linha Volkswagem G5 (Se o Veículo Possui esse Tipo de Ligação) - Função Auto Trava - Função Pânico ou Localizador - Aceita Gravação de Até 4 Controles - Tensão de Operação: 11V - 16V - Consumo de Corrente: 25mA - Bloqueio: 7A - Pressão Sonora da Sirene Piezo-elétrica: 110dB a 1 Metro de Distância - Setas: 2x7A - Frequência de Transmissão: 433,8MHz - Alcance médio: 30 metros - Baterias Transmissor (1xCR2032): 3V - Medidas Aproximadas do Produto (AxLxC): Padrão - Medidas Aproximadas da Embalagem (AxLxC): 7x10x9 cm - Peso Aproximado: 1kg Conteúdo da Embalagem - 01 Central - 01 Sirene - 02 Controle Remoto - Chicotes - 02 Sensores Ultrasom DESCRIÇÃO MÓDULO SUBIDA QUANTUM QA 108: FABRICADO COM ALTA TECNOLOGIA E MATERIAIS DE EXCELENTE QUALIDADE, ESTE MÓDULO DE SUBIDA DE VIDRO ELÉTRICO QA108 DA QUANTUM É O ACESSÓRIO IDEAL PARA QUEM ESTÁ EM BUSCA DE UMA FORMA EFICIENTE PARA AUMENTAR A SEGURANÇA DO SEU CARRO E TORNAR SEU USO DIÁRIO MAIS PRÁTICO. CONVERTENDO OS VIDROS ELÉTRICOS ORIGINAIS DO SEU VEÍCULO EM VIDROS INTELIGENTES, ELE PERMITE A SUBIDA E A DESCIDA COMPLETA COM UM ÚNICO TOQUE DE BOTÃO E O FECHAMENTO DOS VIDROS, GARANTINDO MAIS CONFORTO. DESCIDA EXPRESSA PELOS BOTÕES E VIA ALARME: - SOBE 2 VIDROS POR VEZ AO RECEBER SINAL DO AUXILIAR DO ALARME; - CONFIGURAÇÃO DOS TIPO DE DESCANSO NOS MOTORES, POSITIVO, NEGATIVO OU MISTO; - DESCIDA DOS VIDROS PARA VEÍCULOS COM CENTRAL ELETRÔNICA SEM A NECESSIDADE DE ACESSÓRIOS EXTERNOS; TEMPORIZAÇÃO DOS BOTÕES POR 1 MINUTO: - TEMPORIZA OS BOTÕES POR 60 SEGUNDOS. CONTEÚDO DA EMBALAGEM: - 1 - MÓDULO DE VIDRO QUANTUM QA 108', 360.99, 325.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/d5154ce304fd4ad2a5d94cade0a90c61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341544056%2F7783220230', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
