INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259660770', 'Coqueiro Sardinha com Óleo', 'A Sardinha Coqueiro é uma ótima opção para incluir mais peixe na sua alimentação, de forma prática e deliciosa. Fonte de proteína, ômega 3 e vitamina D, tudo pronto para comer e sem conservantes. Combina com diversos pratos, como macarrão, cuscuz, lanches e saladas.', 8.79, 8.79, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/sg-11134201-82616-mj72nvxbfuo6c7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554850%2F58259660770', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
