INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593289400', 'Limpa telas Clean com flanela Implastec 60ml', 'Limpa telas Clean c/ flanela Implastec 60ml O Limpa telas Clean com flanela Implastec 60ml foi especialmente desenvolvido para a remoção de manchas e poeira de monitores de LCD e Plasma, eliminando a estática do monitor, o que reduz o acúmulo de pó na tela. Qualidade e Segurança Produzido a base de éteres glicólicos e água, possibilita a limpeza sem agressão ao monitor. Ideal para Pode ser utilizado para limpeza de tablets, smartphones, monitores de PC, TVs (Plasma, LCD e LED), projetores, GPS, câmera digital, entre outras aplicações. Especificações Aplique o Clean Limpa Telas Implastec sobre a flanela e em seguida passando este sobre o monitor. Remova-o na sequência com auxílio de toalha multi-uso até secar completamente. Garantia: 6 meses de garantia direto com o fabricante Referência: IM012', 38.45, 38.45, NULL, 'Cameras & Drones > Camera Care > Cleaning Kit', 'https://cf.shopee.com.br/file/sg-11134201-825ao-mq6qtef3eku91c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F392651618%2F22593289400', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
