INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099595547', 'Driver JBL D409Ti 150W RMS 8 Ohms Titânio', 'O Driver JBL D409TI é um dispositivo de áudio profissional projetado para reproduzir frequências médias e altas com clareza e precisão. Com potência de 150W RMS e impedância de 8 ohms, é ideal para sistemas de som automotivo e profissional. Características Principais: Diafragma de titânio: Proporciona alta sensibilidade e resposta de frequência estendida. Bobina de 4 polegadas: Permite maior manuseio de potência e durabilidade. Design compacto: Facilita a instalação em diversos tipos de caixas acústicas. Resposta de frequência: 300 Hz a 17 kHz, cobrindo uma ampla gama de sons. Sensibilidade: 111 dB SPL, garantindo alta eficiência e volume. Potência: 150W RMS Impedância: 8 ohms Resposta de frequência: 300 Hz - 17 kHz Sensibilidade: 111 dB SPL Diâmetro da garganta: 2 polegadas Material do diafragma: Titânio Material da bobina: Cobre Conteúdo da Embalagem: 1 Driver JBL D409TI 1 Certificado de garantia', 1238.97, 1139.86, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-820m5-mlwbp63cjk071a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F329035577%2F20099595547', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699185573', 'Rack Bancada para TV até 55 Polegadas 1,36m Ripado Impressão 3D 1 Porta Cedro Aruba EDN', 'O Rack Bancada Aruba é a escolha perfeita para elevar o estilo e a funcionalidade da sua casa! O detalhe ripado em impressão 3D garante sofisticação que transforma seu espaço em um ambiente moderno e convidativo. Conta com espaço para aparelhos eletrônicos e decorações, além de possuir 1 porta de correr com suave deslize e pés resistentes em madeira que não agridem o piso. Acomoda TV até 55 polegadas! MEDIDAS: A = 58 cm L = 136 cm P = 36 cm MEDIDAS DOS PÉS: A = 22 cm L = 6,5 cm P = 2,5 cm PRATELEIRA SUPORTA ATÉ: 5kg PRODUTO SUPORTA ATÉ: 30kg PESO: 21,40kg RACK SUPORTA TV''S DE ATÉ: 55 Polegadas MODELO: Rack Bancada Para TV Até 55 Polegadas 1,36m Ripado Impressão 3D 1 Porta Aruba COR: Cedro MARCA: EDN ACABAMENTO: Pintura UV MATERIAL DA ESTRUTURA: MDP/MDF ESPESSURA DO MATERIAL: 12mm PORTAS: 1 TIPO DE PORTA: Deslizante PRATELEIRAS: 1 PÉS: 4 unidades, retrô MATERIAL DOS PÉS: MDF GARANTIA: 3 meses pelo fabricante DIFERENCIAL: Tampo com borda laqueada, porta deslizante com acabamento em design moderno, trilhos em ABS. INSTRUÇÕES/CUIDADOS: Para maior durabilidade, recomendável que a limpeza dos móveis seja feita com pano limpo e levemente umedecido em água e sabão neutro. Em seguida, deverá ser passado um pano limpo e seco. ITENS INCLUSOS: 1 Rack Bancada, 1 Manual de Montagem, 1 Kit Parafusos A Esplanada Móveis se responsabiliza pela entrega dos produtos adquiridos até a porta de entrada ou portaria do endereço indicado, se a portaria do condomínio permitir, as entregas são efetuadas no piso térreo e é de responsabilidade do cliente a locomoção da mercadoria até seu apartamento ou casa. Confira as dimensões do produto e certifique-se de que estão adequadas aos elevadores, portas e corredores do local da entrega. Não fazemos a montagem, desmontagem do produto e/ou portas e janelas, transporte pela escada ou içamento pelo lado de fora do prédio. Não está incluso no serviço de entrega o deslocamento até o interior do apartamento, com ou sem elevador, ou deslocamento em locais de difícil acesso como escadarias.', 379.0, 359.0, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-82582-mgcbobpg8sunaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1097902002%2F20699185573', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
