INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13732807666', 'Cartucho HP 667XL Original 3YM81AB Preto p/ Deskjet 2376, 2776, 6476, 5076, 5276', 'Conte com os cartuchos de tinta originais HP para obter desempenho de impressão. Ajude a garantir impressões nítidas e intensas em casa, na escola e no trabalho com cartuchos desenvolvidos e testados com a impressora HP e projetados para facilitar o uso. Detalhes: - Rendimento: 480 páginas - Impressões que funcionam todas as vezes. Cartuchos projetados para alto rendimento - Impressões resistentes à água e que não desbotam com o tempo - Cores mais vibrantes e nítidas. Com Tecnologia anti curvas - Fotos e documentos que duram mais de 50 anos sem perder a cor e a qualidade - Resultados superiores da primeira à última página, sem obstruções ou impressões com bandas - Impressão sustentável, os cartuchos HP originais são feitos com até 50% de material reciclado. Compatibilidade - Deskjet Ink Advantage 2376 - Deskjet Ink Advantage 2776 - Deskjet Ink Advantage 6476', 256.88, 249.0, NULL, 'Computers & Accessories > Printers & Scanners > Inks & Toners', 'https://cf.shopee.com.br/file/sg-11134201-824g2-mf0414k7mx3d0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F13732807666', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54305904746', 'Central Multimidia Auto CarPlay Android Auto 7" Polegadas USB Espelhamento Apps Entrada Câmera Ré', 'Multimídia MP5 2DIN Tela 7” Touch Screen – Android Auto e CarPlay com Fio A Multimídia MP5 HT-5625CA é a escolha ideal para quem busca mais tecnologia, conectividade e qualidade sonora no veículo. Com tela de 7 polegadas Touch Screen, oferece navegação intuitiva e acesso rápido às principais funções, deixando sua experiência ao volante muito mais prática e segura. Compatível com Android Auto e Apple CarPlay com conexão via cabo (consulte versões compatíveis), permite espelhamento do celular para uso de aplicativos, mapas, músicas e chamadas diretamente na tela da multimídia. Conta ainda com potência de 4x60W RMS, garantindo um som potente e bem definido, além de múltiplas opções de entrada para ampliar suas possibilidades de entretenimento. ATENÇÃO: Anuncio não acompanha camera de ré. Destaques do Produto Tela de 7” Touch Screen para fácil interação Potência de 4x60W RMS para som mais forte e limpo Conectividade Android Auto e CarPlay com fio Espelhamento de celular com fio Bluetooth para chamadas e reprodução de músicas Entradas USB, SD e AUX Controle remoto para maior comodidade Compatível com câmera de ré Especificações Técnicas Tela: 7” Touch Screen Potência: 4x60W RMS Cores dos botões: 7 opções de iluminação lateral Conectividade: Android Auto (com fio) Apple CarPlay (com fio) Espelhamento de celular (com fio – consulte compatibilidade) Entradas: USB / SD / AUX / Bluetooth Entrada de vídeo: 1 Saídas de áudio e vídeo: 2 Entrada para câmera de ré: 1 Comando de volante (SWC): 2 fios Grava até 10 funções Dimensões e Peso Altura: 20,5 cm Largura: 15 cm Comprimento: 11,1 cm Peso: 0,651 kg Conteúdo da Embalagem 1 Multimídia MP5 2DIN Acessórios para instalação 1 Co