INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203554460', 'Emblema Lateral Complementar L.e Polo virtus Original Vw', '6EA853689CFOD Emblema Lateral Complementar L.e Polo virtus Original Vw. GARANTIA: 90 DIAS - Enviando Normalmente para todo Brasil. Somos a Concessionária DISCAUTOL VEICULOS Autorizada Volkswagen em Campo Grande MS * CONSULTE A COMPATIBILIDADE COM SEU VEÍCULO * Antes de efetuar a compra, envie numero do CHASSI do veículo no campo de perguntas. # O CHASSI é o código de identificação do veículo (como um CPF), que identifica todas as peças compatíveis, composto por 17 caracteres entre letras e números. # Encontre o CHASSI nos vidros, no RENAVAM e / ou próximo ao motor, na carroceria.', 39.18, 39.18, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rdvd-mbwwxgbthk4c74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1663927767%2F58203554460', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799665469', 'PATINS TRILINE 3 RODAS 2 EM 1 AJUSTAVEL ROSA PP 27 A 30 - BW022RPP', 'Patins 3 Rodas 2 Em 1 Bota Ajustável Importway Rosa Patins 2 em 1, esse lindo patins irá garantir a diversão da criançada, passa mais segurança e equilíbrio, pode ser usado como inline ou triline, ideal para quem está começando a treinar. Além de ter um designer moderno, sua bota é ajustável Especificações: *Marca: Importway *Modelo: BW022R *Cor: Rosa *Sistema de Configuração Fácil *2 Travas de Segurança *Freio Traseiro no Pé Direito *Peso Máximo: 50kg *Rolamento de Aço *Pode ser usado como Inline ou Triline *Indicado compra de um número maior ao calçado *Certificado pelo Inmetro Conteúdo da Embalagem - 01 Patins 3 Rodas 2 Em 1 Bota Ajustável Importway Rosa "Compra Garantida" - Ao Comprar conosco a sua compra é 100% garantida, o seu dinheiro está seguro até a entrega. *Garantia 90 dias. *Imagens meramente ilustrativas Importway Importando Soluções com Qualidade, Inovação e Responsabilidade desde 2007.', 206.22, 206.22, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd69-m7mpm0hmi06wb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1499808573%2F21799665469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259717961', 'Margarina com Sal Qualy', 'A Margarina Qualy com Sal é cremosa e saborosa, perfeita para o seu dia a dia. Ideal para acompanhar pães, torradas e brioches no café da manhã ou lanche da tarde. Qualy Cremosa contém o exclusivo QMIX, uma combinação de vitaminas, selênio e Ômega 3, que são essenciais para a sua saúde. Além disso, a cada pote vendido, outro é reciclado, mostrando o compromisso da Qualy com o planeta.', 10.79, 10.79, NULL, 'Food & Beverages > Dairy & Eggs > Butter & Margarine', 'https://cf.shopee.com.br/file/sg-11134201-8259f-mqnelhp7iolr2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554900%2F58259717961', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
