INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899158641', 'Kit Cozinha Itatiaia Florença Grafite 2 Peças', 'Cozinha Compacta Itatiaia Florença 2 Peças 4 Portas Grafite A Cozinha Compacta Itatiaia Florença 2 Peças é ideal para quem busca praticidade, durabilidade e um toque moderno na cozinha. Fabricada em aço de alta qualidade com pintura eletrostática a pó, oferece resistência contra ferrugem, fácil limpeza e longa vida útil. O kit é composto por: Balcão com 2 portas e tampo em MDP, ideal para guardar utensílios e apoiar pequenos eletrodomésticos. Armário aéreo com 2 portas em aço e 2 prateleiras internas, perfeito para organizar pratos, copos e mantimentos com praticidade. Com acabamento na cor Grafite, seu design moderno combina facilmente com diversos estilos de cozinha, unindo funcionalidade e elegância. CARACTERÍSTICAS GERAIS Linha: Florença Marca: Itatiaia Cor: Grafite Material: Aço Acabamento: Pintura eletrostática a pó Escala de brilho: Semibrilho Tipo: Cozinha Compacta 2 Peças (Balcão + Armário Aéreo) BALCÃO 2 portas e 2 prateleiras internas Tampo em MDP Pés reguláveis em polipropileno Dobradiças metálicas Dimensões: 92 cm (A) x 70 cm (L) x 45 cm (P) Peso: 13,55 kg ARMÁRIO AÉREO 2 portas em aço 2 prateleiras internas Dobradiças metálicas Dimensões: 55 cm (A) x 70 cm (L) x 28 cm (P) Peso: 7,8 kg INFORMAÇÕES ADICIONAIS Total de portas: 4 Total de prateleiras: 5 Peso máximo por prateleira: 10 kg Cor interna: Branco Garantia: 12 meses pelo fabricante Limpeza: pano levemente umedecido Imagens ilustrativas. Não acompanham objetos de decoração.', 899.9, 669.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134207-820l6-mnx12azscg0262', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F680601528%2F22899158641', NULL, NULL, '2026-07-28T02:11:3