INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792559732', 'Correia Alternador Fiat Palio 1.0 1.5 8V 96 a 2017 Micro V Gates', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. O motor do carro foi criado para gerar sua própria energia, mas esta ação só é possível pela existência do alternador. O alternador é acionado por uma correia ligada ao motor, que gera corrente alternada que é transformada em corrente contínua. Dessa forma o carro passa a ter energia para usar som, ar-condicionado, vidros elétricos, etc.', 62.33, 62.33, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7ra3e-mbcrkuudxclf0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F23792559732', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
