INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28479481791', 'Spray Mop 2 em 1 Flashlimp', 'Spray Mop 2 em 1 Flashlimp O Mop Spray 2 em 1 possui reservatório para acondicionamento de água ou produtos químicos de sua preferência. O spray é acionado facilmente por uma alavanca posicionada ao alcance de suas mãos. O refil de microfibra é lavável e pode ser substituído ao final de sua vida útil. Conte com a praticidade de limpar chão, janela, vidros e outras superfícies com um único produto. Material: PP / Aço inox / ABS / PET / PE / Sílica Gel Capacidade: 365ml Medidas: - Para Janelas: 27cm (Altura) x 8cm (Largura) x 133,5cm (Profundidade) - Para Chão: 11cm (Altura) x 37cm (Largura) x128cm (Profundidade) - Base para Janela: 7cm (Altura) x 27cm (Largura) x7,5cm (Profundidade) - Base para Chão: 11cm (Altura) x 37cm (Largura) x10cm (Profundidade) - Reservatório: 5cm (Altura) x 6,5cm (Largura) x20cm (Profundidade) Embalagem: Contém 01 Mop Spray / 01 microfibra para janelas / 01 microfibra para chão / 01 base para janelas / 01 base para chão', 230.67, 230.67, NULL, 'Home & Living > Home Care Supplies > Mops', 'https://cf.shopee.com.br/file/sg-11134201-7rd6b-m7b0uz7b6x0p17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946161700%2F28479481791', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
