INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49504219860', 'Prancha Alisadora Mondial Black Rose com Revestimento Cerâmico Preto/Rose Bivolt - P-27', 'Muito mais proteção para seus fios! A Prancha Alisadora Black Rose P-27 possui tecnologia Protect Care, que protege a saúde do cabelo por meio de condicionamento iônico e aquecimento controlado. Além disso, o revestimento com Tourmaline Íon ainda promove um liso intenso e com muito brilho. BENEFÍCIOS: REVESTIMENTO CERÂMICO + TOURMALINE ÍON: As placas têm revestimento de cerâmica com Tourmaline Íon, tecnologia que emite íons e fecha a cutícula dos fios. O resultado é um cabelo com menos frizz e muito mais macio, brilhante e lindo! TECNOLOGIA PROTECT CARE: Preserva a saúde dos fios através do condicionamento iônico e aquecimento controlado. MECHAS SEM MARCAS: As chapas flutuantes adaptam-se às mechas para deslizar suavemente, garantindo um alisamento suave e sem marcas. TEMPERATURA: A prancha alisa perfeitamente todos os tipos de cabelo e chega a até 220°C! BIVOLT: Pode ser ligada em tomadas 127V e 220V: liberdade de ligar sua prancha onde quiser! TRAVA DE SEGURANÇA: Com as chapas fechadas, você evita queimaduras e consegue guardar o item com muito mais facilidade. CABO GIRATÓRIO 360°: Mais fácil de manusear: o fio da prancha para cabelos é giratório e não enrola durante o uso. DIMENSÕES E INFORMAÇÕES TÉCNICAS: Altura: 3,5cm Largura: 30cm Profundidade: 3cm Peso: 260g Tensão/Voltagem: Bivolt Cor: Preto/Rosê CONTEÚDO DA EMBALAGEM: 1 Prancha Alisadora 1 Manual de Instruções', 179.88, 115.9, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-82621-mj5lpb3rv66f21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1296760327%2F49504219860', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29079224780', 'Guardanapo Pequeno Folha Simples Advanced Xpressnap com 500un Tork', 'Guardanapo Pequeno Folha Simples Advanced Xpressnap com 500un Tork O refil Tork Advanced guardanapo Xpressnap café folha simples, com percepção de folha dupla, pois o guardanapo sai do seu dispenser dobrado ao meio. Desenvolvido para ser utilizado nos dispensers da linha Tork Xpressnap, esse sistema inteligente libera um guardanapo por vez, evitando o uso excessivo e proporcionando maior controle no consumo. Além de garantir que os clientes toquem apenas no guardanapo que irão utilizar, promovendo uma experiência mais higiênica e sustentável. Indicação de Uso: - Uso exclusivo nos dispensers da linha Tork Xpressnap; - Ideal para ambientes movimentados, como lanchonetes, fast-foods, cafeterias, padarias, food trucks, restaurantes e bares. Dispenser Compatível: - 101934 - Dispenser Guardanapeira Xpressnap Café Tabletop Preto (Sistema N10) Cód. de Fáb.: 080132XRT Cor: Branco Tamanho: Pequeno Dimensões: 21,6cm x 21,6cm (desdobrado) Embalagem: 01 pacote contém 500 folhas', 71.32, 71.32, NULL, 'Home & Living > Home Care Supplies > Tissue & Paper Towels', 'https://cf.shopee.com.br/file/sg-11134201-8262b-mkl0xo7xtiiu84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946161700%2F29079224780', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
