INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10775109625', 'Revitalizador de plásticos e borrachas spray 300ml luxcar', 'Somos a Go! Mec Auto Peças, estamos no ramo de autopeças para veículos nacionais e importados há quase duas décadas, nosso estoque conta com uma variedade de 45000 itens. Todos os nossos produtos são novos, originais e com garantia._x000D_ _x000D_ Este anúncio contém os seguintes produtos:_x000D_ _x000D_ 300 ml_x000D_ O Revitalizador de Plásticos e Borrachas Luxcar, foi desenvolvido para reavivar a cor e aparência original das superfícies plásticas do seu carro. Pode ser utilizado na parte interna e externa, ideal para revelar as cores em para-choques, painéis, maçanetas, acabamentos plásticos, frisos e borrachas de portas, pneus, tapetes de borrachas, capotas marítimas, entre outros._x000D_ _x000D_ Vantagens:_x000D_ • Recupera a cor e aparência original._x000D_ • Realça, renova e reaviva as cores originais._x000D_ • Evita o ressecamento._x000D_ • Promove um brilho duradouro._x000D_ _x000D_ Modo de usar:_x000D_ Agite antes de usar. Limpe e seque a superfície antes do uso. Com uma esponja aplicadora, espalhe o produto por toda a superfície e em seguida retire o excesso com uma flanela ou pano de microfibra._x000D_ _x000D_ Validade 24 meses.', 33.0, 33.0, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/5764738d631a382205289ea36f235fcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549478150%2F10775109625', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45261189242', 'Pista De Carrinho Unicórnio Castelo Brinquedo Menina Rosa', 'Pista Mágica de Unicórnio Transforme o momento da brincadeira em uma experiência encantadora com a Pista Mágica de Unicórnio. Este brinquedo combina cores vibrantes, movimento e interatividade em um cenário lúdico com castelo e carrinho temático. O carrinho em formato de unicórnio percorre toda a pista empurrando a bolinha, criando um efeito dinâmico que estimula a atenção e a curiosidade. O conjunto auxilia no desenvolvimento cognitivo, coordenação motora e imaginação. Características: Tema de unicórnio com design lúdico Castelo decorativo estilo conto de fadas Carrinho motorizado que movimenta a bolinha pela pista Circuito interativo de montagem fácil Cores vibrantes Material: Plástico resistente e durável Conteúdo da embalagem: 01 Carrinho de unicórnio 01 Pista para montagem 01 Castelo decorativo 01 Portal decorativo 01 Bolinha Especificações: Tema: Unicórnio / Fantasia Idade recomendada: A partir de 3 anos Montagem simples e rápida Produto leve e seguro para uso infantil', 149.9, 78.9, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-823qs-mophgdfdd7gg85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F438068303%2F45261189242', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
