INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098443611', 'Lancheira Grande Sestini Grafitti - Colorido', 'Mantenha o lanche fresco e organizado com a Lancheira Grande Sestini Grafitti - Colorido, uma opção divertida e espaçosa que combina com o estilo de vida ativo das crianças. Feita em poliéster, garante resistência ao uso diário e facilidade de limpeza. Alças de costas espumadas e reguláveis: Conforto ergonômico para o transporte. Alça de mão espumada: Praticidade ao carregar. Alça carona: Facilita o transporte em conjunto. Tag identificador: Ajuda a personalizar e identificar a lancheira. Bolso lateral com elástico: Ideal para armazenar garrafinhas ou pequenos itens. Logo em borracha: Design moderno e durável. Interior resistente a líquidos: Protege contra vazamentos e facilita a limpeza. Acompanha garrafinha e potinho: Completa o kit para a hora do lanche. Fechamento com zíper: Segurança e praticidade no uso. Fácil limpeza: Mantém a lancheira sempre nova e higienizada.', 69.9, 69.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-8261s-ml5k9273oa31b7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F867958784%2F22098443611', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
