INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56064656598', 'Fones de ouvido TWS X55 para dormir, Bluetooth sem fio, som estéreo Hi-Fi, microfone com cancelamento de ruído, à prova', 'Característica: - Fones de ouvido confortáveis para dormir: muito confortáveis de usar - Controle com um único botão - Microfone integrado - Exibição de bateria por LED - Qualidade sonora Hi-fi - Bateria dos fones: 35mAh - Bateria da caixa de carregamento: 350mAh - Tensão: 5V=1A Como emparelhar: 1. Certifique-se de que os fones estão carregados. 2. Retire ambos os fones da caixa de carregamento ao mesmo tempo (esquerdo e direito irão se conectar automaticamente). 3. Aguarde 5 segundos. 4. Ative o Bluetooth no seu dispositivo. 5. Encontre o ícone "TWS" na lista de Bluetooth e toque para emparelhar. 6. O ícone "TWS" aparece na lista emparelhada—conexão realizada com sucesso.Fones de ouvido amigáveis ao sono – extremamente confortáveis para uso noturno Qualidade de som hi-fi – aproveite um super prazer Microfone embutido e controle de um botão Fones de ouvido: 35mAh | Estojo de carregamento: 350mAh | Voltagem: 5V=1A Emparelhamento: Retire ambos os fones de ouvido ao mesmo tempo Espere 5 segundos Ative o Bluetooth Toque em "TWS" na lista de dispositivos Conexão bem-sucedida Display LED da bateria Perfeitos para dormir, viajar e uso diário', 25.0, 24.5, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/sg-11134253-8257s-mqxqcsf5yept40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F56064656598', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22196761133', 'Violao Classico Eletroacustico Strinberg Black Sl200c Mahog', 'Desfrute com este violao Strinberg da conexao com a musica. Ele e projetado para amadores e profissionais. Com este instrumento voce vai descobrir novos acordes, cantar suas cancoes e vai desfrutar da vida musical. Som amplificado Sendo eletroacustico, e possivel obter um melhor som e aumentado ao conecta-lo a um sistema de alto-falantes. Um modelo para cada guitarrista A tampa de abeto gera um tom brilhante e claro, mesmo nos registros mais agudos. Qualidade se destaca As cordas de nylon sao caracterizadas por serem flexiveis e resistentes. Garantem a durabilidade e alem disso tem um grande poder de absorcao da carga de choque.', 935.0, 935.0, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/br-11134207-820m8-mm62sb91mdq828', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F22196761133', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
