INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21397682391', 'Shampoo Dove Men 2 em 1 Forca Resistente 400ml', 'O Shampoo Dove Men 2 em 1 Força Resistente 400ml é ideal para homens com a vida agitada, cheia de trabalho e muitos compromissos e não tem tempo a perder! Principalmente para aqueles que curtem praticidade, pois já vem shampoo e condicionador em um único produto. Rápido, prático e fácil. Sua fórmula deixa os fios mais fortes e mais resistentes à queda. Perfeito para os homens que estão com os cabelos finos, ralos e desejam dar mais força e recuperar. Sua fórmula contém cafeína e cálcio, que limpam profundamente a oleosidade e a sujeira que fica acumulada no couro cabeludo. Pode ser udado em cabelos oleosos. Está cansado de usar shampoos e produtos femininos? Dove Men Care traz uma linha de produtos para cada tipo de necessidade, e traz o cuidado ideal para os cabelos dos homens. Conheça também o Creme para Pentear Dove Men Care Força e Controle 200ml. Ficar com cabelo de galã nunca foi tão fácil! **Cabelos mais fortalecidos e resistentes** Para um estilo de vida ativo.', 38.84, 38.84, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rd4g-lvay4k3pl8kn22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F21397682391', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
