INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45711621428', 'Quebra Cabeça P. 100 Pçs Toy Story 5 8098', 'Quebra Cabeça Turma da Mônica 8097 é a escolha perfeita para os amantes de quebra-cabeças e da icônica turma criada por Maurício de Sousa. Com 100 peças, este quebra-cabeça apresenta Mônica e seus amigos em uma linda ilustração que irá encantar tanto crianças quanto adultos. A atividade de montar quebra-cabeças é uma ótima forma de desenvolver habilidades cognitivas, como concentração e reconhecimento de formas. Além disso, proporciona momentos de diversão em família, sendo ideal para tardes de lazer ou encontros com amigos. Projetado para ser desafiador, mas acessível, são 100 peças que garantem uma experiência envolvente, adequando-se a diferentes faixas etárias. Feito em papel e papel cartão, o produto oferece durabilidade e um toque agradável ao manuseio. A orientação vertical contribui para um visual impactante quando exposto, ideal para decorá-lo após a montagem. É uma excelente opção para aqueles que desejam presentear ou até mesmo para quem busca um hobby relaxante. A marca Novo Papel é reconhecida pela qualidade de seus produtos, garantido a satisfação em cada montagem. Experimente o prazer de montar e colecionar, e descubra o universo divertido da Turma da Mônica de uma maneira única e envolvente.', 30.99, 30.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134207-820lc-mp0riffr2sjl6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F947344701%2F45711621428', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40515159794', 'Brinquedo Arco & Flecha Indian Archery- Tag Toys TGG001', 'ste arco e flecha da TAG TOYS foi desenvolvido para momentos de lazer com foco em coordenação, mira e concentração. É indicado para crianças a partir de 8 anos e se adapta bem à faixa recomendada de 8 a 13 anos, oferecendo uma proposta de brincadeira ativa e envolvente. O formato convida a praticar precisão de maneira simples e dinâmica, tornando a experiência interessante tanto em casa quanto em atividades recreativas. É uma opção que estimula o movimento e o controle dos gestos, sem exigir uma curva de aprendizado complexa. Por se tratar de um brinquedo voltado ao público infantil e pré-adolescente, pode ser aproveitado em ambientes amplos e com acompanhamento responsável. Isso ajuda a transformar o momento de brincar em uma atividade mais segura e organizada. O nome Indian Archery TagToys identifica uma linha pensada para quem procura uma proposta temática dentro do universo de arco e flecha. A marca TAG TOYS agrega confiança ao item e reforça sua vocação para uso recreativo. Para famílias que buscam uma alternativa de lazer com apelo esportivo, este arco e flecha oferece uma experiência estimulante e adequada à idade indicada. É uma escolha interessante para desenvolver atenção, coordenação e diversão em uma mesma atividade. Material: Plástico resistente | Idade recomendada: A partir de 8 anos | Inclui: 1 arco, 3 flechas com pontas de ventosa.', 26.99, 26.99, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mdvqtyfc3hmo3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F947344701%2F40515159794', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22626999672', 'Jogo Interativo Super Trunfo Seleções do Mundo - Grow 4282', 'Super Trunfo Seleções do Mundo traz 32 cartas com imagens e informações de seleções do mundo para uma disputa superdivertida! Você compara sua carta com a do outro jogador. Mas escolha bem a característica que vai utilizar a cada rodada, pois, se sua carta ganhar, você fica com a carta do outro jogador; se perder, ele fica com a sua! No final, vence quem ganha todas as cartas do jogo. Código do Produto: 04282 Especificações Técnicas Faixa Etária : A partir de 7 anos Componentes : contém 32 cartas, 1 caixa plástica e 1 regra Tamanho da Imagem : n/a Dimensões da embalagem : 10,2 x 15,4 x 2 cm Precisa de baterias ou Pilhas : n/a Participantes : 2 a 8 Garantia contra defeitos de fabricação (meses) : 3 Código de Barras : 7908010142822 Certificação Inmetro : CE-BRI/ICEPEX-N 01264-25 - NM300-2004 OCP 0046', 31.99, 31.99, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/br-11134201-23020-s00qst6gixnv25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F947344701%2F22626999672', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
