INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393596336', 'Pá de Lixo Articulada com Cabo Noviça Bettanin', 'Com cabo alongado e articulado, a Noviça Pá Articulada com Cabo possui uma maior profundidade, rosca articulada e pente de vassoura para facilitar a retirada de sujeiras das cerdas sem que seja necessário colocar as mãos nos resíduos, tornando a limpeza segura e rápida.', 42.9, 34.9, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rffm-m9aaaxh44bkye9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F22393596336', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208430801', 'Cera Líquida Carnaúba 500ml Spray Proteção Renova Brilho Pintura Verniz Estética Acabamento Auto', 'A Cera Líquida de Carnaúba 500ml BraClean foi desenvolvida para proporcionar brilho intenso e acabamento uniforme à pintura automotiva. Formulada com carnaúba, ela auxilia na valorização estética do veículo, contribuindo para aparência mais limpa e bem cuidada. De aplicação prática e rápida, a cera líquida automotiva BraClean é indicada para quem busca manutenção frequente da pintura, oferecendo facilidade na aplicação e bom rendimento em cada uso. BENEFÍCIOS • Intensificar o brilho da pintura automotiva. • Contribuir para acabamento mais uniforme e valorizado. • Facilitar aplicação com fórmula líquida prática. • Auxiliar na proteção superficial contra sujeiras leves. • Ajudar a manter aparência renovada do veículo. • Proporcionar manutenção estética periódica com praticidade. INFORMAÇÕES TÉCNICAS Marca: BraClean Produto: Cera Líquida de Carnaúba Volume: 500ml Categoria: Cera automotiva líquida Aplicação: Pintura automotiva limpa e seca Estado físico: Líquido Indicação: Uso automotivo Conteúdo da embalagem: 1 frasco de 500ml COMO USAR Lave e seque o veículo completamente. Agite o frasco antes da aplicação. Aplique pequena quantidade com pano macio ou aplicador. Espalhe uniformemente em movimentos circulares. Após leve secagem, remova com pano seco para revelar o brilho. PERGUNTAS FREQUENTES Pode aplicar sobre pintura nova? Sim, desde que a pintura esteja totalmente curada conforme orientação do fabricante. Substitui polimento? Não. Atua no brilho e proteção superficial. Pode usar com frequência? Sim, indicada para manutenção regular. PROVA DE CONFIANÇA • Produto com carnaúba para acabamento valorizado. • Aplicação prática e rápida. • Embalagem de 500ml com bom rendimento.', 45.8, 27.48, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Wax', 'https://cf.shopee.com.br/file/br-11134275-820lz-mlji1cmy3kef6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F758890475%2F58208430801', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
