INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298564356', 'Colchão Light D33 – Solteiro (78x188x14) - Ortobom', 'Colchão Light D33 Solteiro (78x188x14) O Colchão Ortobom Light D33 foi desenvolvido para quem busca conforto equilibrado, firmeza moderada e excelente durabilidade. Produzido 100% em Espuma D33 Pró Aditivada de Alta Performance, oferece suporte para até 100 kg por pessoa, mantendo a sustentação e o conforto ao longo do uso. Seu tampo com bordado em matelassê, proporciona um toque suave e agradável que reforça a sensação de aconchego. O revestimento resistente conta com tratamento antiácaro e antialérgico, garantindo um ambiente de descanso mais higiênico e saudável. O Colchão Ortobom Light D33 é a escolha ideal para quem valoriza conforto, resistência e qualidade em um só produto.', 535.9, 471.59, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-8260i-mjzy9a5h4jcwa5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1537615778%2F22298564356', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
