INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23092640717', 'Pingente de Prata 925 Cruz Lisa Detalhada', 'Pingente de Prata 925 Cruz Fé Lisa Este pingente de Prata 925 é uma expressão simples, mas poderosa, de fé. Possui um design de cruz lisa que mede 16mm de comprimento por 22mm de altura, proporcionando um toque de espiritualidade e significado. Especificações: Tamanho: 16mm x 22mm Peso: 0.6g Material: Prata 925 Um Símbolo de Fé O Pingente de Prata 925 Cruz Fé Lisa é uma maneira elegante de exibir sua fé e espiritualidade. Seu design simples e atemporal o torna adequado para uso diário ou para ocasiões especiais, sempre lembrando a importância da fé em sua vida. Encontre Mais na Aqua Joias Explore nossa coleção completa de pingentes de Prata 925 para encontrar uma variedade de símbolos e designs que refletem seus valores e crenças. Na Aqua Joias, estamos comprometidos em oferecer joias de alta qualidade que têm significado e estilo.', 64.0, 45.0, NULL, 'Fashion Accessories > Additional Accessories > Charms, Pendants & Ornaments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6cokzwz8vid46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F23092640717', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
