INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693106866', 'Jarro de Vidro Jarra para Suco água 1L ou 500ml Casa Jarra para Cozinha Vidro Com Tampa', 'Desfrute de praticidade e elegância com a Jarra de Vidro com Tampa de Plástico, uma adição indispensável para sua cozinha. Com capacidade de 500ml, esta jarra é perfeita para armazenar uma variedade de líquidos, desde sucos frescos até água gelada ou até mesmo chá gelado. Fabricada com vidro, esta jarra oferece durabilidade e transparência cristalina, permitindo que você aprecie a cor e a textura das bebidas armazenadas. A tampa de plástico garante um fechamento seguro, mantendo o conteúdo fresco por mais tempo e evitando derramamentos indesejados. O design elegante e minimalista desta jarra a torna uma peça versátil, adequada para uso em diversas ocasiões, desde reuniões familiares até eventos ao ar livre. Além disso, sua alça ergonômica facilita o manuseio e o despejo sem derramamentos. Adicione um toque de praticidade e estilo à sua vida cotidiana com a Jarra de Vidro com Tampa de Plástico de 500ml. Seja para uso doméstico ou como presente, esta jarra é a escolha perfeita para quem valoriza funcionalidade e design elegante na hora de servir bebidas.', 29.9, 16.06, NULL, 'Home & Living > Dinnerware > Jugs, Pitchers & Accessories', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lwsmrxp0xznj1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F23693106866', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294444015', 'Fender Conjunto De Arruelas De Alumínio E Parafusos De Pára-Choque Estilo M6 COM 10UNIDADES', 'Apresentamos o Kit de Parafusos e Arruelas Anodizadas M6 x 20mm - Conjunto com 10 Unidades para quem busca personalização e estilo no acabamento de veículos e equipamentos. Por que escolher nosso Kit de Parafusos com Arruelas Anodizadas? Estilo e Personalização: Ideal para Tuning automotivo, este conjunto proporciona um visual esportivo ao motor e outras áreas do veículo, adicionando um toque especial ao acabamento. Durabilidade e Resistência: Parafusos em aço inoxidável, que não enferrujam, e arruelas em alumínio anodizado, que combinam leveza com alta resistência. Versatilidade de Aplicação: Pode ser utilizado em diversos pontos com rosca M6, como no cofre do motor, faróis e placa, de acordo com a necessidade de instalação. Especificações do Produto: - Material das Arruelas: Alumínio anodizado - Material dos Parafusos: Aço inoxidável - Comprimento dos Parafusos: 20mm - Espessura das Arruelas: 4mm - Diâmetro Externo das Arruelas: 18mm - Rosca dos Parafusos: M6 ou 6mm Conteúdo da Embalagem: - 10 arruelas anodizadas - 10 parafusos Allen M6 Informações Adicionais: Este conjunto oferece fácil instalação e acabamento de qualidade, perfeito para quem valoriza detalhes no visual do veículo. Ideal para uso em tuning automotivo e adaptações esportivas.', 59.9, 25.11, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Safety > Wheel Nuts', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg55pne7s16s33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1471063820%2F23294444015', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18657590052', 'Armário de Cozinha Compacta 4 peças MP3696.895 Veneza Multimóveis Preto', 'A Cozinha Compacta 4 peças com Armário e Balcão MP3696 Veneza Multimóveis tem um excelente custo benefício e um amplo espaço interno. Produzida em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade e resistência, possui corrediças metálicas (mais leveza no manuseio), pés retrô em polipropileno, que deixam o ambiente mais estiloso, puxadores em ABS e tampo em MDP 15mm com pintura de alta resistência. Os módulos são individuais e você pode montar da maneira que se adaptar melhor ao seu ambiente. O balcão possui tampo removível (compatível com pia de 120 cm). Para deixar sua cozinha mais bonita e organizada, possui vidro reflecta e compartimento especial para utensílios mais altos. Conteúdo da Embalagem: 1 (um) armário aéreo com portas de vidro 120cm 1 (um) armário aéreo 120cm 2 (dois) balcões com tampo 120cm Dimensões do produto montado: Cozinha - Altura: 203cm | Largura: 240cm | Profundidade: 32cm (aéreos) - 53cm (balcão com tampo) *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 2099.9, 1399.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7qvdi-li03obrp1tw32f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F18657590052', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
