INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '2976276882', 'Kit Palheta Limpador Parabrisa Dianteiro + Traseiro Ford Ka 1997 a 2001 Encaixe Traseiro tipo Click', 'Kit Palheta Limpador de Para-brisa Dianteiro + Traseiro para Ford Ka 1997 a 2001 Mantenha a visibilidade do seu Ford Ka sempre nítida e segura em qualquer condição climática com o Kit de Palhetas Limpadoras de Para-brisa. Projetado para modelos de 1997 a 2001, este conjunto inclui duas palhetas dianteiras e uma palheta traseira, garantindo uma limpeza eficiente e uniforme. 🔹 Compatibilidade: Ford Ka 1997, 1998, 1999, 2000 e 2001 🔹 Material resistente: Borracha de alta durabilidade para um desempenho silencioso e eficiente 🔹 Instalação simples e rápida 🔹 Melhor desempenho na remoção de água e sujeira Substitua suas palhetas desgastadas e evite riscos no vidro, garantindo uma condução mais segura e confortável. 🚗💨', 39.79, 30.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/79191c6db6e017e848f241f9b446c681', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357432948%2F2976276882', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
