INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8916055808', 'Lupa de Mesa com Garras e Iluminação Led Bivolt GT120 Lorben', 'Esta lupa facilitará a observação de detalhes em seu trabalho. Ela possui garras para fixação, iluminação integrada por 5 LED’S e 2 lentes com diferentes ampliações: 34mm e 90mm. Sua alimentação é com 3 pilhas AA (não inclusas) ou via fonte bivolt inclusa que, quando utilizada, desativa o uso das pilhas automaticamente. Ideal para trabalhos que necessitem de uma “terceira mão” Uso indicado para engenheiros eletrônicos, estudantes, cientistas, colecionadores ou qualquer profissional que necessite visualizar detalhes Suas garras móveis fixam os materiais a serem observados Iluminação com ajuste de posição Auxilia a observação em ambientes com pouca ou nenhuma luz Quando utilizada com a fonte economiza a energia das pilhas para trabalhos futuros Suporte e base ajustáveis Superfície da base preenchida com chapa de aço para aumentar o peso e reforçar a estabilidade Marca: Lorben Alimentação: 3 pilhas AA ou via fonte externa bivolt (inclusa) Material: Polipropileno e Vidro Cor: Preto/Prata Inclui: 1 Base do suporte 1 Lente de 90 milímetros de diâmetro (2.5X) 2 Lentes de 34 milímetros de diâmetro (5X, 8X) 1 Manual de usuário 1 Fonte de energia bivolt 110V/220V Tamanho do produto: aproximadamente 20x11x17cm Peso do produto: 515g Tamanho da embalagem: 20x14x11 cm Peso: 640g Código do produto: GT120 Produto inclui e-book digital complementar, entregue eletronicamente após a compra. Imagens ilustrativas. As tonalidades podem variar.', 79.99, 79.99, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/4d91a63a718f41bc5e11732805676d6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F386114683%2F8916055808', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
