INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207455162', 'ATLAS DO MANUAL DO MUNDO', 'O Manual do Mundo — a maior produtora de entretenimento educativo do país, com mais de 1 milhão de livros vendidos — convida você a viajar pela Terra com mais de 60 mapas incríveis. Desbrave os seis continentes e os oceanos com recriações 3D que mostram os mais diversos aspectos de cada região, desde relevo, populações e pontos turísticos até clima, vida selvagem e visões noturnas do espaço. Qual é o lugar mais seco do planeta? Qual é o país mais populoso da Terra? Onde vive a maior borboleta do mundo? Qual é a fronteira internacional mais cruzada do globo? Vulcões, geleiras, cataratas, pirâmides, tornados, desertos, catedrais, cordilheiras... Tudo que você pode imaginar está aqui. Atravesse os picos do Himalaia, as savanas africanas, a fl', 129.9, 129.9, NULL, 'Books & Magazines > Books > History & Cultures', 'https://cf.shopee.com.br/file/sg-11134201-82613-mm6hf6hpmvwi48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F58207455162', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
