INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19335882098', 'Banqueta Portátil Alumínio Para Camping E Pesca Banquinho', '# Auto Equip # Bem vindo! * Produtos de Qualidade * Postagens até 24h * Pagamento facilitado Descrição Banqueta De Alumínio Dobrável Verde Claro e Verde Escuro: A Banqueta Alumínio é super versátil! Cabe em qualquer lugar, é prática, dobrável, leve e fácil de carregar. É perfeita para camping e pescaria e pode ser mantida no porta-malas do seu carro para ser utilizada sempre que precisar. Resistente, suporta até 90 Kg já que é produzida pela Mor em alumínio de excelente qualidade e tela 100% polietileno. O alumínio deixa a Banqueta mais leve e garante maior durabilidade mesmo em áreas litorâneas! Especificações Técnicas: - Marca: Mor - Cor: Verde - Material da estrutura: Alumínio - Material da Tela: Polietileno - Altura: 152mm - Dobrável - Peso máximo suportado: 90kg - Dimensões aproximadas (CxLxA): 28 x 33 x 37cm Conteúdo da embalagem: - 01 Banqueta Dobrável Importante: Garantia de 3 meses. Todos produtos postados em até 24h úteis! A Auto Equip recomenda que a instalação seja feita por profissional especializado e não se responsabiliza pelo mau uso do produto.', 49.9, 49.9, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/3d783b2e1640ea8828f60348d417d83e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402093902%2F19335882098', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20597808711', 'Kit com 8 Cadeiras Masters Allegra Preta', 'Kit com 8 Cadeiras Masters Allegra Preta Conhecida no mundo inteiro pelo seu design único e a forma como foi criada a cadeira Allegra Masters é uma homenagem a três cadeiras símbolo da história do design a cadeira Jacobsen de Arne Jacobsen a cadeira Saarinen de Eero Saarinen e a DSR do casal Eames. Os modelos se entrelaçam em uma combinação de curvas dando vida a uma original e cativante fusão de estilos. Modelo: Cadeira Allegra Masters Material da Estrutura: Polipropileno Garantia de 3 meses por defeito de fabricação. Altura Total: 84 cm Altura do Chão Até o Assento: 48 cm Profundidade Interna do Assento: 48 cm Largura Interna do Assento: 53 cm Peso Máx. Recomendado: 120 kgs Peso unitário: 4,2 kgs Indicações de Uso: - Não utilizar produtos químicos e abrasivos para limpeza; - Limpar com pano umedecido e sabão neutro para melhor conservação; - Deve ser evitada exposição dos produtos ao sol pois podem apresentar pequenas mudanças em sua coloração. Observações importantes: - Produto NÃO necessita de montagem - Pode haver alguma diferença de tonalidade entre a imagem e o produto real, por conta do tratamento de imagens e a calibração de cores do seu monitor. - Ao receber a mercadoria, o cliente deve verificar as condições da embalagem, caso haja alguma avaria não assine o comprovante de recebimento.', 1592.0, 1592.0, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7rdyk-lzqqp1qli0x4ca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F20597808711', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19138638506', 'Mesinha De Apoio Quadrada Branca Para Lazer 51x51 Com proteção Solar Mor', '# Auto Equip #Bem vindo! * Produtos de Qualidade* Postagens até 24h* Pagamento facilitado Descrições técnicas Mesa Platica de Apoio - Mor: Com a mesa Plástica de Apoio Mor tenha sempre ao seu lado o conforto. confeccionada em polipropileno 100% virgem com proteção UV, garantindo maior durabilidade, com um ótimo acabamento, pode ser usada nos seus momentos de diversão como praia, camping, varanda, festas, onde voce preferir, super compacta e fácil de limpar e podendo também empilhar, ocupando menos espaço ao guardar mais unidades. Ganhe comodidade e praticidade com a mesa de apoio plástica Mor. Especificações técnicas: - Material: Polipropileno - Formato: Quadrado - Cor: Branco - Peso:1,10Kg Dimensões aproximadas: - Altura: 43cm - Largura: 51cm - Comprimento: 51cm Conteúdo da embalagem: - 01 mesa de plastico Mor Importante:Garantia de 3 meses.Todos produtos postados em até 24h úteis!A Auto Equip recomenda que a instalação seja feita por profissional especializado e não se responsabiliza pelo mau uso do produto.', 62.9, 62.9, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-7qvfx-li0durnwclim0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402093902%2F19138638506', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
