INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998126522', '4 Latas de Chumbinho Vetor 5.5mm 500 Unidades – Technogun', 'Chumbinho Vetor 5.5mm 125 Unidades - Technogun Pensando em um bom desempenho e alto qualidade em munição, a renomada marca brasileira Technogun desenvolveu os Chumbinhos Vetor, que traz como principal característica a precisão perfeita para tiros de até 20m. Ideal para o lazer e competição com tiro em papel, já que seu design inovador e exclusivo faz com que a munição atinja o alvo como um furador. Outra característica que merece destaque é o grande poder de impacto. Os materiais utilizados na produção dos Chumbinhos Vetor merecem destaques, pois o uso do estanho e chumbo garante dureza maior comparada a outras munições. Os chumbinhos Vetor 5.5mm tem o peso de 0,92 gramas. Os chumbinhos Vetor são formados em alta pressão por um sistema único, que proporciona um balanceamento centrífugo uniforme e preciso, dando ao atirador a melhor experiência em tiros de curta distância. Especificações Fabricante: Technogun Modelo: Vetor Calibre: 5.5mm Peso: 0,92 gramas por chumbinho (14,24Grains) ATENÇÃO: "O uso do produto exige treinamento e equilíbrio emocional." "Deverá ser guardado em lugar seguro e fora do alcance de terceiros."', 171.9, 171.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/6f8cc27dbd0d056d1bf19421e55e240c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F567374315%2F23998126522', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
