INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201627836', 'ESPUMANTE CONSTELACION BRUT ROSÉ 750ML', 'OCÊ ESTÁ COMPRANDO: ESPUMANTE CONSTELACION ROSÉ BRUT 750ML SOBRE O PRODUTO: O Espumante Espanhol Constelación Brut Rosé se destaca pela sua frescura e pelo caráter frutado, representando bem o estilo dos espumantes espanhóis, segue o método tradicional de produção, semelhante ao usado na produção de Champagne, o que garante uma qualidade consistente. Os vinhedos de onde as uvas provem, tem entre 20 e 60 anos de idade, em sistema de condução espaldeira, com utilização de parcelas selecionadas, de videiras novas e velhas, mesclando vindima manual e automática. CARACTERÍSTICAS VISUAIS: Delicado espumante rosé de cor limpa e brilhante com abundância de pequenas bolhas finas e elegantes. CARACTERÍSTICAS OLFATIVAS: No nariz, destacam-se os aromas de frutas vermelhas frescas, como morango, framboesa e cereja. Também pode haver toques florais suaves, que trazem uma certa elegância, e notas ligeiramente cítricas, que contribuem para a frescura. CARACTERÍSTICAS GUSTATIVAS:No paladar, é um espumante leve e refrescante, com uma acidez bem equilibrada que realça os sabores frutados. As notas de morango e framboesa predominam, mas há também uma ligeira presença de citrinos, como limão ou toranja, que conferem uma sensação crocante. O final é seco devido ao estilo Brut, mas com uma suavidade agradável e um toque mineral. SERVIÇO: Servir entre 10–12 °C HARMONIZAÇÃO: Harmoniza bem com frutos do mar leves, saladas com frutas frescas e queijos suaves, carnes brancas grelhadas e sobremesas pouco doces como tartes de frutas vermelhas.', 61.06, 61.06, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-822xf-mi09x4nf64n599', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844012318%2F58201627836', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203596075', 'Shorts Saia Feminino Plus Size Secret Glam Bege', 'Shorts Saia Feminino Plus Size Secret Glam, confeccionado em viscose Khyara acetinada com estampa rotativa exuberante. Possui revel entretelado com pesponto interno e acabamento limpo, recorte duplo fixo com pesponto, franzido e prolongamento frontal formando nó com pontas chanfradas. Abertura frontal com transpasse, bainha na barra para caimento impecável e costas com cós de elástico rebatido. Peça sofisticada, perfeita para looks elegantes e tropicais em ocasiões ao ar livre.', 214.99, 214.99, NULL, 'Women Clothes > Shorts > Shorts', 'https://cf.shopee.com.br/file/sg-11134201-8259u-mr0jxd6fhts0a2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F58203596075', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598464324', 'ARROZ PARA RISOTTO SCOTTI 1KG', 'VOCÊ ESTÁ COMPRANDO: Arroz para Risoto Scotti 1kg – Arroz de grão longo tipo Ribe, ideal para o preparo de risotos e pratos que exigem cremosidade e absorção uniforme de sabores. ORIGEM: Itália SOBRE O PRODUTOR: A Riso Scotti é uma empresa italiana com mais de 160 anos de tradição na produção de arrozes especiais. Reconhecida internacionalmente, a marca combina métodos artesanais com tecnologia moderna para oferecer produtos de alta qualidade. SOBRE O PRODUTO: Peso líquido: 1kg Tipo de arroz: Ribe Ingredientes: Arroz de grão longo Ribe Alergênicos: Não contém glúten Embalagem: Pacote plástico selado Conservação: Armazenar em local fresco e seco.', 52.83, 52.83, NULL, 'Food & Beverages > Food Staples > Rice', 'https://cf.shopee.com.br/file/sg-11134201-7rfh4-m9hcys14szoi68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844012318%2F23598464324', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
