INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53801126056', 'Microfone Gamer RGB Cardioide RGB com Controle de Volume Tipo C P2 MC847', 'O Microfone Condensador oferece captação de alta qualidade para gravações profissionais, streaming, podcasts e chamadas. Seu design moderno combina materiais de ABS e metal, proporcionando durabilidade e excelente desempenho acústico. Conta com diafragma de 14mm e padrão polar cardioide, garantindo captação direcional que reduz ruídos indesejados e foca na voz com clareza e nitidez. Possui controles integrados para ajuste de volume, som de fundo, botão de mudo e cancelamento de ruído, além de iluminação RGB que adiciona estilo e personalidade ao ambiente. Com interface Tipo C + 3,5mm, é compatível com diversos dispositivos, oferecendo praticidade e conectividade rápida. ESPECIFICAÇÕES: - Tipo: Microfone Condensador - Dimensão do diafragma: 14mm - Padrão polar: Cardioide (captação direcional) - Frequência: 80Hz - 16kHz - Gravação: 48/96/192kHz - Reprodução: 48kHz - Interface: Tipo C + 3,5mm - Controle: Knobs multifuncionais (volume microfone/fone/som de fundo) + botão de mudo + cancelamento de ruído + controle de LED - Ajuste de volume: Sim - Iluminação: RGB - Material: ABS + metal - Peso: 325g - Dimensões: 189 x 85mm (+- 2mm) CONTEÚDO: - 1x Microfone - 1x Suporte para base - 1x Cabo Tipo C - 1x Manual de instruções', 203.5, 154.33, NULL, 'Audio > Microphones', 'https://cf.shopee.com.br/file/sg-11134201-821er-mgw8usxh43kced', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F53801126056', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253860039', 'BOINA DE ESPUMA LUSTRO E SUPER LUSTRO 3 POL - ESPUMA PRETA', 'Boina de Espuma Lustro/Super Lustro DBUFF Dub Boyz feita de espuma oferece uma ótima eficiência na etapa de polimento de acabamento no polimento. Conta com um tingimento exclusivo, o que permite uma melhor visualização do produto na boina auxiliando na hora da limpeza. Conta com reforço em toda sua borda em costura com fio especial.', 48.0, 48.0, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Polisher', 'https://cf.shopee.com.br/file/sg-11134201-8262o-mjsu23zg2kg5bc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552415726%2F58253860039', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
