INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250770256', 'Hidratante Corporal Homme Bloom 200g Body Cream Masculino Sofisticado', 'HIDRATANTE CORPORAL HOMME BLOOM 200G BODY CREAM MASCULINO SOFISTICADO O Body Cream Homme Bloom foi desenvolvido para homens que buscam hidratação intensa com uma fragrância marcante e moderna. Sua textura cremosa e de rápida absorção nutre profundamente a pele, deixando-a macia, protegida e com toque confortável, sem sensação oleosa. A fragrância se abre com a energia da bergamota e o toque picante da pimenta. No coração, notas aromáticas como lavanda, vetiver e patchouli criam uma assinatura elegante e envolvente. No fundo, acordes amadeirados de cedro, ambroxan e ládano garantem profundidade e um rastro sofisticado. Ideal para o uso diário, proporcionando frescor, cuidado e presença. DESTAQUES DO PRODUTO: • Hidratação profunda e duradoura • Fragrância masculina elegante e moderna • Toque macio sem oleosidade • Perfume prolongado na pele • Textura leve e rápida absorção • Ideal para uso diário Ativos Principais • Manteiga de Karité – nutrição profunda • Ureia – hidratação intensiva • Pantenol – regeneração da pele • Glicerina – retenção de umidade • Vitamina E – ação antioxidante MODO DE USO: -Aplique sobre a pele limpa e seca, espalhando com movimentos suaves até total absorção. -Ideal para uso diário, especialmente após o banho. INFORMAÇÕES TÉCNICAS: • Marca: Bloom • Tipo: Body Cream / Hidratante Corporal • Peso: 200g • Público: Masculino Composição / Base Manteiga de Karité, Ureia, Glicerina, Pantenol, Vitamina E, fragrância Homme', 70.9, 49.9, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/br-11134207-820ln-mo41f9os9fr4a5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609741857%2F58250770256', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43232271176', 'Sachê para Gatos Ração Úmida para Gatos Kit 15 Sachê Ração Úmida Friskies Gatos Mar de Sabores 80g', 'A Caixa com 15 Unidades de Sachê Friskies Gatos Mar de Sabores 80g foi desenvolvida para proporcionar refeições saborosas e nutritivas para gatos adultos. Com pedaços ao molho e sabores inspirados em frutos do mar, oferece uma alimentação mais atrativa e ajuda a variar a rotina alimentar do seu pet. Os sachês possuem textura macia e são práticos de servir, podendo ser oferecidos como complemento da alimentação seca ou como refeição úmida. Sua fórmula conta com nutrientes essenciais para auxiliar na alimentação diária dos felinos. Contém: • Caixa com 15 Sachês Friskies Mar de Sabores para Gatos 80g cada Benefícios: • Alimento úmido para gatos adultos • Sabores inspirados em frutos do mar • Pedaços ao molho com textura macia • Auxilia na hidratação diária • Fonte de vitaminas e minerais • Sachês práticos e fáceis de servir Perguntas Frequentes: Esse alimento é indicado para quais gatos? É indicado para gatos adultos. O produto pode ser servido junto com ração seca? Sim, os sachês podem ser oferecidos como complemento da alimentação seca. Quantos sachês acompanham a caixa? A caixa contém 15 sachês de 80g cada.', 59.71, 54.5, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/sg-11134201-8258v-mq7xva1qq68018', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1194006916%2F43232271176', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
