INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49059051170', 'Livro - W.I.T.C.H.: O Poder dos Elementos (Vol. 2) - Editora Universo dos Livros ISBN 9788550305486', 'W.I.T.C.H.: O Poder dos Elementos (Vol. 2) As bruxinhas estão de volta, em uma HQ cheia de ação, aventura e fantasia.Em W.I.T.C.H.: O Poder dos Elementos, Will, Irma, Taranee, Cornelia e Hay Lin vivem suas vidas cotidianas em um novo mundo, buscando constantemente um equilíbrio entre a realidade e os poderes ligados aos elementos da natureza. Enquanto um inimigo misterioso conspira nas sombras, uma nova personagem entra em cena. As aventuras das bruxinhas continuam nesta leitura que retoma a história de onde tudo começou! Sobre o autorAlessandro Ferrari é autor de diversas aventuras de vários personagens da Disney, incluindo Piratas do Caribe e High School Musical. Ele já adaptou Alice no País das Maravilhas para graphic novel, além dos filmes da Pixar Wall-E, Up - Altas aventuras e Toy Story 1, 2 e 3.Sobre a ilustradoraGiulia Adragna é artista e designer baseada em Palermo. Atuou em projetos para editoras como Panini Comics, Jungle Ed., Giunti, Fabbri, Rageot, BOOM! Studios, Sergio Bonelli Ed. e Tunué, assinando capas, ilustrações e cores digitais para títulos como Miraculous e W.I.T.C.H. Sobre Disney Consumer ProductsDisney Consumer Products, Games and Publishing (CPGP) traz a magia das marcas e franquias da The Walt Disney Company - incluindo Disney, Pixar, Marvel, Star Wars, National Geographic e mais - no cotidiano de famílias e fãs de todo o mundo por meio de produtos e experiências em mais de 100 categorias de varejo, de brinquedos e camisetas a aplicativos, livros, videogames e muito mais. Uma divisão do segmento de Parques, Experiências e Produtos da Disney, as operações globais da CPGP incluem: o maior negócio de licenciamento do mundo, uma das maiores marcas de publicações infantis, um dos principais licenciadores de jogos interativos entre plataformas e lojas parceiras em diversos países. Autor(es): Alessandro Ferrari, Giulia Adragna ISBN: 9788550305486, 978-85-503-0548-6 Check-List: Junho/2026 Editora: Universo dos Livros Faixa Etária: Crianças e Pré-Adolescentes Lombada/Encadernação: Quadrada Tipo de capa: Cartão Data de Lançamento: 05/06/2026 Idioma: Português Condição: Novo/Lacrado', 63.9, 63.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-81zv6-mn6en0keufie9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F49059051170', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209469061', 'Limpador Multiuso Veja Power Fusion Limão', 'Veja Power Fusion é a eficiência de Veja Multiuso, com a poderosa mistura de extrato de limão, bicarbonato e álcool. Máximo poder de limpeza nas sujeiras mais difíceis, restaura o brilho e seca rápido. O melhor multiuso de todos os tempos. Aplique o produto nas superfícies a serem limpas e, em seguida, passe um pano ou esponja macia. Para as sujeiras mais difíceis, deixar o produto agir por alguns instantes. Para superfícies verticais, recomenda-se aplicar o produto diretamente no pano. Atenção: para painéis de fogões: limpar com a superfície fria. Não usar em superfícies de madeira natural. Para superfícies de alumínio, mármore e superfícies pintadas/esmaltadas e com serigrafia, limpar imediatamente após a aplicação. Recomendação: Testar em uma pequena área escondida antes de usar.', 12.79, 12.79, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8259f-mqnel007hdzfca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555024%2F58209469061', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698053943', 'Mangá - Kusuriya No Hitorigoto - Diários De Uma Apotecária 09 - Novo/Lacrado', 'Kusuriya No Hitorigoto - Diários De Uma Apotecária 09 Na caravana que veio ao Palácio Interno depois de muito tempo, Maomao se diverte fazendo compras com Xiaolan. Lá, ela se reencontra com a serva imperial que capturou o filhote de gato.E então, outra vez ela acaba sendo consultada por Renshi sobre um novo caso, e ele se vai se conectando a um incidente diferente.Novos incidentes e novos mistérios são levados até a Maomao neste nono volume!! Tipo de Produto: Revista Segmentos: Mangás Marcas: Planet Manga Autor(es): Akimi Yoshida, Itsuki Nanao, Natsu Hyuuga, Nekokurage ISBN: 9786525929842 Check-List: Novembro/2024 Classificação Etária: 14 anos, 16 anos Gênero: Ação, Aventura, Comédia, Drama, Fantasia, Mistério, Romance Demografia: Josei Editora: Editora Panini Número de páginas: 180 Tipo de capa: Capa Cartão Data de Lançamento: 21/11/2024 Idioma: Português Condição: Novo/Lacrado', 49.0, 49.0, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rfia-m32kavkui5fb4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F23698053943', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298393848', 'Marvel - Os Fabulosos X-Men: Edição Definitiva Vol. 10 - Novo/Lacrado', 'Os Fabulosos X-Men: Edição Definitiva Vol. 10Para salvar o Anjo, que desapareceu, os X-Men acabam nos esgotos e são capturados pelos Morlocks, um bando de mutantes que vivem no subterrâneo. Ororo terá duelar com sua líder, Callisto, para salvar a si e seus companheiros, e isso desperta nela atitudes mais radicais e violentas. Na Mansão X, a vilã Vampira pede ajuda a Charles Xavier e torna-se uma membro temporária da equipe, mas acaba enfrentando a fúria de Carol Danvers, agora a poderosa Binária! Enquanto isso, no Japão, Wolverine decide não esconder mais seus sentimentos e quer se casar com Mariko Yashida, mas tem de enfrentar a seita de assassinos mais perigosos do planeta: Tentáculo! Os X-Men viajam até a terra do Sol Nascente para participar da cerimônia de casamento entre Logan e Mariko, mas uma surpresa inesperada poderá arruinar a felicidade do casal. E ainda há uma divertida história na qual os X-men enfrentam o amalucado Homem-Impossível! Muitos vilões, aventuras de tirar o fôlego e reviravoltas surpreendentes marcam este volume da coleção, que apresenta alguns dos momentos mais importantes da equipe de mutantes mais adorada dos leitores!Tipo de Produto: Edições Definitivas, Livros Segmentos: Comics Marcas: Marvel Autor(es): Brent Anderson, Chris Claremont , Frank Miller, John Romita Jr., Paul Smith ISBN: 9786525932521, 978-65-259-3252-1 Check-List: Abril/2025, Outubro/2024 Classificação Etária: 12 anos Editora: Panini Personagem: X-Men Número de páginas: 464 Tipo de capa: Capa dura Data de Lançamento: 21/09/2024 Idioma: Português Condição: Novo/Lacrado', 245.9, 245.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rene-m8km2puavkbtcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F23298393848', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
