INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21598098683', 'Conjunto Feminino Curto Listrado Marialícia', 'O Conjunto Feminino Curto Listrado Marialícia é a cara do verão! Composto por blusa e shorts em malha dublada listrada, o look oferece um visual completo cheio de estilo e conforto. A blusa com mangas curtas possui modelagem ajustada ao corpo, valorizando a silhueta e trazendo um visual delicado junto às listras presentes em toda a peça. O shorts conta com uma modelagem que se adapta ao corpo, cintura alta e elástico no cós, que garantem conforto para cada movimento. Para deixar o visual mais moderno, as listras na blusa e shorts são em direções contrárias. Perfeito para um passeio, combine o look com tênis ou sandálias e esteja pronta para arrasar! Modelo veste P Medidas da modelo: 89cm de busto; 97cm de quadril; e 69cm de cintura', 199.9, 199.9, NULL, 'Women Clothes > Sets > Individual Sets', 'https://cf.shopee.com.br/file/sg-11134201-8259z-mr1t48jbbta8a3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F21598098683', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
