INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294188909', 'Kit Abacate Nutritivo Óleo 45ml Dabelle Hair - 5 Produtos', 'O Kit Abacate Nutritivo DaBelle com Óleo 45ml oferece nutrição profunda e combate ao ressecamento, ideal para cabelos secos e opacos. Com 5 produtos enriquecidos com Óleo de Abacate, o kit garante maciez, brilho e controle do frizz para fios mais saudáveis e sedosos. O que o Kit Completo Contém (5 Produtos) · 1 Shampoo Abacate Nutritivo 250ml · 1 Condicionador Abacate Nutritivo 200ml · 1 Máscara Abacate Nutritivo 400g · 1 Óleo em Creme Multifuncional 190ml · 1 Óleo Nutritivo Abacate 45ml Detalhes e Benefícios de Cada Item Shampoo e Condicionador Limpeza nutritiva e condicionamento que sela as cutículas, deixando os fios macios e brilhantes. Máscara Abacate Nutritivo Tratamento intenso que repõe lipídios e hidrata profundamente. Creme para Pentear Facilita o desembaraço e controla o frizz. Óleo Nutritivo 45ml Finalizador que sela as pontas, doa brilho e protege contra o ressecamento. Benefícios Adicionais · Nutrição Profunda: Poder do Óleo de Abacate para fios revitalizados. · Maciez e Brilho: Cabelos sedosos, hidratados e com frizz sob controle. · Tratamento Completo: Rotina com 5 produtos para cuidado intensivo. Modo de Uso Lave com shampoo, aplique condicionador e enxágue. Use a máscara para tratamento profundo. Finalize com creme para pentear e óleo nutritivo no comprimento e pontas.', 130.9, 124.99, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk45jcws8zybe1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939411398%2F22294188909', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15281634126', 'Pilha Auditiva 10 Rayovac Bateria Pr70 6 unidades', 'Um grande avanço para o mundo das pilhas auditivas. O novo design aliado a uma formulação melhorada são a combinação perfeita para uma pilha auditiva de maior duração, confiança e potência para qualquer situação. A nova pilha tem selo de proteção avançado que proporciona estabilidade e mantém a energia em condições extremas.', 37.5, 30.9, NULL, 'Home Appliances > Batteries', 'https://cf.shopee.com.br/file/c330cb53dbef39d1c77a47d1ed1846c2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F751077961%2F15281634126', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
