INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899846002', 'Kit Meu Cacho Perfeito Cereja Gota Dourada - Shampoo, Condicionador e Creme de Pentear', 'SHAMPOO E CONDICIONADOR MEU CACHO PERFEITO CEREJA GOTA DOURADA: Cachos Definidos e Radiantes Se você busca cachos mais saudáveis, definidos e com um perfume irresistível, o Shampoo e Condicionador Meu Cacho Perfeito Cereja Gota Dourada é a escolha ideal. Essa dupla foi desenvolvida com ativos reconstrutores e extrato de cereja para atuar profundamente na fibra capilar, garantindo cachos fortes, hidratados e cheios de vida. O kit completo oferece um tratamento contínuo que começa na lavagem e termina com a selagem das cutículas, o que resulta em fios mais resistentes e cachos perfeitamente modelados. Benefícios do Kit Meu Cacho Perfeito Cereja Redução da quebra e fortalecimento: A fórmula reconstrói a fibra capilar, tornando os fios mais resistentes. Hidratação profunda: Proporciona hidratação intensa sem deixar o cabelo pesado. Definição duradoura: Ajuda a manter a forma natural dos cachos por mais tempo. Aroma de cereja: Deixa um perfume marcante e delicioso nos cabelos. Com o uso diário, seus cachos ficarão mais bonitos, macios e com a definição que você sempre quis. Este Kit Contém: 01 Shampoo Meu Cacho Perfeito Cereja Gota Dourada 300ml; 01 Condicionador Meu Cacho Perfeito Cereja Gota Dourada 300ml; 01 Creme de Pentear Meu Cacho Perfeito Cereja Gota Dourada 1 KG;', 59.0, 49.0, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md3vbsgcyqkh84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1382606196%2F21899846002', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698820555', 'Kit Shampoo e Condicionador Desamarelador 430 ml + Creme Desamarelador 320 ml Gota Dourada', 'Descrição mais detalhada (para site/blog): Kit Gota Dourada: O Cuidado Essencial para Loiras e Grisalhas Manter o tom ideal dos cabelos loiros, descoloridos e grisalhos pode ser um desafio, mas o Kit Shampoo e Condicionador Desamarelador + Creme Desamarelador Gota Dourada é a solução perfeita. Desenvolvido para neutralizar os tons amarelados, este kit proporciona um loiro platinado e vibrante, além de nutrir profundamente os fios. Shampoo e Condicionador Desamarelador A dupla de Shampoo e Condicionador Desamarelador é o primeiro passo para um loiro impecável. Sua fórmula com pigmentos especiais age neutralizando gradualmente o amarelado e alaranjado, enquanto limpa e condiciona suavemente, sem ressecar. O resultado é um cabelo com a cor revitalizada, macio e com um brilho incrível. Creme Desamarelador O Creme Desamarelador complementa o tratamento. Ele hidrata intensamente a fibra capilar, que muitas vezes fica fragilizada após a descoloração. Além de nutrir e proteger, o creme intensifica a ação desamareladora, deixando o cabelo com um toque sedoso e a cor ainda mais uniforme e radiante. Este kit contém: 01 Shampoo Desamarelador (430 ml): Neutraliza tons amarelados e limpa suavemente. 01 Condicionador Desamarelador (430 ml): Restaura a maciez e o brilho. 01 Creme Desamarelador (320 ml): Hidrata e intensifica a ação desamareladora.', 69.0, 49.0, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdjkj6oymnyp0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1382606196%2F23698820555', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
