INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24697993434', 'GUIDÃO PRETO FORTUNA PARA HONDA XRE300 COM PESO E ROSCA', 'Guidão da marca Fortuna, compatível com Honda XRE 300. Modelo com peso e rosca, desenvolvido para oferecer maior estabilidade, conforto e controle durante a pilotagem. Possui acabamento na cor preta, garantindo resistência e visual discreto. Ideal para reposição, com encaixe adequado e instalação simples. Especificações: Marca: Fortuna Aplicação: Honda XRE 300 Cor: Preto Modelo: Com peso e rosca Tipo: Guidão Instalação simples Produto ideal para quem busca segurança, conforto e durabilidade para a motocicleta.', 74.0, 74.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-82602-ml8a83u4h0ch5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297313782%2F24697993434', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
