INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792980120', 'Correia Poly V Ar Condicionado RANGER 2.8 2001 a 2005 - 16411 - 4PK1038', 'Correia Poly V Ar Condicionado RANGER 2.8 2001 a 2005 Produto novo, com garantia e Nota Fiscal!_x000D_ _x000D_ Correia Poly V - 4PK1038_x000D_ _x000D_ Aplicação: RANGER - 2.8 TURBO DIESEL _x000D_ Anos: 2001 2002 2003 2004 2005_x000D_ Utilização: Ar Condicionado As correias Multi V permitem a transmissão não positiva de binários. A sua função: O acionamento do alternador, ventoinha, bomba de água, compressor do ar condicionado e direção assistida nos motores modernos. As correias Multi V estão sujeitas a envelhecimento e desgaste. Por essa razão, têm de ser controladas e substituídas a intervalos regulares. Os intervalos de controle e de substituição são sempre estabelecidos pelo fabricante do veículo e devem ser respeitados.', 57.01, 57.01, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd6m-lujhvz5ialml91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22792980120', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098212114', 'Maçarico Portátil Hulter Flexível HT59001F', 'O Maçarico Portatil Hulter Flexivel que não necessita de eletricidade para funcionar. Portátil, leve e perfeito! Você pode confiar no Maçarico Portatil Hulter Flexivel para todos os seus trabalhos. Fácil de usar, indispensável, leve e portatil, para que você possa levá-lo para qualquer lugar. Esta maçarico tem o poder e a precisão para fazer projetos acontecerem com apenas um aperto fácil. Maçarico portátil de alta performance para sua brasagem. Ignição automática. Tubo queimador em aço inoxidável. Projetado para uso com Gás Propano e MAPP. Construção robusta em metal e aço inoxidável. Peso leve.', 299.9, 299.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbn5-m644gc8iqf7k82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F23098212114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294233374', 'Compressor Ar Celta Corsa Classic 2002 2003 2004 2005 2006 2007 2008 6pk Original Mahle', 'Para que serve um compressor? Essa peça que compõe tem duas funções simples: aquecer e resfriar o ar. Só que o processo é um pouco mais complexo do que isso. O compressor, na prática, comprime o gás refrigerador, mandando-o para o condensador do seu veículo. A empresa NÃO se responsabiliza por problemas de instalação. Garantia de 90 dias. - Voltagem: 12v - Polia 6pk - 110mm (11cm) - Fixação Passante - Compressor Procedência Original - Qtde oleo: 150ml - Tipo Oleo: PAG - Rotação sentido HORARIO Compressor Do Ar Condicionado Celta Corsa Prisma Flex / Gasolina Original Mahle Polia 6pk ***Comparar fotos / códigos para ver se é o mesmo compressor para o seu veículo*** GM - CHEVROLET CELTA 1.0 8V FLEX2005 a 2008 GM - CHEVROLET CELTA 1.0 8V GASOLINA2002 a 2008 GM - CHEVROLET CELTA 1.4 8V GASOLINA2003 a 2008 GM - CHEVROLET CORSA 1.0 8V ALCOOL2002 a 2007 GM - CHEVROLET CORSA 1.0 8V FLEX2005 a 2009 GM - CHEVROLET CORSA 1.0 8V GASOLINA2004 a 2009 GM - CHEVROLET PRISMA 1.4 8V FLEX2006 a 2009 Marca: Original Mahle Código: ACP204 ; CS10060 ; 93310443 / 93354502 / 93381741 / 93399315 Código Conversão: CS10060 Código Original: 93310443 / 93354502 / 93381741 / 93399315 - Compressor do ar condicionado - Nota fiscal do produto As imagens são meramente ilustrativas. As informações divulgadas nesta página são de responsabilidade do fabricante. Este produto deve ser instalado por um profissional especializado, para evitar danos ao veículo ou perda da garantia. *COMPARAR FOTOS E CÓDIGOS*', 1628.96, 1628.96, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Air Conditioning', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc6ckw4w1vid4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F587157147%2F22294233374', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
