INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497029732', 'Válvula Solenóide Citroen C3 2003 a 2015 - 180092 - 2007', 'Válvula Solenóide Citroen C3 2003 a 2015 180092 2007 Motor 1.4 8v /1.6 16v Gasolina/Flex - (2 Vias) Problemas mais comuns no sistema de partida a frio Estão relacionados ao combustível ruim. A utilização de um combustível de baixa qualidade faz com que as vias de passagem da solenoide venham a entupir e não permitir a passagem do combustível. Outro problema no sistema pode ser a falta do uso. O combustível resseca os locais de passagem, fazendo com que a falta de lubrificação venha a tornar o material mais frágil, pois algumas partes do sistema são feitas de plástico.', 77.2, 77.2, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rbk3-lmt6dyxlr3h505', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22497029732', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
