INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200261765', 'Ventilador Rosa Britânia Maxx Force 60W BVT304 220V', 'Ventilador Rosa Britânia Maxx Force 60W BVT304 220VO Ventilador Rosa Britânia Maxx Force 60W BVT304 é perfeito para quem busca frescor e praticidade no dia a dia. Com tecnologia Maxx Force e hélice de 6 pás com 30cm, ele proporciona altíssimo desempenho e poder de ventilação, garantindo um ambiente mais agradável e confortável. O Ventilador conta com 3 velocidades, suave, moderada e intensa, que se adequam às suas necessidades. Além disso, a grade removível de 35cm facilita a limpeza, tornando o produto mais prático e higiênico. Para maior flexibilidade, o Ventilador Britânia possui 3 opções de oscilação vertical e oscilação horizontal automática. Assim, você pode direcionar o fluxo de ar para onde quiser, garantindo conforto para todos os ambientes. Com potência de 60W, o Ventilador Britânia Rosa BVT304 é eficiente e econômico. Além de tudo, ele é bonito e moderno, combinando com qualquer decoração. - 3 velocidades - Hélice de 6 pás de 30cm - Potência de 60W - Grade que obedece às normas de ( com partes móveis) - Oscilação horizontal automática com sistema de acionamento (botão integrado à carcaça) - Sistema de articulação para ajuste da inclinação vertical - Porta-fio - sistema de travamento entre grade frontal e traseira - Motor com fusível térmico de - Alça na grade traseira para transportar o aparelho. Especificações Técnicas: Marca: Britânia Cor da Estrutura: Rosa Modelo: BVT304 Estado: Cor das Pás: Cinza Quantidade de pás: 6 Potência (W): 60 W Tipo: De mesa Diâmetro (cm): 30 Função repelente: Não Material das Pás: Plástico Altura do produto: 54,6 cm Largura do produto: 35 cm Comprimento do produto: 29,5 cm Peso do produto: 1,512 kg Altura com embalagem: 46 cm Largura com embalagem: 43,5 cm Comprimento com embalagem: 14,5 cm Peso com embalagem: 1,838 kg Garantia (Dias): 360 Observação: Somente faturamos para o nosso consumidor final, ou seja, não faturamos pedidos para CNPJ por este portal de vendas;', 144.9, 144.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-8258c-mgdqseajqd59d5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1617519379%2F58200261765', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
