INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099609996', 'Kit 2 Roupa Íntima Plenitud Femme Moderada Intensa Tamanho P/M 16 Unidades', 'Roupa Intima Plenitude Femme Calcinha Descartável Moderada / Intensa Tamanho P/M Leve Mais Por Menos A Roupa Íntima Plenitud® Femme foi criada para acompanhar a rotina ativa das mulheres. Agora com nova embalagem e produto ainda melhor, este produto oferece discrição semelhante à de uma calcinha, com tecnologia avançada que garante absorção em segundos e até zero odor. Além disso, é ideal para o período pós-parto. Com rápida absorção e cintura macia que não aperta, Plenitud Femme é um aliado para as mamães a se sentirem confortáveis e protegidas. Diferente de uma fralda geriátrica, a linha de Roupa Íntima Plenitud® é fácil de vestir e tirar, além de ser mais discreta. Sinta-se segura e confortável o dia todo com a Roupa Íntima Plenitud® Femme, o aliado perfeito da mulher!', 119.98, 119.98, NULL, 'Health > Personal Care > Adult Diapers & Incontinence', 'https://cf.shopee.com.br/file/sg-11134201-8259e-mq7wv719vnya20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F20099609996', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794389547', 'Kit 2 Sabonete Líquido Protex Cuidado Íntimo Delicate Care 200ml', 'Protex Cuidado Íntimo Delicate Care Ajuda a manter a defesa natural da região íntima. O líquido está em um frasco ou recipiente duplamente lacrado?: NÃO Protex Cuidado Íntimo Delicate Care é um produto desenvolvido especialmente para cuidar da saúde da mulher. Contém exclusivo Protex System com ácido láctico, que fortalece a barreira natural da área íntima para manter o pH equilibrado. Contém uma fragrância suave. Benefícios para você: Ajuda a manter a defesa natural da região íntima. Proporciona frescor todos os dias. Ginecologicamente testado. Desenvolvido especialmente para cuidar da saúde da mulher. Contém exclusivo Protex System com ácido láctico. Fortalece a barreira natural da área íntima para manter o pH equilibrado. Rende até 50 usos. Exclusivo Protex System com ácido láctico, que fortalece a barreira natural da área íntima para manter o pH equilibrado. Benefícios: Ajuda a manter a defesa natural da região íntima. Proporciona frescor todos os dias. Ginecologicamente testado. Desenvolvido especialmente para cuidar da saúde da mulher. Contém exclusivo Protex System com ácido láctico. Fortalece a barreira natural da área íntima para manter o pH equilibrado. Rende até 50 usos. Ingredientes: Aqua, Sodium Laureth Sulfate, Cocamidopropyl Betaine, Parfum, Styrene/Acrylates Copolymer, Cocamide MEA, Sodium Salicylate, Sodium Benzoate, Glycol Distearate / Sodium Laureth Sulfate / Cocamide MEA / Laureth-10, Lactic Acid, Citric Acid, Sodium Chloride, Tetrasodium EDTA, Polyquaternium-7, Chamomilla Recutita (Matricaria) Flower Extract / Camellia Sinensis Leaf Extract, Hexyl Cinnamal, Linalool, Benzyl Salicylate, Citronellol, Coumarin, Butylphenyl Methylpropional, Geraniol, Alpha-Isomethyl Ionone, Limonene. Modo de Uso: Aplicar uma pequena quantidade na mão. Aplicar na região genital externa até obter espuma. Em seguida, enxaguar abundantemente. Precauções: Manter fora do alcance de crianças. Havendo irritação ou sensibilidade, suspenda o uso e consulte um dermatologista.', 62.98, 62.98, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-823oi-mojrbr23u3gh25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23794389547', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
