INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48300646656', 'Antena Universal Ka Fiesta Focus Ecosport Haste 52 Cm Longa', 'Antena Haste De Teto Carro Ford Ka Fiesta Focus Ecosport Rosca 6mm 52 cm Apresentamos a você a Antena Automotiva para os modelos Ford KA, Ford Ecosport, Ford Fiesta e Ford Focus 6mm Por favor, verifique antes da compra se a rosca da sua antena é de 5mm ou 6mm. Se for 5mm não servirá no seu carro. ROSCA DE 6MM Nossa antena de 52cm é uma opção de qualidade para quem deseja melhorar o sinal de rádio do seu veículo. Com design moderno e discreto, a antena é facilmente instalada no lugar da antena original, sem necessidade de adaptações ou ferramentas especiais. Além disso, a antena é resistente e durável, proporcionando um sinal de rádio mais estável e uma qualidade de som superior. Compatível com os modelos de carros da Ford mencionados, ela é a escolha perfeita para quem deseja uma alternativa confiável para a antena original do carro. Adquira já a sua antena automotiva para Ford KA, Ford Ecosport, Ford Fiesta e Ford Focus e aproveite a melhor qualidade de som e sinal de rádio para seu veículo! Garantia do vendedor: 30 dias', 22.99, 22.99, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgi0tyxx3uvb01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F625420381%2F48300646656', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
