INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55811131881', '(New Arrival) Lovito Padrão de Vestido Casual para Lazer Vestido de Primavera/verão para mulheres L195AD303', '✅DESTAQUES -❤️Padrão -❤️Lazer -❤️Sensação de mão suave -❤️Primavera e verão -❤️Fim de semana casual ✅DESCRIÇÕES Estampa / Padrão:Geometric Estilo:Casual Tipo de vestido:Flared Tamanho Plus:No Material:Poliéster Composição:95%Polyester+5%Spandex Tipo de modelagem:Slim Fit Transparência:No Esticar:Non-stretch Feito na China ✅O PACOTE INCLUI 1XVestir ✅INTRODUÇÃO LOVITO A Lovito é uma marca em crescimento que acredita no poder das meninas. Estamos comprometidos em oferecer opções de roupas fashion e acessíveis, para todos os estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, liberadora e fazer você se sentir incrível. Afinal, o melhor acessório para qualquer look é a autoconfiança! ✅NOTAS DE COMPRA Antes de comprar, dê uma olhadinha na tabela de medidas disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, converse conosco e responderemos o mais rápido possível.', 107.0, 74.5, NULL, 'Women Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-823pg-mpc8dt9zzdvy11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F426378412%2F55811131881', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093927151', 'Melatonina Catarinense 20ml 0,21mg/gt', '**Produto Original** Melatonina em gotas sem sabor com 20ml. Recomenda-se ingerir 1 gota antes de dormir. Gotejar com o frasco na vertical e bater levemente no fundo para iniciar o gotejamento. Este produto é indicado para indivíduos com 19 anos ou mais. Este produto não é um medicamento. Não exceder a recomendação diária de consumo indicada. Mantenha fora do alcance de crianças.', 26.43, 26.43, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rdw6-mc6y2k9vpbl8d8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1458515228%2F22093927151', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
