INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11913296009', 'Livro - Dom Quixote - Principis', 'Influenciado pelas gloriosas histórias de cavalaria, um homem já de idade avançada resolve se aventurar pelo mundo montado em um pangaré e em companhia de um simples camponês. Nesta adaptação, as aventuras de Dom Quixote e Sancho Pança exaltam a essência do Cavaleiro da Triste Figura. Editora: Principis Edição: 1, 2019 Autor: Miguel de Cervantes Idioma: Português Páginas: 304 Dimensões: L 15.90 x A 23.00 x E 1.70 ISBN: 9788594318671', 29.9, 29.9, NULL, 'Books & Magazines > Books > Action, Crime & Thrillers', 'https://cf.shopee.com.br/file/12bb24a7b33a61035248835ff122373e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F11913296009', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098703523', 'Rádio MP3 Player Som Automotivo Bluetooth Universal 1 Din USB Auxiliar First Option 6688T', '• Marca: First Option • Modelo: 6688T • Tamanho de montagem: 1 Din • Cor: Preto • Potência por canal (RMS): 4x25W • Alimentação: 12V • Controle Remoto: Sim • Conexão Bluetooth • Frente: Fixa • Relógio: Sim • Iluminação dos Botões: Vermelho • Reprodução áudio: MP3 e WMA • Leitura de Arquivos por Pasta: Não • Loud: Sim • Modos Reprodução: Aleatório, Repetir • Opções de Equalização: Pop, Rock e Clássico • Memória para Estação: 18 FM • Frequência FM (MHz): 87,5 - 108 • Busca automática de Estações: Sim • Leitor de CD: Não • Entrada USB para transferir dados: sim • Entrada Auxiliar: Sim, frontal • Bluetooth para Ligações: Sim • Bluetooth para Músicas: Sim • Microfone: Sim (embutido) • Saída Áudio (RCA): 2 • Saída Sub (RCA): Não Itens inclusos • 1 Som Automotivo 6688T • 1 Chicote de alimentação • 1 Manual (em português brasileiro) • 1 Controle Remoto Observação Não é aceita a devolução em caso de instalação incorreta por parte do cliente, por consequência, recomendamos que a instalação seja feita por um profissional competente na área para evitar transtornos, é vital que o produto seja instalado no painel do veículo desejado utilizando exclusivamente o chicote da embalagem. Dito isso, sinta-se livre para resolver suas dúvidas no nosso chat.', 61.0, 57.55, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbmjgkhs372090', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1562012414%2F22098703523', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18798274054', 'Amortecedor Porta-Malas Fiat Palio 1996 a 2005', '📦 1 Unidade de Amortecedor a Gás de Porta Malas 🚗 Aplicação: Fiat Palio 1996 a 2005 • Marca: First Option • Cor Preto • Comprimento (aberto): 48cm • Comprimento (fechado): 28cm • Medidas Exatamente iguais aos originais • Fabricado em Aço com mola e gás • Maior Segurança e Conforto • Fácil Instalação • Excelente Acabamento O amortecedor de mola a gás para a tampa no porta-malas é um componente responsável pela sustentação dessa tampa por auxiliar na abertura e amortecimento da mesma, evitando grandes impactos. Ele também funciona como uma espécie de limitador e suavizador de movimento, evitando desgaste e quebra das dobradiças. Seu formato é semelhante ao encontrado no sistema de suspensão do veículo, porém, normalmente tem diâmetros menores e comprimentos maiores. Esse modelo de amortecedor possui um movimento mais suave e constante por usar o gás nitrogênio injetado sob pressão, que garante mais durabilidade maior vida útil. Quando você abre a tampa do porta malas, o nitrogênio empurra uma haste metálica ligada a ela, o que facilita sua abertura, desse modo não é preciso fazer tanta força. Ao soltar a tampa, o nitrogênio mantém essa força e evita que a tampa feche sozinha. Quando você a força para baixo, comprime novamente o nitrogênio, levando a haste metálica de volta à posição inicial. A primeira ativação do amortecedor sempre será mais dura que o normal, após a primeira ele irá comprimir e estender suavemente como esperado! Para instalação, busque um profissional especializado, danos causados por parte do cliente não estão inclusos na garantia do produto! Se houver dúvidas sobre o produto, sinta-se livre para nos chamar no chat de atendimento ao cliente!', 40.0, 27.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbpmllz6mus9d4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1562012414%2F18798274054', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
