INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893606025', 'Blender Zoop Contrast Cadence Com 2 Jarras 220V', 'Blender Zoop Contrast Cadence Com 2 Jarras 220VBlender Cadence Contrast Collection – Prático, Multifuncional e Portátil Versátil, compacto e fácil de levar para qualquer lugar! Ideal para o preparo de bebidas geladas ou quentes, o Blender Cadence Contrast Collection tritura gelo e frutas congeladas com facilidade. Com design moderno, novas cores e alta potência, ele é perfeito para quem busca praticidade no dia a dia. Destaques do Produto Alta potência de 600W: Preparo rápido de sucos e vitaminas 2 jarras squeeze BPA Free de 500ml: Resistentes Com sobretampa para transporte Permitem beber direto da jarra Design compacto e desmontável: Fácil de lavar Cabe em pequenos espaços Botão ON/OFF com luz indicadora de funcionamento Base antiderrapante e trava de segurança: Mais estabilidade durante o uso Design exclusivo Cadence – Linha Contrast Collection Selo de Segurança: OCP SGS Dica de Uso Para melhor performance no preparo das bebidas, coloque os ingredientes na seguinte ordem dentro da garrafa: - Líquidos - Ingredientes frescos - Frutas congeladas - Iogurtes - Sorvetes Especificações Técnicas Modelo: BLD701-127 / BLD701-220 Tensão: 127V Ou 220V (Não é Bivolt) Código do Produto: BLD701 Potência: 600W Consumo: 0,6 kWh Dimensões (LxAxP): 130 x 365 x 130 mm Peso: 1,10 kg Garantia: 12 meses Código de Barras: 7898700211689 / 7898700211696 Informações Comerciais Código de Barras (DUN-14): 1 7898700211686 / 1 7898700211693 Classificação Fiscal / NCM: 8509.40.10 CEST: 24.041.00 Certificações: Inmetro Código da Certificação: SGS', 169.9, 159.9, NULL, 'Home Appliances > Kitchen Appliances > Juicers, Blenders & Soya Bean Machines', 'https://cf.shopee.com.br/file/sg-11134201-7rdxn-mbpieck5dt0c32', 'https://shope.ee/an_redir?or