INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55355409325', 'Soquete Sextavado 3/4'''' x 38mm (44861/138) - Tramontina Pro', 'O Soquete Sextavado 3/4'''' x 38mm (44861/138) - Tramontina Pro, é produzido com sistema Hyper Drive que melhora o acoplamento do produto ao parafuso ou porca, reduzindo as tensões geradas no aperto e prolongando a vida útil. Escolha o tamanho e perfil ideal para a sua necessidade e mãos á obra. Descrição do Produto: • Um grande avanço na produção dos soquetes é a introdução do conceito "Hyper Drive". Este novo perfil melhora o acoplamento do soquete na porca ou parafuso, reduzindo as tensões geradas no aperto, prolongando a vida do soquete e do elemento de fixação. • Soquete forjado em aço cromo vanádio e temperado. • Acabamento cromado. • DIN 3124. • Os soquetes são submetidos a testes rigorosos de torque e de dureza para atender a norma DIN 1711-1. • Afrouxar e apertar parafusos e porcas sextavados. • As ferramentas são produzidas e testadas conforme normas específicas. Referência: 44861/138. Cód. de Fábrica: 44861/138. Marca: Tramontina Pro.', 69.9, 69.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8260m-mjzzetwlz4sg7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F55355409325', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
