INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44478379183', 'Chave Combinada Com Catraca 16mm (42248/116) - Tramontina', 'A Chave Combinada Com Catraca 16mm (42248/116) - Tramontina, oferece eficiência nas tarefas mecânicas. Fabricada em aço cromo vanádio temperado, possui catraca de 90 dentes que garante giro preciso com mínimo movimento. O acabamento cromado e a catraca fosfatizada aumentam a proteção contra corrosão. Tramontina MASTER: a escolha certa para quem leva o trabalho a sério. Descrição do Produto: • Forjada em aço cromo vanádio e temperada. • Catraca com 90 dentes. • Cabeça usinada. • Acabamento cromado. • Catraca fosfatizada. • DIN 3113. • Tamanho: 16 mm. Referência: 42248/116. Cód. de Fábrica: 42248/116. Marca: Tramontina.', 55.9, 55.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8262x-mjzvmyxrbldza8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F44478379183', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193120557', 'Cuba Redonda de Vidro Temperada 30cm Pia para Lavabo e Banheiro', 'A LOPAZZI: Especialista em E-commerce, Transformando Ambientes com Estilo e Qualidade Com mais de uma década de experiência, a LOPAZZI é referência em e-commerce, oferecendo uma ampla gama de produtos selecionados para aprimorar seu espaço. Cubas, torneiras, válvulas, ralos e duchas - tudo com alto padrão e fino acabamento, seguindo as tendências de design mundial para proporcionar o toque especial que seu projeto merece. Cuba Redonda de 30: As cubas de vidro LOPAZZI são sinônimo de funcionalidade, resistência e modernidade. Perfeitas para complementar com sofisticação o ambiente do seu banheiro ou lavabo, elas se adaptam tanto a espaços amplos quanto a ambientes menores, proporcionando um aproveitamento máximo do espaço com graciosidade e leveza. Características: Altura: 12 cm Comprimento: 30 cm Profundidade: 30 cm Espessura: 8 mm Material: Vidro Modelo: Apoio Furo de Saída de Água: 4 cm Formato: Redonda Transforme seu ambiente com a elegância e a praticidade da nossa Cuba Redonda de 30. Adquira já a sua na LOPAZZI e descubra a diferença que um toque de qualidade pode fazer!', 228.9, 139.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/br-11134207-820l7-mqxcsqhwzn5x9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248180593%2F23193120557', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
