INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19374280628', 'Mochila Escolar Reforçada Masculina Estojo Faculdade', '📌CARACTERISTICA MOCHILA: • Bolso principal amplo e espaçoso • Bolsos laterais telados • Bolso frontal com espaço para armazenar pequenos objetos • Compartimento para notebook de até 15,5". 📝FICHA TÉCNICA: • Material: Poliéster 600D • Medidas (AxLxP): 42x30x20cm • Peso: 0,540kg • Capacidade: 25L • SKU: SW2102Z 📌CARACTERISTICA ESTOJO: • Estojo com 1 compartimentos para canetinhas, lápis; borracha, etc • Material de boa qualidade • Designer que permite usar em qualquer ocasião 📝FICHA TÉCNICA: • Material: 100 Algodão • Medição (A*L*P): 23x10x6 cm • Peso: 0,055g • Capacidade: 1,3 ⚠️CUIDADOS DE CONSERVAÇÃO: • Evite carregar excesso de peso • Embalar objetos com cantos vivos cortantes • Para limpeza, utilize apenas pano úmido ou esponja macia e sabão neutro. Não expor a luz do sol para secar • Não utilizar nenhum produto químico para limpeza • Conservar em local seco e arejado ❓QUEM SOMOS? A Oh My Bag, varejo constituído para a revenda de Mochilas, Bolsas e Malas de Viagem, vem se especializando no varejo online e se tornando referência em qualidade e confiança. Com abrangência em todo território nacional, a Oh My Bag com centro de abastecimento próprio e estoque permanente. Isso tem tornado a loja um sinônimo de tranquilidade na compra e agilidade na entrega.', 149.9, 149.9, NULL, 'Men Bags > Backpacks', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6obhdrwn8mfdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F441234830%2F19374280628', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55350898081', 'Lovito Kids Casual Vestido Fofo com Laço Primavera/verão Azul para menina L162LD192', '✅DESTAQUES -❤️Arco -❤️Camada em camadas -❤️Boa Textura -❤️Primavera e verão -❤️Cintura elástica ✅DESCRIÇÕES Estampa / Padrão:Quadriculado Estilo:fofo Tipo de vestido:Camadas Tamanho Plus:Não Material:Poliéster Composição:100% Poliéster Tipo de modelagem: Ajuste regular Transparência:Não Esticar:Não esticado Feito na China ✅O PACOTE INCLUI 1XVestir ✅INTRODUÇÃO LOVITO A Lovito é uma marca em crescimento que acredita no poder das meninas. Estamos comprometidos em oferecer opções de roupas fashion e acessíveis, para todos os estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, liberadora e fazer você se sentir incrível. Afinal, o melhor acessório para qualquer look é a autoconfiança! ✅NOTAS DE COMPRA Antes de comprar, dê uma olhadinha na tabela de medidas disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, converse conosco e responderemos o mais rápido possível.😊', 52.5, 37.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-823oa-moz7lr342a6mdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F426378412%2F55350898081', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298914242', 'Dinossauro de Brinquedo c/ Controle Anda Emite Som Maxi Toys', 'Dinossauro de Brinquedo Anda e Emite Som com Controle Remoto Velociraptor - Maxi Toys Prepare-se para mergulhar em uma aventura pré-histórica com o incrível Dinossauro de Controle Remoto da Maxi Toys! Com design inspirado no poderoso Velociraptor, este brinquedo promete encantar os pequenos com movimentos, luzes e sons que parecem de verdade. Produzido com material super resistente, o dinossauro possui textura realista que imita a pele do animal num tom azul vibrante com detalhes em amarelo. Seu grande diferencial está na boca articulada com iluminação em LED vermelho que imita fogo, deixando a brincadeira ainda mais emocionante. Graças às suas articulações flexíveis, o dinossauro não apenas se movimenta de forma automática, como também abre a boca, solta rugidos poderosos, balança o corpo e a cauda, com movimentos incrivelmente realistas que transportam as crianças direto para a era dos dinossauros. Além disso, a cauda destacável com encaixe prático deixa a montagem ainda mais divertida e envolvente. Ele possui bateria recarregável via cabo USB Tipo-C, garantindo muito mais economia e comodidade no dia a dia, e seu controle remoto é simples e fácil de usar, permitindo que os pequenos comandem todos os efeitos com praticidade. Necessário 2 pilhas AA (não inclusas). Mais do que um brinquedo, este dinossauro é uma experiência completa que estimula a criatividade, coordenação motora e interação social, garantindo longas horas de diversão para toda a família, transformando a brincadeira em uma aventura pré-histórica inesquecível. Principais Características: - Idade Recomendada: A Partir de 3 anos - Design e Textura Realista Inspirado no Velociraptor - Boca Articulada com Efeito de Luz em LED Vermelho que Imita Fogo - Efeitos Sonoros de Rugidos Poderosos para Maior Realismo - Movimento para Frente e para Trás com Rodas Embutidas Discretas - Corpo Todo Articulado para Movimentos mais Realistas - Corpo que Balança e Cauda Flexível que se Mexe Sozinha - Cauda Removível com Encaixe Prático - Articulações Móveis e Flexíveis - Fácil de montar e desmontar - Bateria Recarregável via Cabo USB Tipo-C (acompanha cabo) - Material Leve e Resistente - Estimula a Criatividade, Coordenação Motora e Interação Social - Controle Remoto Intuitivo e Estável Sem Interferências - Necessário 2 Pilhas AA 1,5V (Não Inclusas) - Aprovado Pelo Inmetro Especificações Técnicas: - Conteúdo da Embalagem: 1 Dinossauro de Brinquedo Velociraptor, 1 Cabo USB-C e Controle Remoto. - Dimensões do Produto (AxLxC): 11,0 x 13,0 x 28,0cm - Composição/Material: Plástico ABS - Alimentação: Dinossauro: Bateria Recarregável | Controle: 2 Pilhas AA 1,5v (Não Inclusas) - Peso do Produto: 0,225kgs - Garantia: 90 dias (Contra Defeitos de Fabricação Pelo Fabricante) - Certificação: INMETRO 009732/2024 - Código do Fabricante: 21875 - EAN: 7899403218753 - Marca: Maxi Toys Imagens Meramente Ilustrativas. As cores e estampas podem variar de acordo com o lote do fabricante.', 239.9, 99.99, NULL, 'Mom & Baby > Toys > Robot Toys', 'https://cf.shopee.com.br/file/sg-11134201-824ik-mefuwax0fs3k22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F828882817%2F22298914242', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
