INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18358574910', 'Mochila Spector Feminina Juvenil Executiva Material Resistente Escolar', '📌 CARACTERISTICAS: • Cor: Vermelha • Mochila Spector Original • Mochila com três compartimentos • Bolsos laterais • Divisórias internas • Alça de mão reforçada • Alças acolchoadas e ajustáveis • Forro em bolinhas douradas • Estampa de estrela e lua • Logo personalizado • Puxadores personalizado em dourado • Bolso principal com amplo espaço interno • Mochila autêntica, resistente e original 📝 FICHA TÉCNICA: • Modelo: Universe • Marca: Spector • Material: Poliéster Crinkle • Medidas Aproximada: (AxLxP): 46x37x15cm • Peso: 0,465kg • Litros: 25 litros • SKU: SP5492Z ⚠️ CUIDADOS DE CONVERSAÇÃO: • Evite carregar excesso de peso • Embalar objetos com cantos vivos cortantes • Para limpeza, utilize apenas pano úmido ou esponja macia e sabão neutro. Não expor a luz do sol para secar • Não utilizar nenhum produto químico para limpeza • Conservar em local seco e arejado ❓QUEM SOMOS? A Oh My Bag, varejo constituído para a revenda de Mochilas, Bolsas e Malas de Viagem, vem se especializando no varejo online e se tornando referência em qualidade e confiança. Com abrangência em todo território nacional, a Oh My Bag com centro de abastecimento próprio e estoque permanente. Isso tem tornado a loja um sinônimo de tranquilidade na compra e agilidade na entrega. Emitimos Nota Fiscal para Pessoa Física e Jurídica (CNPJ) Produtos a pronta entrega', 279.99, 279.99, NULL, 'Women Bags > Backpacks', 'https://cf.shopee.com.br/file/sg-11134201-22100-zw4yohjwy8iv72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F441234830%2F18358574910', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
