INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41727579334', 'Devocional Um ano com Timothy Keller | Leituras diárias selecionadas | Timothy Keller', 'Devocional Um ano com Timothy Keller | Leituras diárias selecionadas | Timothy Keller “O evangelho diz: somos mais pecaminosos e falhos em nós mesmos do que jamais ousamos acreditar e, ao mesmo tempo, somos mais amados e aceitos em Jesus Cristo do que jamais ousamos esperar.” Timothy Keller (1950-2023) Um ano com Timothy Keller convida você para uma jornada de 365 dias. A cada dia, uma nova reflexão extraída das obras mais amadas do autor aborda temas essenciais como oração, perdão, amor ao próximo, o sentido do trabalho e a esperança da ressurreição. Cada meditação se inicia com uma passagem bíblica para nortear o seu dia. Este devocional é o presente ideal, seja para quem está descobrindo Keller agora, seja para quem já admira há tempos seu discernimento. Autor: Timothy Keller Editora: Vida Nova Acabamento: Capa comum Dimensões: 16 x 23 Número de páginas: 416', 78.9, 78.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-81zw5-miq1g2l6f01z6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F41727579334', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49862031307', 'O Peregrino | John Bunyan', 'A mais famosa obra de ficção teológica já elaborada narra a jornada épica do personagem Cristão rumo à Cidade Celestial. Ao longo do árduo caminho em busca da salvação, o protagonista se depara com lugares fascinantes e criaturas emblemáticas, como o destruidor Apoliom e o gigante Desespero. Nesta aventura, Cristão experimenta uma série de tentações e outras provações ricamente detalhadas e enraizadas em passagens bíblicas, caracterizando este clássico como um dos mais lidos de todos os tempos. Título: O Peregrino | John Bunyan Autor: John Bunyan Páginas: 128 Formato: 16 x 24 cm Edição: 2022 Capa: Brochura Peso: 0,280 kg ISBN: 9786587817941 Editora: Grupo Online', 13.9, 13.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-823q1-mpayzbgfuryk98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F49862031307', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
