INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20198269714', 'Cordoalha Para Curral 7 Fios 6,4mm 200 Metros JST', '- A Cordoalha para Curral da JST possui resistência de 2500 kgf, é fabricada com 7 fios de aço zincado com camada pesada de zinco, que juntos, formam 6,4 mm de diâmetro, e oferece maior proteção contra a corrosão - É resistente, eficiente, muito durável, proporciona melhor acabamento ao curral e maior visibilidade do seu interior - É indicada para construção de curral de cordoalha e sua comercialização é feita em rolos com 200 metros - Além de todas as vantagens já mencionadas, a Cordoalha JST oferece ainda uma excelente vantagem econômica, tanto na construção quanto na manutenção dos currais, em comparação a um curral tradicional de madeira - Quando pensamos na construção de um curral é preciso ter em mente que este é o local onde é feito todo o manejo com o gado (pesagem, separação, vacinação, marcação), portanto, o curral precisa ser extremamente resistente, pois, é natural que o animal force o curral na tentativa de libertar-se deste local Especificações: • Comprimento: 200m • Carga Mínima de Ruptura: 2500 kgf • Diâmetro Total: 6,4mm (7 fios) • Camada de Zinco: Pesada • Peso: 19 kg', 921.88, 829.69, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/sg-11134201-821et-mgz2p3jhq9l6fa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F272868574%2F20198269714', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
