INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299679127', 'Sapato Couro Rafarillo Masculino Las Vegas 79352-03', 'Os calçados da linha Las Vegas, estilo esporte casual são sapatos de couro , com interior em PU, material antitranspirante e solado de borracha. É um sapato masculino com metal exclusivo, perfeito para diversas ocasiões. Confeccionados com abertura lateral com elástico, esta linha de sapato social masculino, é muito confortável e facilita o calce. Dicas de Conservação: 1 - Limpe sempre o sapato com uma escova de cerdas macias antes de aplicar qualquer produto de engraxe ou conservação 2 - Usar engraxe ou pomada sempre na tonalidade do couro 3 - Não usar nenhum produto químico para limpar o sapato, nem mesmo no solado, pois o produto químico pode descolar o solado e tirar o acabamento do couro, deixando-o descorado.', 314.9, 310.99, NULL, 'Men Shoes > Oxfords & Lace-Ups', 'https://cf.shopee.com.br/file/sg-11134201-7qvdn-lfsegjl5msg19b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F865304201%2F19299679127', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
